class TestAReasonIsNotADerivation(unittest.TestCase):
    """parameter_audit.py — the census of dials nobody priced.

    Jack, 2026-08-21: "I initially priced the staleness guard at 48h, then
    measured it... Age was the wrong margin; the hazard is deploys." The
    threshold was fine; the QUANTITY under it was wrong. That defect was found
    because someone looked. These tests exist so the next one is found because
    something checked.

    Every test below is an ATTACK on the auditor. The interesting ones are the
    three ways it could report a clean bill of health while being blind:
      * accept prose as a derivation (rubber stamp),
      * go quiet when it cannot tell what code is live (fail closed = excuse),
      * grade itself against the postmortem comments in its own source.
    """

    def _P(self, tmpdir):
        """parameter_audit pointed at a sandbox, never the real data/."""
        import importlib, parameter_audit as P
        importlib.reload(P)
        P.REGISTRY_PATH = tmpdir / "reg.json"
        P.BASELINE_PATH = tmpdir / "base.json"
        P.REPORT_PATH = tmpdir / "rep.json"
        return P

    def _tmp(self, name):
        d = Path(tempfile.mkdtemp(prefix="paramaudit_" + name))
        self.addCleanup(shutil.rmtree, d, ignore_errors=True)
        return d

    # -- the module actually finds a consequential dial ----------------------
    def test_a_threshold_that_gates_a_consequence_is_found(self):
        d = self._tmp("find")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "MAX_LOSS_PCT = 7.5\n"
            "def check(x):\n"
            "    if x > MAX_LOSS_PCT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        rep = P.run(root=d)
        keys = [e["key"] for e in rep["undocumented"]]
        self.assertIn("worker.py::MAX_LOSS_PCT", keys)
        self.assertEqual(1, rep["n_consequential"])

    def test_a_threshold_that_gates_only_a_log_line_is_not_a_policy(self):
        """False-positive control. If everything is consequential, the number
        the ratchet guards is noise and nobody will ever move it."""
        d = self._tmp("logonly")
        (d / "main.py").write_text("import quiet\n")
        (d / "quiet.py").write_text(
            "CHATTY_LIMIT = 12\n"
            "def check(x):\n"
            "    if x > CHATTY_LIMIT:\n"
            "        print('noisy')\n")
        P = self._P(d)
        rep = P.run(root=d)
        self.assertEqual(0, rep["n_consequential"])
        self.assertEqual(1, rep["n_gating_a_branch"],
                         "it is still a threshold — only the consequence is absent")

    # -- POISON PILL 1: prose must not pass for a measurement ----------------
    def test_a_rationale_without_a_measurement_does_not_count_as_derived(self):
        """POISON PILL. Register the parameter with a paragraph of confident,
        entirely reasonable prose and NO measurement. If the audit calls it
        documented, then this registry is a rubber stamp and the whole control
        degrades to 'does an explanation exist?' — a question one stale
        paragraph answers yes to, forever."""
        d = self._tmp("prose")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "MAX_LOSS_PCT = 7.5\n"
            "def check(x):\n"
            "    if x > MAX_LOSS_PCT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        P.REGISTRY_PATH.write_text(json.dumps({
            "worker.py::MAX_LOSS_PCT": {
                "value": 7.5,
                "rationale": "A cumulative cap is needed because a big change "
                             "split into small ones each passes the per-change "
                             "limit. Industry practice supports this range.",
            }}))
        rep = P.run(root=d)
        self.assertEqual(0, rep["n_documented"], "prose is not a derivation")
        self.assertEqual(1, rep["n_undocumented"])
        self.assertEqual(1, rep["n_asserted_not_measured"],
                         "and it must be named as an assertion, not silently dropped")

    def test_a_measurement_with_a_real_n_does_count(self):
        d = self._tmp("measured")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "MAX_LOSS_PCT = 7.5\n"
            "def check(x):\n"
            "    if x > MAX_LOSS_PCT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        P.REGISTRY_PATH.write_text(json.dumps({
            "worker.py::MAX_LOSS_PCT": {
                "value": 7.5,
                "measured": {"quantity": "drawdown at exit", "n": 412,
                             "on": "2026-08-21"},
            }}))
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_documented"])
        self.assertEqual(0, rep["n_undocumented"])

    def test_an_analytic_derivation_needs_no_sample_but_must_say_so(self):
        """A standard-error argument measures no sample. n=null is legitimate
        ONLY when the entry declares itself analytic — otherwise a missing n is
        indistinguishable from an entry nobody finished."""
        d = self._tmp("analytic")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "MIN_N = 200\n"
            "def check(x):\n"
            "    if x < MIN_N:\n"
            "        return 'not yet'\n")
        P = self._P(d)
        base = {"value": 200, "measured": {"quantity": "SE of a 97% rate",
                                           "n": None, "on": "2026-08-14"}}
        P.REGISTRY_PATH.write_text(json.dumps({"worker.py::MIN_N": base}))
        self.assertEqual(0, P.run(root=d)["n_documented"],
                         "n=null with no analytic flag is an unfinished entry")
        base["measured"]["analytic"] = True
        P.REGISTRY_PATH.write_text(json.dumps({"worker.py::MIN_N": base}))
        self.assertEqual(1, P.run(root=d)["n_documented"])

    # -- POISON PILL 2: a derivation that no longer describes the value ------
    def test_a_derivation_that_no_longer_matches_the_live_value_is_reported(self):
        """POISON PILL. Someone derives 7.5, records it, then edits the code to
        9.0. The registry now reads as due diligence for a number nobody ever
        priced — worse than an empty entry, because it stops anyone looking."""
        d = self._tmp("drift")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "MAX_LOSS_PCT = 9.0\n"
            "def check(x):\n"
            "    if x > MAX_LOSS_PCT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        P.REGISTRY_PATH.write_text(json.dumps({
            "worker.py::MAX_LOSS_PCT": {
                "value": 7.5,
                "measured": {"quantity": "drawdown at exit", "n": 412,
                             "on": "2026-08-21"},
            }}))
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_drifted"])
        self.assertEqual(9.0, rep["drifted"][0]["value"])
        self.assertEqual(7.5, rep["drifted"][0]["registered_value"])

    # -- POISON PILL 3: reachability must fail OPEN -------------------------
    def test_unreachable_code_is_reported_but_not_ratcheted(self):
        d = self._tmp("dormant")
        (d / "main.py").write_text("x = 1\n")          # imports nothing
        (d / "orphan.py").write_text(
            "DEAD_LIMIT = 42\n"
            "def check(x):\n"
            "    if x > DEAD_LIMIT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_consequential"])
        self.assertEqual(0, rep["n_consequential_reachable"])
        self.assertEqual(0, rep["n_undocumented"], "dormant must not inflate the ratchet")
        self.assertEqual(1, rep["n_dormant"], "but it must still be reported")

    def test_when_it_cannot_tell_what_is_live_it_audits_everything(self):
        """POISON PILL. Delete every scheduler source. The tempting behaviour is
        'no roots -> nothing is reachable -> 0 undocumented', a perfect green
        run produced by knowing nothing. Fail OPEN: not knowing what is live
        must never be a reason to excuse a live parameter."""
        d = self._tmp("noroots")
        (d / "orphan.py").write_text(
            "DEAD_LIMIT = 42\n"
            "def check(x):\n"
            "    if x > DEAD_LIMIT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        P.ENTRY_POINTS = ()            # no entry points, no crontab snapshot
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_undocumented"],
                         "with no way to tell what runs, everything is audited")
        self.assertEqual(0, rep["n_dormant"])

    def test_a_module_reached_only_through_another_module_counts_as_live(self):
        """risk_gate.py appears in no crontab line yet is plainly live. Direct
        reference count is not reachability; the transitive closure is."""
        d = self._tmp("transitive")
        (d / "main.py").write_text("import mid\n")
        (d / "mid.py").write_text("import deep\n")
        (d / "deep.py").write_text(
            "HEDGE_SLOTS = 2\n"
            "def check(x):\n"
            "    if x > HEDGE_SLOTS:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_consequential_reachable"])
        self.assertEqual(0, rep["n_dormant"])

    # -- POISON PILL 4: the auditor must not read its own prose --------------
    def test_a_comment_claiming_the_value_was_derived_proves_nothing(self):
        """POISON PILL. This repo's source is full of postmortem comments that
        say 'measured', 'derived', 'threshold', usually right next to the dial.
        A grep-based auditor would read those and mark the parameter done —
        grading itself against my own explanatory prose. The AST cannot see
        comments, and this test is what keeps it that way."""
        d = self._tmp("comment")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "# DERIVED 2026-08-21: measured n=412 observations, threshold\n"
            "# validated against the walk-forward harness. Fully priced.\n"
            "MAX_LOSS_PCT = 7.5\n"
            "def check(x):\n"
            "    if x > MAX_LOSS_PCT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        rep = P.run(root=d)
        self.assertEqual(1, rep["n_undocumented"],
                         "a comment is not the registry; prose must not confer credit")

    # -- the ratchet ---------------------------------------------------------
    def test_the_ratchet_regresses_when_a_new_unpriced_dial_appears(self):
        d = self._tmp("ratchet")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "A_LIMIT = 5\n"
            "def check(x):\n"
            "    if x > A_LIMIT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        first = P.run(root=d)
        self.assertEqual("SET", P.ratchet(first)["status"])
        (d / "worker.py").write_text(
            "A_LIMIT = 5\nB_LIMIT = 9\n"
            "def check(x):\n"
            "    if x > A_LIMIT:\n"
            "        submit_sell(x)\n"
            "    if x > B_LIMIT:\n"
            "        submit_sell(x)\n")
        second = P.ratchet(P.run(root=d))
        self.assertEqual("REGRESSED", second["status"])
        self.assertEqual(1, second["delta"])
        self.assertEqual(1, json.loads(P.BASELINE_PATH.read_text())["undocumented"],
                         "a regression must NOT quietly rewrite the baseline")

    def test_the_ratchet_tightens_when_a_dial_gets_priced(self):
        d = self._tmp("tighten")
        (d / "main.py").write_text("import worker\n")
        (d / "worker.py").write_text(
            "A_LIMIT = 5\n"
            "def check(x):\n"
            "    if x > A_LIMIT:\n"
            "        submit_sell(x)\n")
        P = self._P(d)
        P.ratchet(P.run(root=d))
        P.REGISTRY_PATH.write_text(json.dumps({
            "worker.py::A_LIMIT": {"value": 5, "measured": {
                "quantity": "breaches per week", "n": 88, "on": "2026-08-21"}}}))
        r = P.ratchet(P.run(root=d))
        self.assertEqual("IMPROVED", r["status"])
        self.assertEqual(0, json.loads(P.BASELINE_PATH.read_text())["undocumented"])

    # -- the separation of powers -------------------------------------------
    def test_the_auditor_can_never_edit_a_parameter(self):
        """AST-pinned, same rule as pick_gate_trial_review.py. Deriving a number
        and changing a live limit are different acts and the second is the
        Chairman's. An auditor that can rewrite config.py is not an auditor."""
        src = Path(__file__).parent / "parameter_audit.py"
        text = src.read_text()
        tree = ast.parse(text)

        # (a) every write must target one of this module's own named artefacts.
        #
        # CHAIRMAN_PATH was added when the module got a cron entry, because a
        # scheduled report with no consumer is this firm's oldest bug class.
        # Queuing a decision is not editing a parameter — but an allowlist that
        # grows once can grow again, so (a2) below now proves what the names
        # actually point at rather than trusting the name.
        allowed = ("BASELINE_PATH", "REPORT_PATH", "CHAIRMAN_PATH")
        for n in ast.walk(tree):
            if not isinstance(n, ast.Call):
                continue
            if getattr(n.func, "attr", None) not in ("write_text", "writelines",
                                                     "dump", "open"):
                continue
            seg = ast.get_source_segment(text, n) or ""
            self.assertTrue(any(a in seg for a in allowed),
                            "parameter_audit writes somewhere it must not: %s"
                            % seg[:120])

        # (a2) and every one of those names must resolve to a .json file inside
        # data/. This is the assertion that makes the allowlist safe to extend:
        # no matter what gets added later, a write target that is source code,
        # or that escapes data/, fails here. Resolved from the live module, not
        # parsed from the text, so a clever expression cannot dodge it.
        # Reloaded first: sibling tests in this class repoint these constants at
        # a sandbox, and reading them mid-suite would assert the fixture's paths
        # rather than the shipped ones.
        import importlib, parameter_audit as PA
        importlib.reload(PA)
        for nm in allowed:
            p = Path(getattr(PA, nm))
            self.assertEqual(".json", p.suffix,
                             "%s is a write target and must be data, not code" % nm)
            self.assertEqual("data", p.parent.name,
                             "%s must live under data/" % nm)

        # (b) it must not import the live config at all — you cannot edit what
        # you never hold. Asserted on the AST, NOT on the text: this module's
        # own docstring says the words "config.py" while explaining that it
        # refuses to touch it, and a substring check would fail on that
        # sentence. That is the same trap the audited code is built to dodge —
        # assert the claim form, never the word.
        for n in ast.walk(tree):
            if isinstance(n, ast.Import):
                for a in n.names:
                    self.assertNotEqual("config", a.name.split(".")[0])
            elif isinstance(n, ast.ImportFrom) and n.module:
                self.assertNotEqual("config", n.module.split(".")[0])

    def test_the_real_registry_is_valid_and_every_entry_is_measured(self):
        """The shipped registry has to obey the rule it enforces on others."""
        import parameter_audit as P
        importlib = __import__("importlib")
        importlib.reload(P)
        reg = P.load_registry()
        self.assertTrue(reg, "the registry must not be empty or unparseable")
        for k, rec in reg.items():
            if k.startswith("_"):
                continue
            self.assertTrue(P._is_measured(rec),
                            "registry entry %s cites no measurement" % k)

    def test_a_regression_reaches_a_human_and_a_healthy_run_does_not(self):
        """The verdict needs an owner, and the queue needs protecting from it.

        A cron job that prints REGRESSED at 03:00 and files nothing has told
        nobody. A cron job that files a row every run has told nobody either,
        just more expensively — the Chairman queue is at three figures.
        """
        d = self._tmp("escalate")
        P = self._P(d)
        P.CHAIRMAN_PATH = d / "chairman.json"

        healthy = {"ts": "2026-08-21T00:00:00+00:00", "n_drifted": 0,
                   "drifted": [], "undocumented": [],
                   "ratchet": {"status": "FLAT", "baseline": 5, "delta": 0}}
        self.assertFalse(P.escalate(healthy), "a FLAT run must not file a row")
        self.assertFalse(P.CHAIRMAN_PATH.exists())

        bad = dict(healthy, ratchet={"status": "REGRESSED", "baseline": 5,
                                     "delta": 2},
                   undocumented=[{"key": "a.py::X", "value": 9}])
        self.assertTrue(P.escalate(bad), "REGRESSED must reach the Chairman")
        rows = json.loads(P.CHAIRMAN_PATH.read_text())
        self.assertEqual(1, len(rows))
        self.assertEqual("parameter_audit", rows[0]["source"])
        self.assertIn("a.py::X", rows[0]["description"])

        # and the every-two-hours cron must not become 12 rows a day.
        self.assertFalse(P.escalate(bad), "same day, same condition -> one row")
        self.assertEqual(1, len(json.loads(P.CHAIRMAN_PATH.read_text())))

    def test_a_derivation_going_stale_escalates_even_when_the_count_is_flat(self):
        """POISON PILL for the ratchet: drift does not move the ratcheted count.

        A registered value silently ceasing to describe the live code leaves
        n_undocumented untouched — the dial still HAS a derivation, it is just a
        wrong one. Gating escalation on the ratchet alone would make the worst
        case the quiet one.
        """
        d = self._tmp("drift_escalates")
        P = self._P(d)
        P.CHAIRMAN_PATH = d / "chairman.json"
        rep = {"ts": "2026-08-21T00:00:00+00:00", "n_drifted": 1,
               "drifted": [{"key": "risk.py::CAP", "value": 40,
                            "registered_value": 20}],
               "undocumented": [],
               "ratchet": {"status": "FLAT", "baseline": 5, "delta": 0}}
        self.assertTrue(P.escalate(rep))
        rows = json.loads(P.CHAIRMAN_PATH.read_text())
        self.assertEqual("HIGH", rows[0]["severity"],
                         "a stale derivation reads as due diligence and is not")
        self.assertIn("risk.py::CAP", rows[0]["description"])

    def test_a_host_that_cannot_answer_says_unknown_not_none_found(self):
        """POISON PILL: outside a git checkout the census must not claim zero.

        The VM is not a checkout — deploy.sh rsyncs with --exclude=.git/ — so
        `git ls-files` fails there. An empty list would read as "no host-local
        files", the confident wrong answer; None reads as "cannot tell", which
        is what is actually known. Same rule as reachable_modules failing open.
        """
        d = self._tmp("nogit")
        P = self._P(d)
        (d / "a.py").write_text("X = 5\nif n > X:\n    status = 'bad'\n")
        files = P.python_files(d)
        self.assertTrue(files, "fixture must produce at least one module")
        self.assertIsNone(P.host_local_modules(files, d),
                          "no .git present, so the honest answer is unknown, "
                          "not an empty list")

    def test_a_file_git_does_not_track_is_named_as_host_local(self):
        """And inside a checkout it must actually find the untracked file."""
        d = self._tmp("withgit")
        P = self._P(d)
        (d / "tracked_thing.py").write_text("A = 7\n")
        (d / "scratch_thing.py").write_text("B = 9\n")
        subprocess.run(["git", "init", "-q"], cwd=str(d), check=True)
        subprocess.run(["git", "add", "tracked_thing.py"], cwd=str(d), check=True)
        got = P.host_local_modules(P.python_files(d), d)
        self.assertIsNotNone(got)
        self.assertIn("scratch_thing.py", got)
        self.assertNotIn("tracked_thing.py", got)

    def test_a_terminated_hosts_provisioning_code_is_not_a_firm_parameter(self):
        """oracle_setup/ belongs to an instance TERMINATED 2026-07-27.

        It is gitignored, so it lives on the Mac and not the VM; scanning it
        charged the audit dormant 'parameters' from a machine that no longer
        exists and made the two hosts disagree for a reason unrelated to drift.
        """
        import parameter_audit as P
        self.assertIn("oracle_setup", P.SKIP_DIRS)
        d = self._tmp("skipdead")
        (d / "oracle_setup").mkdir()
        (d / "oracle_setup" / "deploy.py").write_text(
            "TIMEOUT = 45\nif t > TIMEOUT:\n    status = 'fail'\n")
        (d / "real.py").write_text("LIMIT = 12\nif x > LIMIT:\n    status = 'no'\n")
        names = {p.name for p in P.python_files(d)}
        self.assertIn("real.py", names)
        self.assertNotIn("deploy.py", names)


class TestAPromotionGateThatNeverBlockedAnything(unittest.TestCase):
    """The v5 promotion gate compared production against a number it never had.

    `ml_model_v5.train()` decided whether a freshly-trained model should replace
    data/model.pkl with:

        prod_auc = float(prod_bundle.get("ensemble_auc_val", 0.0))
        ...
        if force or ens_auc >= prod_auc + PROMO_DELTA:

    reading the incumbent's score out of the model PICKLE. Whether that key is
    in the pickle depends on which trainer last wrote it — v5 embeds it, v1 and
    v3 do not — so the gate's answer depended on the incumbent's provenance
    rather than on the incumbent. When the key was absent the fallback was 0.0,
    and 0.0 makes `>= prod_auc + 0.003` true for every candidate that has ever
    existed. The gate did not "sometimes fail open"; on the always-on host it
    was open every night it ran, and the log says so in its own words:
    "current production AUC = 0.0000", five nights out of five.

    Promoted on those five nights, by single-split val AUC: 0.5264, 0.5264,
    0.4788, 0.4090, 0.4958. Three of the five are below a coin flip.

    Same species as `fallback-that-means-act` (the constant a degraded read
    substitutes IS a decision) and `unknown-verb-approved-nothing` (66 days of
    orders approved by an initialiser). The gate is now a pure function so it
    can be interrogated without a 20-minute training run — the reason no test
    ever caught this is that the check lived as one inline `if` in the middle of
    400 lines of model fitting.
    """

    def setUp(self):
        from predictive_model import ml_model_v5 as v5
        self.v5 = v5

    def test_an_unreadable_incumbent_refuses_to_promote(self):
        """THE POISON PILL. None must mean refuse, never 'compare against zero'."""
        block = self.v5._promotion_block(cand_auc=0.62, prod_auc=None)
        self.assertTrue(
            block,
            "a candidate was cleared for production while the incumbent's AUC "
            "was unreadable — this is the exact bug, restored",
        )
        self.assertIn("unreadable", block.lower())
        # and the discriminating half: the SAME candidate against a real, weak
        # incumbent must be allowed. Otherwise this test would also pass against
        # a gate that simply refuses everything.
        self.assertEqual("", self.v5._promotion_block(cand_auc=0.62, prod_auc=0.55))

    def test_zero_is_not_a_neutral_incumbent(self):
        """0.0 is the value that admits everything; it must never be a default.

        Guarding the literal, not just the behaviour: if a future edit restores
        `.get(..., 0.0)` the gate silently reopens and every other test here
        still passes, because 0.0 is a perfectly valid float to compare against.
        """
        import inspect
        src = inspect.getsource(self.v5._incumbent_auc)
        tree = ast.parse(src.strip())
        for node in ast.walk(tree):
            if not isinstance(node, ast.Call):
                continue
            fn = node.func
            if isinstance(fn, ast.Attribute) and fn.attr == "get" and len(node.args) > 1:
                default = node.args[1]
                self.assertFalse(
                    isinstance(default, ast.Constant)
                    and isinstance(default.value, (int, float))
                    and not isinstance(default.value, bool),
                    "_incumbent_auc substitutes a number for a failed read; the "
                    "only safe substitute is None",
                )

    def test_the_incumbent_is_read_from_the_source_of_truth(self):
        """CLAUDE.md: get_model_metrics() is the only place an AUC comes from."""
        import inspect
        src = inspect.getsource(self.v5._incumbent_auc)
        called = {
            n.func.id for n in ast.walk(ast.parse(src.strip()))
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
        }
        self.assertIn(
            "get_model_metrics", called,
            "the incumbent's AUC must come from model_metrics, not from whatever "
            "happens to be inside the pickle",
        )

    def test_nothing_at_or_below_a_coin_flip_reaches_production(self):
        """An absolute floor, because a relative gate cannot express this.

        If the incumbent is itself 0.45, then 0.48 "beats production" and a
        relative-only gate promotes an anti-predictive model with a clean
        conscience. The right answer there is to keep neither.
        """
        self.assertTrue(self.v5._promotion_block(cand_auc=0.48, prod_auc=0.45))
        self.assertTrue(self.v5._promotion_block(cand_auc=0.50, prod_auc=0.10))
        self.assertEqual("", self.v5._promotion_block(cand_auc=0.60, prod_auc=0.45))

    def test_the_two_sides_of_the_comparison_are_the_same_metric(self):
        """Walk-forward against walk-forward, never holdout against walk-forward.

        v5 computes both: `ensemble_auc_val` (one 80/20 split, optimistic) and
        `wf_cv_mean_auc` (embargoed walk-forward). model_metrics headlines the
        walk-forward. Feeding the candidate's holdout into a comparison against
        the incumbent's walk-forward is two correct halves making one meaningless
        comparison, and it is biased in one direction — toward replacing
        production every single night.
        """
        import inspect
        src = inspect.getsource(self.v5.train)
        assigns = [n for n in ast.walk(ast.parse(src.strip()))
                   if isinstance(n, ast.Assign)
                   and any(isinstance(t, ast.Name) and t.id == "cand_auc"
                           for t in n.targets)]
        self.assertEqual(1, len(assigns), "cand_auc should be assigned exactly once")
        keys = {n.value for n in ast.walk(assigns[0].value)
                if isinstance(n, ast.Constant) and isinstance(n.value, str)}
        self.assertIn(
            "wf_cv_mean_auc", keys,
            "the promoted-or-not decision must be made on the embargoed "
            "walk-forward number, not on the single-split holdout",
        )
        self.assertNotIn("ensemble_auc_val", keys)

    def test_force_is_the_only_override_and_it_is_explicit(self):
        self.assertEqual("", self.v5._promotion_block(None, None, force=True))
        self.assertEqual("", self.v5._promotion_block(0.10, 0.90, force=True))


class TestOnlyASanctionedTrainerWritesTheProductionModel(unittest.TestCase):
    """data/model.pkl is a live artifact; the set of things that may write it is small.

    Found while removing the dead ml_chain_r*.py experiment chain. Those files
    were dormant — on no scheduler, imported by nothing — but two of them
    (`ml_chain_r6.py`, `ml_chain_r7.py`) ended their promote() with:

        pickle.dump(d, open(PROD, 'wb'))          # data/model_v2.pkl
        shutil.copy(PROD, BASE / 'data' / 'model.pkl')

    so `python3 ml_chain_r7.py` — one command, no flag, no confirmation — would
    have replaced the live production model with a July-3-shaped bundle. That
    bundle has no `lt_model` or `lt_scaler`, so the long-term model the pipeline
    reads would have silently vanished, and none of the chain files write
    model_meta.json, so model_metrics.get_model_metrics() would have gone on
    reporting the AUC of a model that no longer existed on disk. The gate
    deciding all this was a hardcoded `PROD_VAL_AUC = 0.6068` — one val split,
    against an honest walk-forward std of ±0.073.

    "Dormant" is not a safety property. It describes the scheduler, not the file.
    """

    SANCTIONED = {
        # The trainers. Each writes model_meta.json in the same breath, so the
        # artifact and the firm's description of it move together.
        "predictive_model/ml_model.py",
        "predictive_model/ml_model_v2.py",
        "predictive_model/ml_model_v3.py",
        "predictive_model/ml_model_v4.py",
        "predictive_model/ml_model_v5.py",
    }

    # Calls that can put bytes on disk. Over-inclusive on purpose: `copy(A, B)`
    # is counted whichever end names the target, because resolving argument
    # position through shutil/pickle/Path aliases is exactly the kind of
    # cleverness that makes a control quietly stop matching. An over-inclusive
    # sweep costs one allowlist entry; an under-inclusive one costs a silent
    # false GREEN, which is what this whole class exists to prevent.
    _MUTATORS = {"copy", "copyfile", "copy2", "move", "dump", "open",
                 "write_bytes", "replace", "rename", "save"}

    def _writers_of(self, target: str):
        """Every module containing a filesystem-mutating call naming `target`.

        The literal never appears in the call itself — the trainers write
        `shutil.copy(V5_PATH, MODEL_PATH)`, where MODEL_PATH is a module-level
        `DATA_DIR / "model.pkl"`. A sweep that only looked for the string
        constant inside the call found nothing at all, which is precisely the
        failure this class's non-vacuity assertion is there to catch. So resolve
        the names first, then look for either the name or the literal.
        """
        root = Path(__file__).parent
        writers, examined = set(), 0
        for path in sorted(root.rglob("*.py")):
            if any(part in ("__pycache__", "backups", ".git", "venv", "node_modules")
                   for part in path.parts):
                continue
            rel = str(path.relative_to(root))
            examined += 1
            try:
                tree = ast.parse(path.read_text())
            except (SyntaxError, UnicodeDecodeError):
                continue

            def _names_the_target(node):
                return any(isinstance(s, ast.Constant) and isinstance(s.value, str)
                           and s.value.rstrip("/").endswith(target)
                           for s in ast.walk(node))

            aliases = {t.id for n in ast.walk(tree) if isinstance(n, ast.Assign)
                       for t in n.targets
                       if isinstance(t, ast.Name) and _names_the_target(n.value)}

            for node in ast.walk(tree):
                if not isinstance(node, ast.Call):
                    continue
                fn = node.func
                name = (fn.attr if isinstance(fn, ast.Attribute)
                        else fn.id if isinstance(fn, ast.Name) else "")
                if name not in self._MUTATORS:
                    continue
                # `open(path, "rb")` is a read. This is the one argument-position
                # inference worth making: without it the sweep flags every module
                # that merely LOADS the production model, and a control that
                # cries wolf on readers gets its allowlist padded until it stops
                # meaning anything.
                if name == "open":
                    modes = [a.value for a in node.args[1:]
                             if isinstance(a, ast.Constant) and isinstance(a.value, str)]
                    if modes and all("r" in m and "+" not in m for m in modes):
                        continue
                hits = _names_the_target(node) or any(
                    isinstance(s, ast.Name) and s.id in aliases
                    for s in ast.walk(node))
                if hits:
                    writers.add(rel)
        return writers, examined

    def test_no_unsanctioned_module_writes_model_pkl(self):
        writers, examined = self._writers_of("model.pkl")
        self.assertGreater(examined, 100, "the sweep examined almost nothing")
        # Non-vacuous: this only means something if it can actually see a writer.
        self.assertTrue(
            writers & self.SANCTIONED,
            "the sweep found no sanctioned writer either — it is matching "
            "nothing, so its silence about unsanctioned writers proves nothing",
        )
        rogue = writers - self.SANCTIONED
        self.assertEqual(
            set(), rogue,
            "these modules write the live production model without being one of "
            "the sanctioned trainers: %s. If one of them is legitimate, add it "
            "to SANCTIONED here AND make it write model_meta.json in the same "
            "operation — an artifact that moves without its metadata makes "
            "get_model_metrics() describe a model that is no longer on disk."
            % sorted(rogue),
        )


class TestTheRepoRootIsNeverPutOnThePath(unittest.TestCase):
    """No module in this tree may prepend the repo root to sys.path.

    `institutional-tracker/feature_engineer.py` did:

        sys.path.insert(0, str(Path(__file__).parent.parent))

    copied verbatim from `predictive_model/feature_engineer.py`, where the file
    is one level deeper and `.parent.parent` correctly names this directory. At
    the top level the same expression names the REPO ROOT, and the repo root
    still carries two pre-migration relics from 2026-03-21 — `main.py` (13KB
    against the live 106KB) and `config.py` (6KB against the live 12KB). Once
    the root is sys.path[0] they win every subsequent `import main` /
    `import config` in that process.

    Nothing raised. The suite reported nine ERRORs in TestStateRoundTrip and
    TestSignalSourceHelpers — classes with no connection to feature engineering
    — saying "cannot import name 'ORG' from 'config'", which is what a March
    main.py asking a July config.py for a symbol it no longer exports looks
    like. That is the benign version. The malign version is a production
    process that happens to import feature_engineer before config and then
    trades on five-month-old ALPACA credentials and five-month-old risk limits
    with no error at all, on whichever host imports in that order — which makes
    it a `host_divergence_is_a_bug_class` failure waiting for an ordering
    change rather than a test-only annoyance.

    Two halves, because either alone is weak:
      1. static — no top-level module may name the parent of this directory;
      2. live — with the shadowing modules enumerated from disk, importing the
         real feature_engineer in a fresh interpreter must still resolve every
         one of them inside institutional-tracker/.
    Half 2 is what actually protects the firm; half 1 is what tells you which
    line to fix when half 2 goes red.
    """

    ROOT = Path(__file__).resolve().parent

    def test_no_top_level_module_prepends_the_parent_directory(self):
        import ast as _ast

        offenders, examined, path_calls = [], 0, 0
        for py in sorted(self.ROOT.glob("*.py")):      # top level ONLY: one level
            examined += 1                              # deeper .parent.parent is right
            try:
                tree = _ast.parse(py.read_text())
            except Exception:
                continue
            for node in _ast.walk(tree):
                if not isinstance(node, _ast.Call):
                    continue
                fn = node.func
                if not (isinstance(fn, _ast.Attribute)
                        and fn.attr in ("insert", "append")
                        and isinstance(fn.value, _ast.Attribute)
                        and fn.value.attr == "path"
                        and isinstance(fn.value.value, _ast.Name)
                        and fn.value.value.id == "sys"):
                    continue
                path_calls += 1
                arg = _ast.dump(_ast.Module(body=[_ast.Expr(node)], type_ignores=[]))
                # `Path(__file__).parent.parent` shows up as two chained
                # attribute accesses named 'parent'; one is this directory and
                # is fine, two is the repo root and is not.
                if arg.count("attr='parent'") >= 2:
                    offenders.append(f"{py.name}:{node.lineno}")

        self.assertGreater(examined, 100,
                           "the sweep examined almost nothing — it is not looking "
                           "at this tree")
        self.assertGreater(path_calls, 0,
                           "the sweep matched no sys.path call anywhere, so finding "
                           "no offender proves nothing about the codebase")
        self.assertEqual(
            [], offenders,
            "these top-level modules put the REPO ROOT on sys.path, where "
            "pre-migration main.py/config.py shadow the live ones: %s. Use "
            "Path(__file__).parent — this directory is already what the "
            "predictive_model.* imports need." % offenders)

    def test_importing_feature_engineer_does_not_reroute_later_imports(self):
        shadowed = sorted(
            {p.stem for p in self.ROOT.parent.glob("*.py")}
            & {p.stem for p in self.ROOT.glob("*.py")}
        )
        if not shadowed:
            self.skipTest("no repo-root module shares a name with this tree — "
                          "nothing can be shadowed on this host (the VM gets an "
                          "rsync of institutional-tracker/ only)")

        probe = (
            "import importlib.util, json, sys\n"
            "sys.path.insert(0, %r)\n"
            "import feature_engineer\n"
            "print(json.dumps({m: (importlib.util.find_spec(m).origin or '')\n"
            "                  for m in %r}))\n" % (str(self.ROOT), shadowed)
        )
        r = subprocess.run([sys.executable, "-c", probe],
                           capture_output=True, text=True, timeout=180)
        self.assertEqual(0, r.returncode,
                         "the probe could not import feature_engineer: %s"
                         % r.stderr[-800:])
        where = json.loads(r.stdout.strip().splitlines()[-1])
        for mod, origin in sorted(where.items()):
            self.assertTrue(
                origin.startswith(str(self.ROOT) + os.sep),
                "after importing feature_engineer, `import %s` resolves to %s — "
                "the repo root is ahead of institutional-tracker on sys.path and "
                "a pre-migration relic is now the live module" % (mod, origin))


class TestTheResolverLooksUpWhatCanActuallyHaveAnAnswer(unittest.TestCase):
    """A finite lookup budget spent in the wrong order is a silent data loss.

    `resolve_settlements` had a 400-lookup budget and took `pending[:400]` in
    LEDGER order — by when a row was recorded, which says nothing about whether
    Kalshi has published an outcome. Measured on the VM on 2026-08-22: 2,517
    pending rows, so 16% examined per run, and 465 rows that had CLOSED, were
    unsettled, and had never once been looked up. Six probed live against the
    API were all `status=finalized` with a result available. The verdict gate the
    whole Kalshi campaign waits on was starved of outcomes that already existed
    and cost nothing to read.

    Nothing errored, nothing was empty, and every individual number the sector
    reported was true — which is why only an invariant catches it.
    """

    def _kc(self):
        import kalshi_calibration
        return kalshi_calibration

    def test_a_closed_row_is_never_starved_by_newer_unclosed_rows(self):
        kc = self._kc()
        budget = 50
        # The shape of the real ledger: a long head of recently-recorded rows
        # that close far in the future, and one older row that closed days ago.
        rows = [{"ticker": "FUTURE-%d" % i, "close_time": "2026-12-%02dT00:00:00Z"
                 % ((i % 28) + 1)} for i in range(budget * 4)]
        rows.insert(3 * budget, {"ticker": "CLOSED-LONG-AGO",
                                 "close_time": "2026-08-01T00:00:00Z"})

        selected, n_pending = kc.resolve_candidates(rows, budget)

        # Non-vacuity: the fixture has to actually overflow the budget, or this
        # test would pass on a list that never needed prioritising at all.
        self.assertEqual(len(selected), budget)
        self.assertGreater(n_pending, budget,
                           "fixture does not exceed the lookup budget, so it "
                           "cannot demonstrate prioritisation")

        tickers = [r["ticker"] for r in selected]
        self.assertIn("CLOSED-LONG-AGO", tickers,
                      "a row that closed weeks ago was left out of the lookup "
                      "batch while %d rows closing in December were included — "
                      "the queue is ordered by record time, not by whether an "
                      "answer can exist" % len(tickers))
        self.assertEqual(tickers[0], "CLOSED-LONG-AGO",
                         "the oldest-closing row must be looked up first")

    def test_the_queue_is_sorted_and_not_filtered_to_already_closed(self):
        """The plausible version of this fix throws away most real settlements.

        209 of the 341 rows settled so far settled BEFORE their close_time
        (median -32.2h) because Kalshi finalises these markets early. Filtering
        to `close_time < now` would look like a tightening and would silently
        discard the majority of the sample.
        """
        kc = self._kc()
        far = "2099-01-01T00:00:00Z"
        rows = [{"ticker": "T%d" % i, "close_time": far} for i in range(5)]
        selected, n_pending = kc.resolve_candidates(rows, 400)
        self.assertEqual(n_pending, 5)
        self.assertEqual(len(selected), 5,
                         "rows whose close_time has not passed were dropped from "
                         "the lookup queue; early settlement is the NORM on these "
                         "markets, so a filter loses most of the evidence")

    def test_settled_and_voided_rows_never_consume_the_budget(self):
        kc = self._kc()
        rows = ([{"ticker": "S%d" % i, "settled": True} for i in range(10)]
                + [{"ticker": "V%d" % i, "voided": True} for i in range(10)]
                + [{"ticker": "OPEN", "close_time": "2026-09-01T00:00:00Z"}])
        selected, n_pending = kc.resolve_candidates(rows, 400)
        self.assertEqual([r["ticker"] for r in selected], ["OPEN"])
        self.assertEqual(n_pending, 1)

    def test_a_permanently_stuck_row_cannot_monopolise_the_front_of_the_queue(self):
        """The fix's own failure mode, pinned.

        Ordering by close_time puts a ticker that is voided or delisted upstream
        at position 0 forever, burning one lookup every run. Stuck rows never
        leave, so the count only grows, and at a trickle it reaches the budget
        within a year and starves the queue again — in a new shape, with every
        individual number still true.
        """
        kc = self._kc()
        stuck = {"ticker": "DELISTED", "close_time": "2026-01-01T00:00:00Z",
                 "unresolved_looks": kc.STUCK_AFTER_LOOKS}
        fresh = {"ticker": "RECENTLY-CLOSED", "close_time": "2026-08-20T00:00:00Z"}
        selected, _ = kc.resolve_candidates([stuck, fresh], 400)

        self.assertEqual(selected[0]["ticker"], "RECENTLY-CLOSED",
                         "a row asked %d times since closing with no result "
                         "still sorts ahead of a fresh closed row"
                         % kc.STUCK_AFTER_LOOKS)
        self.assertIn("DELISTED", [r["ticker"] for r in selected],
                      "the stuck row was DROPPED rather than demoted — that "
                      "biases the sample toward the outcomes we could see, "
                      "which is the thing resolve_settlements forbids")

    def test_a_row_one_look_below_the_threshold_is_not_demoted(self):
        """Non-vacuity: the demotion must be the threshold doing work, not the
        mere presence of the field."""
        kc = self._kc()
        almost = {"ticker": "OLD-BUT-OK", "close_time": "2026-01-01T00:00:00Z",
                  "unresolved_looks": kc.STUCK_AFTER_LOOKS - 1}
        fresh = {"ticker": "NEWER", "close_time": "2026-08-20T00:00:00Z"}
        selected, _ = kc.resolve_candidates([fresh, almost], 400)
        self.assertEqual(selected[0]["ticker"], "OLD-BUT-OK")

    def test_looks_before_close_do_not_count_toward_stuck(self):
        """Otherwise the demotion lands on the 30-90d horizon the gate waits on.

        Before a contract closes, "not resolved" is the expected answer and
        carries no information. Counting it would trip the threshold on day 10
        for a row that closes in 80 days, penalising a long-dated contract for
        being long-dated.
        """
        kc = self._kc()
        now = datetime.now(timezone.utc)
        future = (now + timedelta(days=80)).isoformat().replace("+00:00", "Z")
        past = (now - timedelta(days=3)).isoformat().replace("+00:00", "Z")
        self.assertFalse(kc._has_closed({"close_time": future}, now))
        self.assertTrue(kc._has_closed({"close_time": past}, now))
        self.assertFalse(kc._has_closed({"close_time": "not-a-date"}, now),
                         "an unparseable close_time must not be treated as "
                         "closed, or the row gets demoted on a date nobody read")
        self.assertFalse(kc._has_closed({}, now))

    def test_a_row_with_no_close_time_sorts_last_but_is_not_dropped(self):
        """Unorderable is not the same as ineligible."""
        kc = self._kc()
        rows = [{"ticker": "NOCLOSE"},
                {"ticker": "BADCLOSE", "close_time": "not-a-date"},
                {"ticker": "REAL", "close_time": "2026-08-01T00:00:00Z"}]
        selected, _ = kc.resolve_candidates(rows, 400)
        self.assertEqual(selected[0]["ticker"], "REAL")
        self.assertEqual(len(selected), 3,
                         "a row with an unreadable close_time was dropped from "
                         "the queue entirely, so it can never settle")


class TestTheWatchdogDoesNotAssertACauseItNeverMeasured(unittest.TestCase):
    """RESOLUTION_STALLED used to state that `--resolve` was not running.

    On 2026-08-22 that sentence was false: `--resolve` had run 2.8h earlier and
    settled 31 rows, while 43 of the 44 overdue rows had never entered its
    lookup window. The alarm sent its reader to restart a healthy cron job. A
    finding may report what it measured; the moment it names a cause it did not
    check, it is worse than silence because it is actively misleading.
    """

    def _w(self):
        import kalshi_watchdog
        return kalshi_watchdog

    BASE = {"collector": {"role": "collector", "evidence": "test"},
            "stall_hours": 1.0, "n_examined": 2405, "newest_record": "2026-08-22T14:00Z",
            "overdue_unsettled": 44, "oldest_overdue": "2026-08-19T14:29Z",
            "strata": {}, "unreachable": [], "binding_gate": "2026-09-21"}

    def _detail(self, **over):
        w = self._w()
        proj = dict(self.BASE, **over)
        found = [f for f in w.evaluate(proj, None) if f["kind"] == "RESOLUTION_STALLED"]
        self.assertEqual(len(found), 1, "RESOLUTION_STALLED did not fire on a "
                                        "projection built to trip it")
        return found[0]["detail"]

    def test_it_does_not_claim_resolve_is_dead_while_resolve_is_demonstrably_alive(self):
        detail = self._detail(resolver_last_settled_hours=2.8,
                              resolver_settled_24h=31,
                              overdue_beyond_lookup_window=43,
                              resolve_pending=2517, resolve_budget=400)
        self.assertNotIn("--resolve is not running", detail)
        self.assertIn("starved", detail,
                      "the real cause — a queue the resolver never reaches — is "
                      "not named, so the reader is left with the wrong fix")
        self.assertIn("2517", detail.replace(",", ""))

    def test_a_quiet_resolver_is_reported_as_consistent_with_not_proof_of_death(self):
        """Absence of settled_at is not evidence the job is dead.

        A run that found nothing ready to settle leaves exactly the same trace
        as a run that never happened, so this branch must defer rather than
        conclude — otherwise the fix is the same wrong fix in the other
        direction.
        """
        detail = self._detail(resolver_last_settled_hours=200.0,
                              resolver_settled_24h=0,
                              overdue_beyond_lookup_window=0)
        self.assertIn("CONSISTENT with", detail)
        self.assertIn("does not prove it", detail)

    def test_an_alive_resolver_reaching_every_row_points_upstream(self):
        detail = self._detail(resolver_last_settled_hours=2.0,
                              resolver_settled_24h=12,
                              overdue_beyond_lookup_window=0)
        self.assertIn("inside its lookup window", detail)
        self.assertNotIn("starved", detail)

    def test_the_watchdog_imports_the_budget_rather_than_restating_it(self):
        """A supervisor carrying its own copy of the rule it supervises goes
        stale the day the rule moves, while its numbers stay plausible."""
        import ast
        w = self._w()
        src = Path(w.__file__).read_text()
        literals = [n.value for n in ast.walk(ast.parse(src))
                    if isinstance(n, ast.Constant) and n.value == 400]
        self.assertEqual(literals, [],
                         "kalshi_watchdog hardcodes the literal 400; the lookup "
                         "budget must come from kalshi_calibration."
                         "RESOLVE_MAX_LOOKUPS")


class TestThePremiseVerdictSpeaksOnlyForTheHorizonsItSampled(unittest.TestCase):
    """A verdict must not be wider than the sample that produced it.

    2026-08-22: draining the resolver backlog took the current-rule settled
    sample from 63 to 929 and `is_premise_alive` flipped ALIVE -> DEAD. The
    finding was real. But 923 of the 929 rows were 1-7d contracts, and the
    verdict was phrased as a judgement on a rule that trades 1-90d, whose 7-30d
    and 30-90d bands held 1 and 5 observations.

    `is_edge_proven` refuses a verdict in exactly that situation and explains
    why in a comment: settlements arrive shortest-horizon-first, so a sample
    that clears a size threshold on short-dated rows is "perfectly real and
    completely inapplicable" to long ones. The argument belongs to the sample,
    not to the reader, and it had been applied to only one of the two gates.
    """

    def _rows(self, n, days, price=0.99, hit_rate=0.5, rule=None):
        import kalshi_calibration as kcal
        rule = rule or kcal.SELECTION_RULE
        hits = int(round(n * hit_rate))
        return [{"settled": True, "outcome": 1 if i < hits else 0,
                 "market_price": price, "days_to_close": days,
                 "selection_rule": rule} for i in range(n)]

    def test_a_dead_verdict_from_one_band_names_the_bands_it_did_not_test(self):
        import kalshi_calibration as kcal
        rows = self._rows(400, days=3.0, price=0.99, hit_rate=0.90)
        verdict, why, detail = kcal.is_premise_alive(rows)
        self.assertEqual(verdict, kcal.DEAD, why)
        self.assertIn("SCOPE:", why)
        self.assertIn("7-30d", why)
        self.assertIn("30-90d", why)
        self.assertTrue(detail["horizon_scoped"])

    def test_a_sample_spread_across_every_band_carries_no_caveat(self):
        """Non-vacuity guard: the caveat must be able to switch OFF.

        A test that only ever asserts its presence would pass just as happily
        against a version that pasted the sentence onto every verdict.
        """
        import kalshi_calibration as kcal
        rows = (self._rows(150, days=3.0, price=0.99, hit_rate=0.90) +
                self._rows(60, days=15.0, price=0.99, hit_rate=0.90) +
                self._rows(60, days=45.0, price=0.99, hit_rate=0.90))
        verdict, why, detail = kcal.is_premise_alive(rows)
        self.assertEqual(verdict, kcal.DEAD, why)
        self.assertNotIn("SCOPE:", why)
        self.assertFalse(detail["horizon_scoped"])
        for band in ("1-7d", "7-30d", "30-90d"):
            self.assertGreaterEqual(detail["horizon_coverage"][band],
                                    kcal.MIN_SETTLED_PER_HORIZON)

    def test_an_alive_verdict_is_scoped_too(self):
        """ALIVE authorises nothing, but it is the flag that says "build the
        estimator" — and an estimator built on 1-7d evidence would be sized
        against 90-day contracts."""
        import kalshi_calibration as kcal
        rows = self._rows(400, days=3.0, price=0.90, hit_rate=0.90)
        verdict, why, _ = kcal.is_premise_alive(rows)
        self.assertEqual(verdict, kcal.ALIVE, why)
        self.assertIn("SCOPE:", why)

    def test_the_caveat_reports_open_rows_so_a_reader_knows_evidence_is_coming(self):
        """DEAD's documented consequence is closing the sector, which ends the
        collection that fills the untested bands. The reader has to be able to
        see that the gap is closing rather than permanent."""
        import kalshi_calibration as kcal
        rows = self._rows(400, days=3.0, price=0.99, hit_rate=0.90)
        rows += [{"settled": False, "market_price": 0.97, "days_to_close": 45.0,
                  "selection_rule": kcal.SELECTION_RULE} for _ in range(37)]
        _, why, _ = kcal.is_premise_alive(rows)
        self.assertIn("30-90d: 0 settled / 37 still open", why)

    def test_a_voided_row_is_not_counted_as_evidence_still_coming(self):
        import kalshi_calibration as kcal
        rows = self._rows(400, days=3.0, price=0.99, hit_rate=0.90)
        rows += [{"settled": False, "voided": True, "market_price": 0.97,
                  "days_to_close": 45.0, "selection_rule": kcal.SELECTION_RULE}
                 for _ in range(37)]
        _, why, _ = kcal.is_premise_alive(rows)
        self.assertIn("30-90d: 0 settled / 0 still open", why)

    def test_the_scope_never_downgrades_a_real_refutation(self):
        """The caveat explains a DEAD; it must never convert one into
        CANNOT_TELL. Softening a refusal because the sample is uneven is how a
        gate stops being a gate."""
        import kalshi_calibration as kcal
        rows = self._rows(400, days=3.0, price=0.99, hit_rate=0.50)
        verdict, why, _ = kcal.is_premise_alive(rows)
        self.assertEqual(verdict, kcal.DEAD, why)
        self.assertNotEqual(verdict, kcal.UNDECIDED)

    def test_both_gates_use_the_same_per_horizon_threshold(self):
        """AST: the scope helper and is_edge_proven must read one constant.

        Two gates reasoning about horizon coverage against two different numbers
        would let the premise call a band 'tested' that the edge gate calls
        thin, and the disagreement would be invisible in both reports.
        """
        import ast
        import kalshi_calibration as kcal
        tree = ast.parse(Path(kcal.__file__).read_text())
        for name in ("_horizon_scope", "is_edge_proven"):
            fn = next(n for n in ast.walk(tree)
                      if isinstance(n, ast.FunctionDef) and n.name == name)
            names = {n.id for n in ast.walk(fn) if isinstance(n, ast.Name)}
            self.assertIn("MIN_SETTLED_PER_HORIZON", names,
                          f"{name} does not read MIN_SETTLED_PER_HORIZON")


class TestRecoveryDerivesItsScheduleFromTheCrontab(unittest.TestCase):
    """wakeup_recovery must not restate, by hand, facts the crontab holds.

    2026-08-23: Jack reported a "pipeline was down" email over a weekend when
    nothing was down. `wakeup_recovery.JOBS` carried a hand-kept copy of two
    facts production already states — which days each job runs, and which log
    proves it ran — and both had drifted:

      * fe_pipeline / fi_pipeline / overnight_ml_runner declared log prefixes
        ("fe_pipeline", "fi_pipeline", "ml_runner_daily") that no scheduled job
        writes. `_run_job()` names its log after the declared prefix, so each
        was reading a file only wakeup_recovery itself had ever written: the
        real cron run was invisible, the self-written log aged out, recovery
        fired, wrote the log, and repeated forever. fe_pipeline ran EVERY day
        (12:12, 18:02, 00:14, 06:08, 12:08) against a real cron of 15:04 Mon-Fri.
        This is the identical defect fixed for main.py in 8e4f97b, which
        repaired one row of a five-row table and left three siblings standing.
      * `weekday_only` was False for three weekday-only jobs and True for
        canary_agent, which the crontab runs all weekend. Wrong in both
        directions, and structurally unable to express overnight_ml_runner's
        real `2-6` (Tue-Sat) at all.

    The repair is a derivation, not better constants. These tests pin the
    derivation, and — because a check that cannot fail is not a check — pin
    that the detector still fires on the exact values that shipped.
    """

    def _sched(self):
        import wakeup_recovery as w
        sched, source = w._crontab_schedule()
        if source == "unavailable" or not sched:
            self.skipTest("no crontab snapshot on this host")
        return w, sched

    def test_a_weekday_only_job_is_not_recovered_on_a_weekend(self):
        w, sched = self._sched()
        dow, _p, _wp, _n = w._resolve_job("fe_pipeline.py", "fe", "1-5", sched)
        self.assertEqual(sorted(dow), [0, 1, 2, 3, 4],
                         "fe_pipeline's crontab is `0 15 * * 1-5`")
        for weekend in (5, 6):
            self.assertNotIn(weekend, dow,
                             "recovery would 'restore' a job that was never due")

    def test_a_declared_prefix_no_scheduled_job_writes_is_reported(self):
        """The self-referential log loop, caught by its own name."""
        w, sched = self._sched()
        _d, _p, _wp, notes = w._resolve_job(
            "fe_pipeline.py", "fe_pipeline", "1-5", sched)
        self.assertTrue(any("log prefix" in n for n in notes),
                        "a prefix nothing schedules must be reported, not used")

    def test_a_tuesday_to_saturday_schedule_is_representable(self):
        """The old bool had no correct value for `2-6`; the literal does."""
        w, sched = self._sched()
        dow, _p, _wp, notes = w._resolve_job(
            "overnight_ml_runner.py", "ml_overnight", "2-6", sched)
        self.assertEqual(sorted(dow), [1, 2, 3, 4, 5], "Tue-Sat")
        self.assertEqual(notes, [], f"declared 2-6 should agree: {notes}")

    def test_the_declared_table_agrees_with_the_crontab_today(self):
        """Zero drift now. This test is what makes a future edit noisy."""
        w, sched = self._sched()
        drift = []
        for script, prefix, _h, declared_dow, _a in w.JOBS:
            _d, _p, _wp, notes = w._resolve_job(script, prefix,
                                                declared_dow, sched)
            drift.extend(notes)
        self.assertEqual(drift, [], "JOBS disagrees with the live crontab:\n" +
                         "\n".join(drift))

    def test_the_drift_detector_catches_the_values_it_shipped_with(self):
        """Non-vacuity. Feed the pre-fix table back in; every row must alarm.

        Without this, `test_the_declared_table_agrees_with_the_crontab_today`
        would also pass against a `_resolve_job` that returned no notes at all.
        """
        w, sched = self._sched()
        shipped = [("fe_pipeline.py", "fe_pipeline", "*"),
                   ("fi_pipeline.py", "fi_pipeline", "*"),
                   ("overnight_ml_runner.py", "ml_runner_daily", "*"),
                   ("canary_agent.py", "canary", "1-5"),
                   ("morning_briefing.py", "briefing", "*")]
        for script, prefix, declared_dow in shipped:
            _d, _p, _wp, notes = w._resolve_job(script, prefix,
                                                declared_dow, sched)
            self.assertTrue(notes, f"{script}: shipped defect not detected")

    def test_an_unparseable_dow_widens_to_every_day_rather_than_skipping(self):
        """The degraded path must fail toward the cheap error.

        Skipping a scheduled job loses an agent; running an unscheduled one
        wastes a run. Those costs are not symmetric, so an unreadable schedule
        resolves to "assume it runs" — and says so in the log.
        """
        import wakeup_recovery as w
        self.assertIsNone(w._expand_dow("bogus"))
        self.assertIsNone(w._expand_dow(""))
        dow, _p, _wp, notes = w._resolve_job(
            "never_scheduled_xyz.py", "xyz", "bogus", {})
        self.assertEqual(sorted(dow), [0, 1, 2, 3, 4, 5, 6])
        self.assertTrue(any("absent from the crontab" in n for n in notes))

    def test_cron_sunday_is_both_zero_and_seven(self):
        import wakeup_recovery as w
        self.assertEqual(w._expand_dow("0"), {6})
        self.assertEqual(w._expand_dow("7"), {6})
        self.assertEqual(sorted(w._expand_dow("0,6")), [5, 6])   # Sat + Sun
        self.assertEqual(sorted(w._expand_dow("MON-FRI")), [0, 1, 2, 3, 4])
        self.assertEqual(sorted(w._expand_dow("1-5/2")), [0, 2, 4])

    def test_a_dom_restricted_line_does_not_narrow_the_weekday(self):
        """Cron ORs day-of-month with day-of-week; we cannot narrow from DOW."""
        import wakeup_recovery as w
        sched, _src = w._crontab_schedule()
        entry = sched.get("pregenerate_lessons.py")   # `0 2 13-21 6 *`
        if not entry:
            self.skipTest("that crontab line is not present on this host")
        self.assertEqual(sorted(entry["dow"]), [0, 1, 2, 3, 4, 5, 6])

    def test_freshness_counts_the_real_cron_log_not_only_recoverys_own(self):
        """The core repair: any log the job may write is evidence it ran."""
        import wakeup_recovery as w
        with tempfile.TemporaryDirectory() as td:
            logs = Path(td)
            today = datetime.now().strftime("%Y%m%d")
            (logs / f"fe_{today}.log").write_text("real cron run")
            with patch.object(w, "LOGS_DIR", logs):
                self.assertIsNone(w._log_age_hours("fe_pipeline"),
                                  "recovery's private prefix has no log")
                age = w._freshest_log_age({"fe_pipeline", "fe"})
                self.assertIsNotNone(age, "the real cron log must count")
                self.assertLess(age, 1.0)

    def test_no_code_path_decides_the_day_from_a_hardcoded_weekday(self):
        """AST, not grep: this file's own postmortem comments say `weekday`."""
        import wakeup_recovery as w
        tree = ast.parse(Path(w.__file__).read_text())
        fns = {n.name for n in ast.walk(tree)
               if isinstance(n, ast.FunctionDef)}
        self.assertNotIn("_is_weekday", fns,
                         "_is_weekday cannot express 2-6 and must stay deleted")
        for cmp_node in [n for n in ast.walk(tree) if isinstance(n, ast.Compare)]:
            left = cmp_node.left
            if (isinstance(left, ast.Call)
                    and isinstance(left.func, ast.Attribute)
                    and left.func.attr == "weekday"):
                self.fail("a hardcoded `.weekday() < N` decides the schedule "
                          "again; derive it from the crontab instead")

    def test_the_drift_report_is_rewritten_even_when_clean(self):
        """A stale finding left on disk reads as a current one."""
        import wakeup_recovery as w
        src = Path(w.__file__).read_text()
        body = src.split("def run_recovery", 1)[1]
        call = body.split("_record_drift(", 1)[0].rsplit("\n", 1)[-1]
        self.assertNotIn("if drift", call,
                         "_record_drift must run on every pass, not only on "
                         "failure, or the last bad report outlives the bug")


class TestBufferedIsNotDelivered(unittest.TestCase):
    """Enqueueing is not delivery, and a state file must not say it is.

    2026-08-23: Jack said he wasn't sure he'd received the Kalshi email. He
    hadn't — it was entry 11 of 21 in data/email_buffer.json, correctly
    classified non-urgent and waiting for the 22:00 UTC digest. Nothing was
    broken. But `email_verdict` stamps data/kalshi_verdict_notified.json at
    11:45, the moment `buffer_email` returns True, ten hours before the digest
    carries it — and its log line said "sent".

    So a single failed digest would have produced: no email, a state file
    asserting Jack had been told, and silence for VERDICT_HEARTBEAT_DAYS. The
    firm's oldest failure shape — an absence of output read as an absence of a
    problem — with a receipt on it.

    `email_buffer.delivery_state` answers from the two records that know: the
    buffer (still queued = pending) and .digest_last_sent, whose `sent_at` is
    written only after SMTP returns.
    """

    def _env(self, td, buffer_rows=None, stamp=None):
        import email_buffer as eb
        data = Path(td) / "data"
        data.mkdir(parents=True, exist_ok=True)
        (data / "email_buffer.json").write_text(json.dumps(buffer_rows or []))
        if stamp is not None:
            (data / ".digest_last_sent").write_text(json.dumps(stamp))
        return patch.multiple(eb,
                              BUFFER_PATH=str(data / "email_buffer.json"),
                              DIGEST_STAMP_PATH=str(data / ".digest_last_sent"))

    def test_a_digest_sent_before_the_enqueue_is_not_delivery(self):
        """The bug, stated directly: an older receipt proves nothing."""
        import email_buffer as eb
        queued = datetime.now()
        stamp = {"date": "x", "sent_at": (queued - timedelta(hours=3)).isoformat(),
                 "reports": 9}
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, [], stamp):
                state, why = eb.delivery_state(queued.isoformat(), "V")
        self.assertEqual(state, "lost", why)

    def test_a_digest_sent_after_the_enqueue_is_delivery(self):
        import email_buffer as eb
        queued = datetime.now() - timedelta(hours=10)
        stamp = {"date": "x", "sent_at": datetime.now().isoformat(), "reports": 21}
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, [], stamp):
                state, why = eb.delivery_state(queued.isoformat(), "V")
        self.assertEqual(state, "delivered", why)

    def test_a_message_still_in_the_buffer_is_pending_not_lost(self):
        """Today's normal case. Calling it lost would double-send every day."""
        import email_buffer as eb
        queued = datetime.now()
        stamp = {"date": "x", "sent_at": (queued - timedelta(hours=3)).isoformat(),
                 "reports": 9}
        rows = [{"subject": "Kalshi verdict: premise DEAD",
                 "buffered_at": queued.isoformat()}]
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, rows, stamp):
                state, why = eb.delivery_state(queued.isoformat(),
                                               "Kalshi verdict: premise DEAD")
        self.assertEqual(state, "pending", why)

    def test_no_digest_receipt_at_all_is_unknown_not_lost(self):
        """Absence of evidence is not evidence of loss.

        Calling this 'lost' made every caller re-send on every run of any host
        that has never flushed a digest — the Mac has no .digest_last_sent at
        all — and it broke the pre-existing heartbeat test, correctly. It also
        cannot mask a real loss: flush_digest stamps BEFORE clearing the
        buffer, so gone-from-the-buffer with no stamp anywhere is a failed
        stamp write, not an undelivered email.
        """
        import email_buffer as eb
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, [], None):
                state, why = eb.delivery_state(datetime.now().isoformat(), "V")
        self.assertEqual(state, "unknown", why)

    def test_only_a_receipt_older_than_the_enqueue_means_lost(self):
        """'lost' requires positive evidence: a digest ran and skipped it."""
        import email_buffer as eb
        queued = datetime.now()
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, [], {"date": "x", "reports": 3,
                                    "sent_at": (queued - timedelta(minutes=1)).isoformat()}):
                self.assertEqual(eb.delivery_state(queued.isoformat(), "V")[0],
                                 "lost")
            with self._env(td, [], {"date": "x", "reports": 3,
                                    "sent_at": (queued + timedelta(minutes=1)).isoformat()}):
                self.assertEqual(eb.delivery_state(queued.isoformat(), "V")[0],
                                 "delivered")

    def test_no_recorded_enqueue_time_is_unknown_not_lost(self):
        """Upgrade safety: old state files must not mail Jack a backlog."""
        import email_buffer as eb
        self.assertEqual(eb.delivery_state(None)[0], "unknown")
        self.assertEqual(eb.delivery_state("")[0], "unknown")
        self.assertEqual(eb.delivery_state("not-a-date")[0], "unknown")

    def test_an_aware_timestamp_does_not_crash_against_a_naive_receipt(self):
        """The verdict writes UTC-aware; the buffer writes naive local."""
        import email_buffer as eb
        stamp = {"date": "x", "sent_at": datetime.now().isoformat(), "reports": 1}
        aware = (datetime.now(timezone.utc) - timedelta(hours=10)).isoformat()
        with tempfile.TemporaryDirectory() as td:
            with self._env(td, [], stamp):
                state, why = eb.delivery_state(aware, "V")
        self.assertIn(state, ("delivered", "lost"), why)   # must not raise

    def test_the_verdict_state_records_what_it_enqueued(self):
        """Without subject + buffered_at, delivery_state cannot be asked."""
        import kalshi_calibration as kcal
        src = Path(kcal.__file__).read_text()
        block = src.split("def email_verdict", 1)[1].split("\n    curve =", 1)[0]
        for field in ('"subject"', '"buffered_at"'):
            self.assertIn(field, block,
                          f"email_verdict must persist {field} for the "
                          f"delivery check to have anything to check")

    def test_a_lost_verdict_is_requeued_rather_than_deduped(self):
        """The payoff: an undelivered verdict must not dedupe itself away."""
        import kalshi_calibration as kcal
        src = Path(kcal.__file__).read_text()
        block = src.split("def email_verdict", 1)[1].split("\n    curve =", 1)[0]
        self.assertIn("delivery_state", block,
                      "the dedupe branch must consult the delivery receipt")
        self.assertIn('"lost"', block,
                      "a lost verdict must fall through to a re-queue")

    def test_the_return_string_does_not_claim_it_was_sent(self):
        """buffer_email enqueues. A caller saying 'sent' is how a log lies."""
        import kalshi_calibration as kcal
        src = Path(kcal.__file__).read_text()
        block = src.split("def email_verdict", 1)[1].split("\ndef ", 1)[0]
        self.assertNotIn('return True, f"sent (', block,
                         "say queued, not sent — nothing here witnessed a send")

    def test_delivery_state_is_reachable_from_the_module_that_owns_the_receipt(self):
        """It lives with the buffer, so any caller can ask without guessing."""
        import email_buffer as eb
        self.assertTrue(callable(getattr(eb, "delivery_state", None)))


class TestASubjectIsNotAnIdentity(unittest.TestCase):
    """The digest deduped on a display string, and one of them was a COUNT.

    `coherence_laws.notify_violations` already dedupes: it buffers only when
    the set of violations CHANGES, so every mail it hands to the digest is by
    construction news. Its subject is "Coherence: N law(s) violated on <host>".
    A stop-loss blind to 13 broker positions, the VM running code that is not
    the repo's, and 15 Kalshi ladders quoting numbers no probabilities can
    produce all render as "1 law(s)".

    The digest then deduped on that string and kept the newest. Two dedupe
    layers, the second strictly coarser than the first, the coarse one deleting
    what the fine one had certified as news — and logging it as "Removed N
    duplicate report(s)".

    Measured on the Mac's buffer, 2026-08-27, before the fix: 133 reports, 8
    colliding subjects, 59 drops with differing bodies, and four DISTINCT
    coherence alarms queued for destruction — `deployed_set_matches_repo`,
    `shipped_config_matches_repo`, `nested_probabilities_are_monotone` (32
    copies across two subjects), and the {deployed, nested} pair (26 copies).
    The survivors would have been the config-drift ones. The VM's four-day log
    window shows no distinct alarm destroyed there, so this is a defect caught
    queued rather than an escape ([[report-the-outcome-not-the-scare]]).

    And the receipt agreed it was fine: `delivery_state` matches the manifest
    on subject, and the destroyed message's subject is character-for-character
    the survivor's ([[truncate-before-lock]]).
    """

    def setUp(self):
        import email_buffer as eb
        self.eb = eb
        self.tmp = tempfile.mkdtemp()
        self._saved = (eb.BUFFER_PATH, eb.DIGEST_STAMP_PATH)
        eb.BUFFER_PATH = os.path.join(self.tmp, "email_buffer.json")
        eb.DIGEST_STAMP_PATH = os.path.join(self.tmp, ".digest_last_sent")

    def tearDown(self):
        self.eb.BUFFER_PATH, self.eb.DIGEST_STAMP_PATH = self._saved
        shutil.rmtree(self.tmp, ignore_errors=True)

    def _row(self, subject, body, key="", minutes_ago=0):
        return {"subject": subject, "html_body": body, "sender_name": "T",
                "key_metrics": {}, "dedup_key": key,
                "buffered_at": (datetime.now()
                                - timedelta(minutes=minutes_ago)).isoformat()}

    def _flush(self, rows):
        """Run a real flush with SMTP stubbed; return (sent_html, stamp)."""
        with open(self.eb.BUFFER_PATH, "w") as f:
            json.dump(rows, f)
        sent = {}

        class _Stub:
            def __enter__(_s): return _s
            def __exit__(_s, *a): return False
            def login(_s, *a): pass
            def send_message(_s, msg): sent["msg"] = msg

        with patch.object(self.eb.smtplib, "SMTP_SSL", lambda *a, **k: _Stub()):
            ok = self.eb.flush_digest(force=True)
        self.assertTrue(ok, "the stubbed send must succeed")
        html = ""
        msg = sent.get("msg")
        if msg is not None:
            for part in msg.walk():
                if part.get_content_type() == "text/html":
                    html += part.get_payload(decode=True).decode("utf-8", "replace")
        with open(self.eb.DIGEST_STAMP_PATH) as f:
            return html, json.load(f)

    # ── the loss itself ───────────────────────────────────────────────────

    def test_two_different_alarms_under_one_subject_both_survive(self):
        """The bug, in the shape it actually had."""
        subj = "Coherence: 1 law(s) violated on apex-capital-495523"
        html, _ = self._flush([
            self._row(subj, "positions_conserve: 13 broker positions unledgered",
                      key="coherence:vm:positions_conserve", minutes_ago=120),
            self._row(subj, "nested_probabilities_are_monotone: 15 ladders",
                      key="coherence:vm:nested_probabilities_are_monotone"),
        ])
        self.assertIn("positions_conserve", html,
                      "the stop-loss alarm was deleted as a duplicate of an "
                      "unrelated Kalshi alarm")
        self.assertIn("nested_probabilities_are_monotone", html)

    def test_reruns_of_the_same_alarm_still_collapse_to_the_newest(self):
        """The behaviour the dedupe exists for, and it must not regress: the
        detail carries live counts, so the same law re-buffers all day."""
        subj = "Coherence: 1 law(s) violated on apex-capital-495523"
        key = "coherence:vm:nested_probabilities_are_monotone"
        html, stamp = self._flush([
            self._row(subj, "nested: 15 of 2056 ladders", key=key, minutes_ago=300),
            self._row(subj, "nested: 16 of 2168 ladders", key=key, minutes_ago=60),
            self._row(subj, "nested: 17 of 2201 ladders", key=key),
        ])
        self.assertEqual(1, stamp["reports"])
        self.assertIn("17 of 2201", html, "the newest run must be the one kept")
        self.assertNotIn("15 of 2056", html)

    def test_a_producer_that_declares_nothing_keeps_todays_behaviour(self):
        """Back-compat is load-bearing: ~40 producers pass no key, and for a
        subject that names its report ("[CRO REPORT] ... Risk:MODERATE") six
        regenerations a day SHOULD collapse to the freshest."""
        html, stamp = self._flush([
            self._row("[CRO REPORT] Risk:MODERATE", "grade B", minutes_ago=200),
            self._row("[CRO REPORT] Risk:MODERATE", "grade A"),
        ])
        self.assertEqual(1, stamp["reports"])
        self.assertIn("grade A", html)

    def test_two_subjects_are_still_two_reports(self):
        html, stamp = self._flush([self._row("A", "one"), self._row("B", "two")])
        self.assertEqual(2, stamp["reports"])

    def test_the_key_survives_the_trip_through_the_buffer_file(self):
        """END TO END, through `buffer_email` rather than a hand-built row.

        A mutation run deleted the key from what `buffer_email` persists and
        every test above still passed, because they all wrote `dedup_key`
        straight into the JSON. The producer declaring a key and the flush
        reading one are two halves, and a fixture that builds the row itself
        only ever tests the second ([[both-sides-of-a-comparison]]).
        """
        subj = "Coherence: 1 law(s) violated on h"
        with open(self.eb.BUFFER_PATH, "w") as f:
            json.dump([], f)
        self.assertTrue(self.eb.buffer_email(
            subject=subj, html_body="positions_conserve: 13 unledgered",
            sender_name="Coherence Layer", dedup_key="coherence:h:positions_conserve"))
        self.assertTrue(self.eb.buffer_email(
            subject=subj, html_body="nested_probabilities: 15 ladders",
            sender_name="Coherence Layer",
            dedup_key="coherence:h:nested_probabilities_are_monotone"))
        with open(self.eb.BUFFER_PATH) as f:
            rows = json.load(f)
        self.assertEqual(2, len({r.get("dedup_key") for r in rows}),
                         "buffer_email must persist the key it was handed, or "
                         "the flush has nothing to read")
        html, stamp = self._flush(rows)
        self.assertEqual(2, stamp["reports"])
        self.assertIn("positions_conserve", html)
        self.assertIn("nested_probabilities", html)

    # ── the general guard: the NEXT coarse subject, not this one ──────────

    def test_a_collapse_that_destroys_different_content_is_recorded(self):
        """The half that survives me — as a CENSUS, not an alarm.

        A drop whose body matches the survivor's is certainly a re-run. A drop
        whose body DIFFERS is either the same report with fresher numbers or
        two unrelated reports sharing a subject, and no rule in the transport
        can tell those apart — "[CRO REPORT] ... Risk:MODERATE" carries its
        state in the subject, "Coherence: 1 law(s)" carries a count. Same
        evidence, opposite meaning.
        """
        with self.assertLogs("email_buffer", level="INFO") as log:
            self._flush([self._row("Coherence: 1 law(s) violated", "law X"),
                         self._row("Coherence: 1 law(s) violated", "law Y")])
        blob = "\n".join(log.output)
        self.assertIn("DIFFERENT content", blob)
        self.assertIn("Coherence: 1 law(s) violated", blob,
                      "the census must name the producer's subject")

    def test_the_census_is_not_raised_to_a_nightly_alarm(self):
        """Six producers whose behaviour is correct, named at WARNING every
        night, is the noise this module exists to prevent — and it would bury
        the one line that matters ([[severity-below-the-escalation-floor]] in
        reverse: the floor is there to keep real findings visible)."""
        with patch.object(self.eb.logger, "warning") as warn:
            self._flush([self._row("[CRO REPORT] Risk:LOW", "grade B"),
                         self._row("[CRO REPORT] Risk:LOW", "grade A")])
        self.assertEqual([], [c for c in warn.call_args_list
                              if "DIFFERENT" in str(c)])

    def test_identical_reruns_are_not_counted_as_destroyed_content(self):
        """Nothing was lost, so nothing may be recorded as unproven."""
        _html, stamp = self._flush([
            self._row("[CRO REPORT] Risk:LOW", "same body"),
            self._row("[CRO REPORT] Risk:LOW", "same body")])
        self.assertEqual([], stamp["lost_subjects"])

    def test_a_declared_key_is_not_counted_as_undeclared(self):
        """A producer that DID declare its identity and still collapsed two
        different bodies is doing the right thing — that is the re-run case
        with fresh numbers, which is exactly what a key is for. Counting it
        would make declaring a key look no better than not declaring one."""
        _html, stamp = self._flush([self._row("S", "count 15", key="k"),
                                    self._row("S", "count 16", key="k")])
        self.assertEqual([], stamp["lost_subjects"])

    # ── the receipt must not certify what it deleted ──────────────────────

    def test_the_receipt_records_what_the_collapse_destroyed(self):
        _html, stamp = self._flush([
            self._row("Coherence: 1 law(s) violated", "law X"),
            self._row("Coherence: 1 law(s) violated", "law Y")])
        self.assertIn("Coherence: 1 law(s) violated", stamp["subjects"])
        self.assertIn("Coherence: 1 law(s) violated", stamp["lost_subjects"],
                      "the receipt must record that a report under this "
                      "subject did NOT go")

    def test_delivery_state_refuses_to_call_a_collided_subject_delivered(self):
        """The manifest test was real and its answer was still wrong: the
        destroyed message's subject is the survivor's, so membership proved
        nothing about WHICH copy went."""
        subj = "Coherence: 1 law(s) violated"
        queued = datetime.now() - timedelta(hours=2)
        self._flush([self._row(subj, "law X", minutes_ago=200),
                     self._row(subj, "law Y", minutes_ago=190)])
        state, why = self.eb.delivery_state(queued.isoformat(), subj)
        self.assertEqual("unknown", state, why)
        self.assertIn("dedup_key", why, "the answer must name the remedy")

    def test_an_uncollided_subject_is_still_delivered(self):
        """The honest third verdict must not swallow the normal answer, or
        every caller re-sends every day ([[verdict-with-no-consequence]])."""
        queued = datetime.now() - timedelta(hours=2)
        self._flush([self._row("Kalshi verdict: premise DEAD", "body",
                               minutes_ago=200)])
        state, why = self.eb.delivery_state(queued.isoformat(),
                                            "Kalshi verdict: premise DEAD")
        self.assertEqual("delivered", state, why)

    def test_an_old_receipt_without_the_field_does_not_crash(self):
        """Upgrade safety: stamps written before today have no lost_subjects."""
        with open(self.eb.DIGEST_STAMP_PATH, "w") as f:
            json.dump({"date": "x", "sent_at": datetime.now().isoformat(),
                       "reports": 3, "subjects": ["V"]}, f)
        state, _why = self.eb.delivery_state(
            (datetime.now() - timedelta(hours=2)).isoformat(), "V")
        self.assertEqual("delivered", state)

    # ── the producer that proved it ───────────────────────────────────────

    def test_the_coherence_layer_declares_its_laws_as_its_identity(self):
        """AST, not grep: the comment I wrote next to this call names
        `dedup_key` and every law in the story, so a text search goes green on
        the postmortem while the call passes nothing
        ([[unregistered-test-is-absent]])."""
        import coherence_laws as cl
        tree = ast.parse(Path(cl.__file__).read_text())
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "notify_violations")
        call = next(c for c in ast.walk(fn)
                    if isinstance(c, ast.Call)
                    and getattr(c.func, "id", "") == "buffer_email")
        kw = {k.arg for k in call.keywords}
        self.assertIn("dedup_key", kw,
                      "notify_violations must tell the digest what makes two "
                      "of its emails the same, because its subject is a count")

    def test_the_key_separates_law_sets_and_not_runs(self):
        """The identity is the law NAMES. Their detail is not: it carries live
        counts that move every run, which is why the signature check upstream
        buffers a fresh mail each time the same law reports a new number."""
        import coherence_laws as cl
        seen = {}

        def _cap(**kw):
            seen.setdefault(kw.get("dedup_key"), []).append(kw["subject"])
            return True

        def _res(name, detail):
            r = MagicMock()
            r.name, r.detail, r.verdict = name, detail, cl.VIOLATED
            r.sources = ("a", "b")
            return r

        with tempfile.TemporaryDirectory() as td:
            with patch.object(cl, "NOTIFY_STATE", Path(td) / "n.json"), \
                 patch.dict("sys.modules", {"email_buffer": MagicMock(
                     buffer_email=_cap)}):
                cl.notify_violations([_res("positions_conserve", "13 unledgered")])
                cl.notify_violations([_res("nested_probabilities_are_monotone",
                                           "15 of 2056")])
                cl.notify_violations([_res("nested_probabilities_are_monotone",
                                           "16 of 2168")])
        self.assertEqual(3, sum(len(v) for v in seen.values()),
                         "the upstream signature check must still buffer each "
                         "change in detail")
        self.assertEqual(2, len(seen),
                         "two laws must be two keys; a detail change must not "
                         "be a third")
        self.assertEqual(1, len({s for v in seen.values() for s in v}),
                         "fixture assumes all three share ONE subject — that "
                         "is the whole defect")


class TestAHostLabelIsNotANetworkCondition(unittest.TestCase):
    """A hostname is a network condition; an identity is written down.

    `coherence_laws.notify_violations` derived its alarm label from
    `socket.gethostname()` — 1500 lines below `_this_host()`'s docstring
    forbidding exactly that, and a month after `order_ledger._host_tag()` fixed
    the same thing for order stamps. This Mac has `HostName: not set`, so
    `kern.hostname` is whatever the network last called it; the live digest
    buffer carried ONE machine's alarms under "Mac" (4) and "MacBook-Air-173"
    (39), interleaved rather than one superseding the other.

    That was cosmetic until the label became the leading component of the
    dedup_key. A key that moves means identical alarms never collapse.
    """

    def test_the_alarm_label_is_the_persisted_identity(self):
        import coherence_laws as cl
        with patch.object(cl, "_this_host", lambda: "apexcapitalc"):
            self.assertEqual("apexcapitalc", cl._host_for_alarm())

    def test_the_label_does_not_move_when_the_hostname_does(self):
        """The property the dedup_key depends on."""
        import coherence_laws as cl, socket
        with patch.object(cl, "_this_host", lambda: "mac"):
            with patch.object(socket, "gethostname", lambda: "Mac.lan"):
                a = cl._host_for_alarm()
            with patch.object(socket, "gethostname",
                              lambda: "MacBook-Air-173.local"):
                b = cl._host_for_alarm()
        self.assertEqual(a, b,
                         "the machine did not change, only the network did — "
                         "the label must not move")

    def test_a_degraded_label_is_still_machine_distinct(self):
        """"unknown" on two hosts is ONE key, and one host's alarm is deleted.

        So the degraded branch must never return a constant that another machine
        could also return. It fails toward too many keys, not toward a shared one.
        """
        import coherence_laws as cl, socket
        with patch.object(cl, "_this_host", lambda: "unknown"):
            with patch.object(socket, "gethostname", lambda: "hostA.local"):
                a = cl._host_for_alarm()
            with patch.object(socket, "gethostname", lambda: "hostB.local"):
                b = cl._host_for_alarm()
        self.assertNotEqual(a, b,
                            "two hosts that both fail to resolve their identity "
                            "must not share one alarm key")
        self.assertNotEqual("unknown", a)
        self.assertNotEqual("unknown", b)

    def test_an_empty_identity_is_a_non_answer_too(self):
        """"" is as shared between two hosts as "unknown" is.

        `_this_host()` cannot return it today, but the guard against it is the
        kind of defensive branch that gets "simplified" away later, and the
        failure it prevents is silent: every host files under one empty key and
        the digest deletes all but one machine's alarm.
        """
        import coherence_laws as cl, socket
        with patch.object(cl, "_this_host", lambda: ""):
            with patch.object(socket, "gethostname", lambda: "hostA.local"):
                a = cl._host_for_alarm()
            with patch.object(socket, "gethostname", lambda: "hostB.local"):
                b = cl._host_for_alarm()
        self.assertTrue(a and b, "an empty label is not a label")
        self.assertNotEqual(a, b)

    def test_a_degraded_label_says_it_is_degraded(self):
        import coherence_laws as cl, socket
        with patch.object(cl, "_this_host", lambda: "unknown"):
            with patch.object(socket, "gethostname", lambda: "hostA.local"):
                self.assertIn("unknown", cl._host_for_alarm(),
                              "a guessed label must read as guessed")

    def test_even_a_dead_socket_yields_a_label(self):
        import coherence_laws as cl, socket
        def _boom():
            raise OSError("no resolver")
        with patch.object(cl, "_this_host", lambda: "unknown"):
            with patch.object(socket, "gethostname", _boom):
                self.assertTrue(cl._host_for_alarm())

    def test_notify_violations_does_not_read_the_hostname(self):
        """AST, not grep — this file and that module both discuss gethostname."""
        import coherence_laws as cl
        tree = ast.parse(Path(cl.__file__).read_text())
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "notify_violations")
        names = {getattr(c.func, "attr", getattr(c.func, "id", ""))
                 for c in ast.walk(fn) if isinstance(c, ast.Call)}
        self.assertNotIn("gethostname", names,
                         "the alarm label must come from the persisted identity, "
                         "not from whatever the network calls this machine")
        self.assertIn("_host_for_alarm", names)

    def test_the_two_hosts_of_this_firm_get_two_keys(self):
        """The end-to-end property: same law-set, different machine, distinct key."""
        import coherence_laws as cl
        keys = []
        for ident in ("mac", "apexcapitalc"):
            with patch.object(cl, "_this_host", lambda i=ident: i):
                keys.append("coherence:%s:%s" % (cl._host_for_alarm(),
                                                 "positions_conserve"))
        self.assertEqual(2, len(set(keys)))

    def test_the_signoff_record_uses_the_same_identity_as_the_order_stamp(self):
        """One machine, one name, across the ledger that stamps orders and the
        ledger that records who flipped the autonomy gate."""
        import signoff_ledger as sl
        from order_ledger import _host_tag
        self.assertEqual(_host_tag(), sl._host())

    def test_signoff_host_delegates_rather_than_deriving(self):
        import signoff_ledger as sl
        tree = ast.parse(Path(sl.__file__).read_text())
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "_host")
        imported = {a.name for n in ast.walk(fn)
                    if isinstance(n, ast.ImportFrom) for a in n.names}
        self.assertIn("_host_tag", imported,
                      "_host must delegate to the one place that knows the "
                      "persisted identity, not re-derive it")

    def test_the_deploy_budget_never_filtered_on_host(self):
        """Pins the claim in _host's docstring: a drifting name could not have
        bought an extra deploy. If someone adds a host filter here, that stops
        being true and the docstring becomes a lie."""
        import signoff_ledger as sl
        tree = ast.parse(Path(sl.__file__).read_text())
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef)
                  and n.name == "_deployed_today_records")
        src = ast.dump(fn)
        self.assertNotIn("deploy_host", src,
                         "the daily deploy budget must stay host-blind — "
                         "filtering it on a host name makes the cap evadable "
                         "by a network rename")


class TestABookedExitIsNotAnExecutedOne(unittest.TestCase):
    """`sell_log` records the DECISION to sell; only the broker records the sale.

    main.py appends the row — carrying `pnl_pct`, which cit_director turns into
    the firm's win rate — as soon as `submit_sell` returns a dict, and it returns
    one on ACCEPTED. Alpaca queues after-hours orders to the next open, so the
    trade is booked hours before it happens, and if the order dies it is booked
    for a trade that never happens at all.
    """

    # Widths the broker actually emits, measured over 500 live orders:
    # {3: 1, 4: 7, 5: 55, 6: 436, 9: 1}. Python 3.9 parses only 3 and 6.
    FRACTION_WIDTHS = ["182", "1823", "18234", "182340", "182340123", ""]

    def _law(self, **kw):
        import coherence_laws as cl
        return cl.law_recorded_exits_are_executed(**kw)

    def _row(self, **kw):
        base = {"date": "2026-08-20", "ticker": "ZZT", "reason": "take_profit (9.0%)",
                "pnl_pct": 9.0, "order_id": "oid-1"}
        base.update(kw)
        return base

    def _order(self, **kw):
        base = {"id": "oid-1", "symbol": "ZZT", "side": "sell", "qty": "10",
                "filled_qty": "10", "status": "filled",
                "created_at": "2026-08-20T14:00:00.123456Z"}
        base.update(kw)
        return base

    # --- the failure the law exists for -----------------------------------
    def test_a_dead_order_makes_the_booked_pnl_fiction(self):
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(filled_qty="0", status="canceled")])
        self.assertEqual(r.verdict, "VIOLATED")
        self.assertEqual(r.n_examined, 1, "a VIOLATED needs its denominator")

    def test_an_executed_exit_holds(self):
        r = self._law(sell_log=[self._row()], orders=[self._order()])
        self.assertEqual(r.verdict, "HOLDS")
        self.assertEqual(r.n_examined, 1)

    def test_a_queued_exit_inside_the_grace_is_reported_not_alarmed(self):
        """The broker's release schedule is not a defect. Alarming nightly on it
        would be correct and useless, and would bury the permanent case."""
        now = datetime(2026, 8, 20, 20, 0, tzinfo=timezone.utc)
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(filled_qty="0", status="accepted")],
                      now=now)
        self.assertEqual(r.verdict, "HOLDS")
        self.assertTrue(r.evidence, "a pending exit must still be surfaced")
        self.assertEqual(r.evidence[0]["ticker"], "ZZT")

    def test_a_queue_longer_than_any_ever_observed_is_a_violation(self):
        import coherence_laws as cl
        now = (datetime(2026, 8, 20, 14, 0, tzinfo=timezone.utc)
               + timedelta(hours=cl._EXIT_PENDING_GRACE_H + 1))
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(filled_qty="0", status="accepted")],
                      now=now)
        self.assertEqual(r.verdict, "VIOLATED")

    # --- the traps ---------------------------------------------------------
    def test_every_fraction_width_the_broker_emits_parses(self):
        """The regression that would have shipped: py3.9 `fromisoformat` takes a
        3- or 6-digit fraction and nothing else, while the VM's 3.11 takes any.
        An unreadable clock drops the order from the candidate set, and the
        recorded exit then reads as never executed."""
        for frac in self.FRACTION_WIDTHS:
            stamp = "2026-08-20T14:00:00%sZ" % (("." + frac) if frac else "")
            with self.subTest(width=len(frac)):
                r = self._law(sell_log=[self._row()],
                              orders=[self._order(created_at=stamp)])
                self.assertEqual(
                    r.verdict, "HOLDS",
                    "a %d-digit fractional second must not turn a filled exit "
                    "into a violation (got: %s)" % (len(frac), r.detail))

    def test_an_unreadable_clock_defers_instead_of_convicting(self):
        """If the format changes again, the honest answer is 'I cannot tell',
        not a list of exits declared fictional."""
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(created_at="not-a-timestamp")])
        self.assertEqual(r.verdict, "CANNOT_TELL")
        self.assertIn("parse", r.detail)

    def test_a_row_predating_the_order_window_is_not_convicted(self):
        """The fetch is limit=500 desc and this account has more orders than
        that, so old rows have no order in the window. Absence of evidence is
        not evidence of absence."""
        r = self._law(sell_log=[self._row(date="2026-01-05", order_id="")],
                      orders=[self._order(created_at="2026-08-20T14:00:00.123456Z")])
        self.assertEqual(r.verdict, "HOLDS")
        self.assertIn("predate", r.detail)

    def test_a_row_inside_the_window_with_no_order_is_convicted(self):
        """The other side of the same boundary — inside the window, a missing
        exit order really does mean the sale never happened."""
        r = self._law(sell_log=[self._row(ticker="ZZQ", order_id="")],
                      orders=[self._order(created_at="2026-08-01T14:00:00.123456Z")])
        self.assertEqual(r.verdict, "VIOLATED")

    def test_the_same_day_as_the_window_edge_is_still_judged(self):
        """Rows are dated midnight; comparing against the window's oldest
        timestamp rather than its date would excuse every exit decided on the
        boundary day."""
        r = self._law(sell_log=[self._row(ticker="ZZQ", order_id="")],
                      orders=[self._order(created_at="2026-08-20T14:00:00.123456Z")])
        self.assertEqual(r.verdict, "VIOLATED")
        self.assertNotIn("predate", r.detail)

    def test_an_empty_sell_log_is_not_a_pass(self):
        r = self._law(sell_log=[], orders=[self._order()])
        self.assertEqual(r.verdict, "CANNOT_TELL")

    def test_an_unreadable_broker_is_not_a_clean_book(self):
        """Patched, not merely left as None. A reachable broker answers, and the
        law then judges a fabricated row against 500 real orders and correctly
        VIOLATES — so `orders=None` tests nothing and puts a live network call in
        the commit path. Forcing the failure is the only way to reach the branch.
        """
        import single_writer
        with patch.object(single_writer, "fetch_broker_orders",
                          side_effect=OSError("connection refused")):
            r = self._law(sell_log=[self._row()], orders=None, host="nowhere")
        self.assertEqual(r.verdict, "CANNOT_TELL")
        self.assertIn("unreachable", r.detail)

    def test_the_order_id_beats_the_heuristic(self):
        """An exact id match must win over a same-ticker order four days out,
        or the fix that made rows checkable buys nothing."""
        r = self._law(
            sell_log=[self._row(order_id="oid-real")],
            orders=[self._order(id="oid-real", filled_qty="0", status="canceled"),
                    self._order(id="oid-decoy", filled_qty="10", status="filled")])
        self.assertEqual(r.verdict, "VIOLATED")
        self.assertEqual(r.evidence[0]["match"], "order_id")

    def test_the_window_opens_at_the_oldest_order_not_the_newest(self):
        """Every one of these tests passed with the window taken from the NEWEST
        order — because they each supply one order, where oldest and newest are
        the same row. With `max`, almost every sell_log row predates the "window"
        and is excused, and the law goes permanently, invisibly silent. Two
        orders at different dates is the only shape that can tell them apart."""
        r = self._law(
            sell_log=[self._row(date="2026-06-01", ticker="ZZQ", order_id="")],
            orders=[self._order(id="old", created_at="2026-01-05T14:00:00.123456Z"),
                    self._order(id="new", created_at="2026-08-20T14:00:00.123456Z")])
        self.assertEqual(r.verdict, "VIOLATED",
                         "a row inside the fetched window must be judged, not "
                         "excused by a window measured from the wrong end")

    def test_the_grace_covers_the_longest_queue_the_broker_ever_took(self):
        """65.51h, measured on this account: an after-hours exit released after a
        long weekend. A grace under that alarms on the broker doing its job, and
        a law that cries wolf nightly is how the real case gets ignored."""
        import coherence_laws as cl
        self.assertGreaterEqual(
            cl._EXIT_PENDING_GRACE_H, 65.51,
            "the grace must exceed the longest legitimate queue observed here")
        now = datetime(2026, 8, 20, 14, 0, tzinfo=timezone.utc) + timedelta(hours=65.5)
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(filled_qty="0", status="accepted")],
                      now=now)
        self.assertEqual(r.verdict, "HOLDS")

    def test_a_partial_fill_is_an_executed_exit(self):
        """The question is whether the broker acted, not whether it finished. A
        40-of-100 fill is a real sale at a real price; convicting it would put
        routine partial fills in the Chairman's escalation queue."""
        r = self._law(sell_log=[self._row()],
                      orders=[self._order(qty="100", filled_qty="40",
                                          status="partially_filled")])
        self.assertEqual(r.verdict, "HOLDS")

    def test_the_heuristic_takes_the_best_filled_candidate(self):
        """Legacy rows carry no order_id and a ticker can have several orders in
        a 4-day span. Picking the worst convicts an exit that really happened —
        and the heuristic feeds an escalation queue, so it must bias toward
        HOLDS, never toward a false alarm."""
        r = self._law(
            sell_log=[self._row(order_id="")],
            orders=[self._order(id="a", filled_qty="0", status="canceled"),
                    self._order(id="b", filled_qty="10", status="filled")])
        self.assertEqual(r.verdict, "HOLDS")

    def test_a_buy_can_never_stand_in_for_the_exit(self):
        """Same ticker, same window, opposite direction. A re-entry is not the
        sale, and matching one would report a booked exit as executed by the
        order that re-opened the position."""
        r = self._law(sell_log=[self._row(ticker="ZZQ", order_id="")],
                      orders=[self._order(symbol="ZZQ", side="buy", id="rebuy")])
        self.assertEqual(r.verdict, "VIOLATED")

    def test_the_denominator_counts_the_rows_with_no_order_at_all(self):
        """`n of N` where N omits the very rows being convicted reads as
        "1 of 1 exits never executed" on a two-row book — an aggregate that
        cannot be checked against anything (memory `an-aggregate-is-not-a-finding`)."""
        r = self._law(
            sell_log=[self._row(), self._row(ticker="ZZQ", order_id="")],
            orders=[self._order()])
        self.assertEqual(r.verdict, "VIOLATED")
        self.assertEqual(r.n_examined, 2,
                         "both the verifiable row and the unmatched one were "
                         "examined; only rows predating the window are excluded")

    # --- the producer and the contract -------------------------------------
    def test_main_persists_the_order_id_it_already_had(self):
        """AST, not grep — this file and main.py both discuss order_id.

        The VALUE is checked, not just the key. `"order_id": sell.get("ticker")`
        satisfies a key-presence assertion, produces an id-shaped string for
        every row, and makes the law's exact-match path match nothing forever
        while reporting `match: heuristic` — a fix that reads as applied and
        is not.
        """
        import main
        tree = ast.parse(Path(main.__file__).read_text())

        # Enumerate the append SITES, then require a row literal for each. The
        # first version of this test walked every Dict, unioned their keys, and
        # asserted "order_id" was in the union — so main.py's SECOND sell_log
        # writer (the manager path, which had no order_id at all) was masked by
        # the first one, which did. A union over N things cannot tell you all N
        # have the property. Counting the sites is what makes the coverage
        # non-vacuous: a third writer added tomorrow fails here until it is
        # checked too, instead of being silently skipped.
        sites = [n for n in ast.walk(tree)
                 if isinstance(n, ast.Call)
                 and isinstance(n.func, ast.Attribute) and n.func.attr == "append"
                 and isinstance(n.func.value, ast.Subscript)
                 and isinstance(n.func.value.slice, ast.Constant)
                 and n.func.value.slice.value == "sell_log"]
        self.assertGreaterEqual(len(sites), 2,
                                "main.py has had two sell_log writers since the "
                                "manager path was added; finding fewer means "
                                "this AST match has drifted, not that a writer "
                                "was removed")

        for site in sites:
            self.assertTrue(site.args and isinstance(site.args[0], ast.Dict),
                            "a sell_log row must be a dict literal so it can be "
                            "checked here")
            row = site.args[0]
            pairs = {k.value: v for k, v in zip(row.keys, row.values)
                     if isinstance(k, ast.Constant) and isinstance(k.value, str)}
            self.assertIn("pnl_pct", pairs, "this is the row that books the P&L")
            self.assertIn("order_id", pairs,
                          "every sell_log row must carry the order id the "
                          "executor already returns, or a recorded exit and a "
                          "real one are indistinguishable")
            val = pairs["order_id"]
            # `.get("id")` (submit_sell's raw dict) or `.get("order_id")`
            # (execute_decision's result) — both read the broker's id from what
            # the executor returned. What this rejects is any OTHER field:
            # `sell.get("ticker")` satisfies key-presence, yields an id-shaped
            # string on every row, and makes the exact-match path match nothing
            # forever while still reporting itself as populated.
            self.assertTrue(
                isinstance(val, ast.Call) and isinstance(val.func, ast.Attribute)
                and val.func.attr == "get"
                and val.args and isinstance(val.args[0], ast.Constant)
                and val.args[0].value in ("id", "order_id"),
                "order_id must be read from the executor's returned id, not "
                "from some other field that merely looks populated")

    def test_the_law_is_registered_and_has_a_poison_pill(self):
        import coherence_laws as cl, internal_audit_agent as ia
        names = {fn.__name__ for fn, _ in cl.LAWS}
        self.assertIn("law_recorded_exits_are_executed", names)
        self.assertIn("recorded_exits_are_executed", ia.POISON_PILLS)

    def test_the_pill_proves_the_law_can_fail(self):
        import coherence_laws as cl, internal_audit_agent as ia
        fn = next(f for f, _ in cl.LAWS
                  if f.__name__ == "law_recorded_exits_are_executed")
        self.assertEqual(ia.POISON_PILLS["recorded_exits_are_executed"].run(fn).verdict,
                         "VIOLATED")

    def test_the_two_sources_are_independent(self):
        import coherence_laws as cl
        a, b = cl.law_recorded_exits_are_executed.sources
        self.assertNotEqual(a, b)
        self.assertIn("sell_log", a)
        self.assertIn("Alpaca", b)


class TestTheEntryLedgerCarriesTheBrokerId(unittest.TestCase):
    """The buy side of the same structural blindness — with no law behind it.

    There is deliberately NO buy-side coherence law. Measured on the VM
    2026-08-27, the entry ledger is clean: 30 of 30 verifiable buy_log rows
    have a filled broker order, 0 unfilled, 9 predating the fetched window.
    The only 4 terminal-unfilled buy orders on the account in 45 days (3
    rejected, 1 expired) were all SH, which has zero buy_log rows — they never
    entered the ledger, so there was nothing to escape. A law costs a poison
    pill, tests, nightly runtime and a new false-alarm surface; buying one for
    a failure class with zero observed instances is paying for the alarm
    before the fire.

    What IS worth paying for is the id, because it decides whether a future
    check can be exact. Without it the only tie from row to order is
    (ticker, side, ±4 days), and SH alone had 42 filled buys inside one 4-day
    window — a regime where that heuristic identifies nothing. This class is
    the ratchet that keeps the field from quietly disappearing again, since
    nothing else reads it yet and an unread field is the easiest kind to drop.
    """

    def test_both_buy_sites_persist_the_order_id_the_executor_returns(self):
        import main
        tree = ast.parse(Path(main.__file__).read_text())

        # Same enumerate-then-assert-per-site shape as the sell_log test above,
        # and for the same reason: a union over the sites' keys passes when only
        # ONE site has the field, which is precisely how main.py's second
        # sell_log writer stayed invisible.
        sites = [n for n in ast.walk(tree)
                 if isinstance(n, ast.Call)
                 and isinstance(n.func, ast.Attribute) and n.func.attr == "append"
                 and isinstance(n.func.value, ast.Subscript)
                 and isinstance(n.func.value.slice, ast.Constant)
                 and n.func.value.slice.value == "buy_log"]
        self.assertGreaterEqual(len(sites), 2,
                                "main.py has two buy_log writers — the 13F path "
                                "and the manager ADD/BUY_NEW path; finding fewer "
                                "means this AST match drifted, not that a writer "
                                "went away")

        for site in sites:
            self.assertTrue(site.args and isinstance(site.args[0], ast.Dict),
                            "a buy_log row must be a dict literal so it can be "
                            "checked here")
            row = site.args[0]
            pairs = {k.value: v for k, v in zip(row.keys, row.values)
                     if isinstance(k, ast.Constant) and isinstance(k.value, str)}
            self.assertIn("ticker", pairs, "this is an entry row")
            self.assertIn("order_id", pairs,
                          "every buy_log row must carry the broker id that "
                          "execute_decision already returns, or an entry can "
                          "only ever be tied to an order by a ±4-day ticker "
                          "guess")
            val = pairs["order_id"]
            self.assertTrue(
                isinstance(val, ast.Call) and isinstance(val.func, ast.Attribute)
                and val.func.attr == "get"
                and val.args and isinstance(val.args[0], ast.Constant)
                and val.args[0].value in ("id", "order_id"),
                "order_id must be read from the executor's returned id — "
                "`.get(\"ticker\")` satisfies key-presence, yields a populated "
                "string on every row, and matches nothing forever")

    def test_the_executor_actually_supplies_an_id_on_the_buy_path(self):
        """The field is only worth pinning if the source of it is real.

        `execute_decision` sets `result["order_id"]` on the SELL and TRIM
        branches; this proves the BUY branch does too. Without it, both writers
        above would faithfully persist `""` forever and the AST test would stay
        green — a fix that reads as applied and is not.

        BEHAVIOURAL, not structural, and the first attempt here shows why. That
        one collected every `ast.If` whose subtree contained a `submit_buy`
        call and asserted `any(...)` of them assigned `order_id`. An `elif`
        chain nests inside the previous `If`'s `orelse`, so the outermost
        `if action == "SELL"` node contains the buy branch AND the sell
        branch's own assignment — deleting the buy assignment entirely left
        the test green. That is [[a-union-cannot-prove-all-n]] again in a
        different costume: `any()` over N candidate blocks proves one of them
        has the property, and I had just written that memory. A fake trader
        answers the actual question instead of a proxy for it, and cannot be
        fooled by how the branches happen to nest.
        """
        import manager_agent

        class _FakeTrader:
            def __init__(self):
                self.calls = []

            def submit_buy(self, ticker, **kw):
                self.calls.append(ticker)
                return {"id": "zz-fake-order-1", "qty": "3"}

        trader = _FakeTrader()
        # The pod ledger is a real on-disk budget: leaving it enabled would let
        # this test either be rejected by a live budget or write a phantom trade
        # into it. Disabling it isolates the branch under test.
        with patch.object(manager_agent, "_POD_LEDGER_AVAILABLE", False):
            res = manager_agent.execute_decision(
                {"manager_action": "BUY_NEW", "ticker": "ZZFAKE",
                 "conviction": 3.0, "current_price": 10.0},
                trader, dry_run=False)

        self.assertEqual(trader.calls, ["ZZFAKE"],
                         "the buy path must still route through submit_buy")
        self.assertTrue(res.get("executed"))
        self.assertEqual(res.get("order_id"), "zz-fake-order-1",
                         "execute_decision must return the broker's id on the "
                         "BUY path — main.py's two buy_log writers read it from "
                         "exactly here, and persist '' if it is absent")


class TestIssueIdentityIsNotTheMeasurement(unittest.TestCase):
    """A detector writes what it measures into the title; identity must not move with it.

    Live tracker, 2026-08-23: 4423 rows, 2139 distinct conditions, `resolved_at`
    set on exactly zero of them. One unfixed condition
    (data/capital_efficiency_report.json being stale) had produced 29 separate
    issues, because the dedupe compared titles exactly and the title carried
    "(49h old)", "(75h old)", "(96h old)" ... — the key moved every time the
    measurement moved, so it could never repeat.
    """

    def setUp(self):
        import issue_tracker as it
        self.it = it
        self.td = tempfile.mkdtemp()
        self.tracker  = os.path.join(self.td, "issues.json")
        self.archive  = os.path.join(self.td, "archive.json")
        # REGISTRY_PATH must be redirected too. resolve_issue() and
        # resolve_by_signature() append to it, so leaving it unpatched would
        # have these tests write into the firm's live data/ directory.
        self.registry = os.path.join(self.td, "registry.json")
        self.p = patch.multiple(it, TRACKER_PATH=self.tracker, ARCHIVE_PATH=self.archive,
                                REGISTRY_PATH=self.registry)
        self.p.start()

    def tearDown(self):
        self.p.stop()
        shutil.rmtree(self.td, ignore_errors=True)

    def _log(self, title, reporter="CITPipelineMonitor", severity="HIGH"):
        return self.it.log_issue(reporter, title, "d", severity, "PIPELINE")

    def _rows(self):
        return json.load(open(self.tracker))

    # ── identity ─────────────────────────────────────────────────────────────
    def test_the_same_condition_at_two_ages_is_one_issue(self):
        a = self._log("Severely stale output: data/x.json (49h old)")
        b = self._log("Severely stale output: data/x.json (75h old)")
        self.assertEqual(a, b, "a growing age minted a second issue for one condition")
        self.assertEqual(len(self._rows()), 1)

    def test_the_normaliser_collapses_the_series_that_actually_shipped(self):
        """Poison pill: the real titles from the live tracker must fold to one.

        These are verbatim from data/issue_tracker.json — ISS-0666, ISS-1020,
        ISS-1059, ISS-1096, ISS-1105. If a future edit to _MEASUREMENT_PATTERNS
        stops collapsing them, this test fails rather than the tracker quietly
        resuming its ~190 rows/day.
        """
        shipped = [
            "Severely stale output: data/capital_efficiency_report.json (49h old)",
            "Severely stale output: data/capital_efficiency_report.json (75h old)",
            "Severely stale output: data/capital_efficiency_report.json (96h old)",
            "Severely stale output: data/capital_efficiency_report.json (99h old)",
            "Severely stale output: data/capital_efficiency_report.json (162h old)",
        ]
        sigs = {self.it.condition_signature(t) for t in shipped}
        self.assertEqual(len(sigs), 1, f"shipped series did not collapse: {sigs}")
        ids = {self._log(t) for t in shipped}
        self.assertEqual(len(ids), 1, "5 shipped re-reports became >1 issue")

    def test_two_different_source_lines_stay_two_issues(self):
        """Poison pill against over-normalising: :693 and :701 are different bugs."""
        a = self._log("print() in production code: agent_roster.py:693")
        b = self._log("print() in production code: agent_roster.py:701")
        self.assertNotEqual(a, b, "distinct source lines were merged into one issue")

    def test_two_different_files_stay_two_issues(self):
        a = self._log("Severely stale output: data/a.json (49h old)")
        b = self._log("Severely stale output: data/b.json (49h old)")
        self.assertNotEqual(a, b, "distinct files were merged into one issue")

    def test_a_different_reporter_gets_its_own_issue(self):
        a = self._log("Severely stale output: data/x.json (49h old)", reporter="CIT")
        b = self._log("Severely stale output: data/x.json (49h old)", reporter="HR Agent")
        self.assertNotEqual(a, b)

    # ── the two clocks ───────────────────────────────────────────────────────
    def test_re_observation_does_not_reset_the_staleness_clock(self):
        """The trap inside the fix.

        get_stale_issues() measures from updated_at. If re-observing a condition
        bumped it, anything seen 6x/day could never age past 48h and the
        escalation path would go silent for exactly the problems that recur most.
        Freshness-of-observation and age-of-unfixed-problem are different clocks.
        """
        self._log("Severely stale output: data/x.json (49h old)")
        rows = self._rows()
        old = (datetime.now() - timedelta(hours=200)).isoformat()
        rows[0]["created_at"] = rows[0]["updated_at"] = old
        json.dump(rows, open(self.tracker, "w"))

        self._log("Severely stale output: data/x.json (206h old)")

        self.assertEqual(self._rows()[0]["updated_at"], old,
                         "re-observation reset updated_at — the issue can never go stale")
        self.assertEqual(len(self.it.get_stale_issues(hours=48)), 1,
                         "a long-unfixed condition dropped out of get_stale_issues")

    def test_re_observation_records_that_it_happened_again(self):
        self._log("Severely stale output: data/x.json (49h old)")
        self._log("Severely stale output: data/x.json (55h old)")
        self._log("Severely stale output: data/x.json (61h old)")
        row = self._rows()[0]
        self.assertEqual(row["occurrences"], 3)
        self.assertIn("61h old", row["latest_title"],
                      "the newest measurement is not visible on the surviving row")
        self.assertIn("49h old", row["title"],
                      "the identifying title was overwritten by a later measurement")

    # ── dedupe scope ─────────────────────────────────────────────────────────
    def test_a_stale_row_still_dedupes(self):
        """94 of 94 duplicate groups in the live tracker were born this way.

        Dedupe matched only OPEN/ASSIGNED/IN_PROGRESS, so the moment a row aged
        into STALE it became invisible and the same condition was re-filed.
        """
        a = self._log("Severely stale output: data/x.json (49h old)")
        self.it.update_issue(a, "STALE")
        b = self._log("Severely stale output: data/x.json (75h old)")
        self.assertEqual(a, b, "a STALE row did not dedupe — the condition was re-filed")

    def test_an_escalated_row_still_dedupes(self):
        a = self._log("Severely stale output: data/x.json (49h old)")
        self.it.update_issue(a, "ESCALATED")
        self.assertEqual(a, self._log("Severely stale output: data/x.json (75h old)"))

    def test_a_resolved_row_does_not_dedupe(self):
        """Recurrence after a fix must be visible, not swallowed as a duplicate."""
        a = self._log("Severely stale output: data/x.json (49h old)")
        self.it.resolve_issue(a, "producer rescheduled", "me")
        b = self._log("Severely stale output: data/x.json (49h old)")
        self.assertNotEqual(a, b, "a condition that came back was hidden behind the closed row")

    # ── closing ──────────────────────────────────────────────────────────────
    def test_a_cleared_condition_closes_its_issues(self):
        for age in (49, 75, 96):
            self._log(f"Severely stale output: data/x.json ({age}h old)")
        sig = self.it.condition_signature("Severely stale output: data/x.json (0h old)")
        closed = self.it.resolve_by_signature("CITPipelineMonitor", sig, "fresh again")
        self.assertEqual(len(closed), 1)
        row = self._rows()[0]
        self.assertTrue(row["resolved_at"], "resolved_at still unset after closing")
        self.assertEqual(self.it.get_stats()["resolved_count"], 1)

    def test_closing_one_reporters_condition_leaves_another_alone(self):
        self._log("Severely stale output: data/x.json (49h old)", reporter="CIT")
        self._log("Severely stale output: data/x.json (49h old)", reporter="HR Agent")
        sig = self.it.condition_signature("Severely stale output: data/x.json (1h old)")
        self.it.resolve_by_signature("CIT", sig, "fresh")
        self.assertEqual(self.it.get_stats()["unresolved_count"], 1)

    def test_lowercase_hygiene_statuses_count_as_finished(self):
        """tracker_hygiene.py writes 'resolved' / 'closed_stale_unverified'.

        An `== "RESOLVED"` comparison read every hygiene-closed row as still
        unresolved — the closer and the counter disagreed about the same row.
        """
        a = self._log("Severely stale output: data/x.json (49h old)")
        rows = self._rows()
        rows[0]["status"] = "closed_stale_unverified"
        json.dump(rows, open(self.tracker, "w"))
        self.assertEqual(self.it.get_stats()["resolved_count"], 1)
        self.assertEqual(self.it.get_stats()["unresolved_count"], 0)
        b = self._log("Severely stale output: data/x.json (49h old)")
        self.assertNotEqual(a, b, "a hygiene-closed row still swallowed a new occurrence")

    # ── compaction ───────────────────────────────────────────────────────────
    def _seed_dupes(self):
        rows = []
        base = datetime.now() - timedelta(days=10)
        for i, age in enumerate((49, 75, 96, 162)):
            rows.append({
                "issue_id": f"ISS-{i+1:04d}", "reporter": "CITPipelineMonitor",
                "title": f"Severely stale output: data/x.json ({age}h old)",
                "description": "d", "severity": "MEDIUM" if i else "HIGH",
                "category": "PIPELINE", "status": "ASSIGNED", "assigned_to": None,
                "created_at": (base + timedelta(hours=i)).isoformat(),
                "updated_at": (base + timedelta(hours=i)).isoformat(),
                "resolved_at": None, "resolution": None, "auto_fix_hint": None,
                "escalation_count": i + 1,
            })
        json.dump(rows, open(self.tracker, "w"))
        return rows

    def test_compaction_folds_re_reports_and_keeps_the_oldest_row(self):
        seeded = self._seed_dupes()
        r = self.it.compact()
        self.assertEqual(r["rows_after"], 1)
        row = self._rows()[0]
        self.assertEqual(row["issue_id"], seeded[0]["issue_id"],
                         "compaction kept a newer row — the staleness clock was reset")
        self.assertEqual(row["occurrences"], 4)
        self.assertEqual(row["severity"], "HIGH", "highest severity ever seen was lost")
        self.assertEqual(row["escalation_count"], 4,
                         "escalation_count should carry the max, not the sum")
        self.assertEqual(row["folded_escalations"], 10)

    def test_compaction_archives_every_row_it_removes(self):
        self._seed_dupes()
        before = {r["issue_id"] for r in self._rows()}
        self.it.compact()
        after = {r["issue_id"] for r in self._rows()}
        archived = {r["issue_id"] for r in json.load(open(self.archive))}
        self.assertEqual(before - after, archived,
                         "rows disappeared without an archive record")
        for r in json.load(open(self.archive)):
            self.assertTrue(r.get("folded_into"), "archived row has no pointer to its survivor")

    def test_compaction_is_idempotent(self):
        self._seed_dupes()
        self.it.compact()
        snapshot = json.dumps(self._rows(), sort_keys=True)
        second = self.it.compact()
        self.assertEqual(second["folded"], 0)
        self.assertEqual(json.dumps(self._rows(), sort_keys=True), snapshot)

    def test_compaction_never_reuses_an_archived_id(self):
        self._seed_dupes()
        self.it.compact()
        archived = {r["issue_id"] for r in json.load(open(self.archive))}
        new = self._log("A brand new and different condition")
        self.assertNotIn(new, archived,
                         "a new issue was minted with an id that already names an archived one")

    def test_compaction_does_not_touch_finished_rows(self):
        rows = self._seed_dupes()
        rows[1]["status"] = "RESOLVED"
        rows[1]["resolved_at"] = datetime.now().isoformat()
        json.dump(rows, open(self.tracker, "w"))
        self.it.compact()
        ids = {r["issue_id"] for r in self._rows()}
        self.assertIn(rows[1]["issue_id"], ids, "compaction folded an already-resolved row")

    def test_a_report_with_no_duplicates_writes_nothing(self):
        self._log("Only condition here")
        r = self.it.compact(dry_run=True)
        self.assertEqual(r["folded"], 0)


class TestTheDetectorClosesWhatItOpens(unittest.TestCase):
    """CITPipelineMonitor filed 220 stale-output issues and closed none."""

    def test_the_monitor_derives_the_close_signature_it_does_not_restate_it(self):
        """AST: _clear_condition must be called with the same title the finding uses.

        A hand-written normalised string ("severely stale output: ... (<age>)")
        would be a second copy of the identity rule, free to drift from
        condition_signature() — the hand-kept-table bug that produced the
        phantom pipeline-restored emails. Grep would match my own comments here,
        so this walks the tree.
        """
        tree = ast.parse(open("cit_director.py").read())
        clear = next((n for n in ast.walk(tree)
                      if isinstance(n, ast.FunctionDef) and n.name == "_clear_condition"), None)
        self.assertIsNotNone(clear, "_clear_condition was removed from cit_director.py")

        sig_kw = [kw for call in ast.walk(clear)
                  if isinstance(call, ast.Call)
                  for kw in call.keywords if kw.arg == "signature"]
        self.assertTrue(sig_kw, "_clear_condition never passes a signature=")
        for kw in sig_kw:
            self.assertIsInstance(
                kw.value, ast.Call,
                "signature= is a literal — it restates the normalisation rule "
                "instead of deriving it from condition_signature()")
            self.assertEqual(
                getattr(kw.value.func, "id", getattr(kw.value.func, "attr", None)),
                "condition_signature")

    def test_every_stale_output_finding_has_a_matching_clear_path(self):
        """Both branches of the freshness test must act: alarm, or retire the alarm."""
        tree = ast.parse(open("cit_director.py").read())
        fn = None
        for cls in ast.walk(tree):
            if isinstance(cls, ast.ClassDef) and cls.name == "CITPipelineMonitor":
                fn = next((n for n in cls.body
                           if isinstance(n, ast.FunctionDef) and n.name == "analyze"), None)
        self.assertIsNotNone(fn, "CITPipelineMonitor.analyze not found")
        calls = [n for n in ast.walk(fn) if isinstance(n, ast.Call)
                 and getattr(n.func, "attr", None) == "_clear_condition"]
        self.assertGreaterEqual(
            len(calls), 2,
            "analyze() opens issues for both 'missing' and 'stale' but closes fewer "
            "kinds than it opens — a detector that cannot retire its own claim "
            "turns a transient fact into a permanent record")


class TestResolutionRegistryHasAProducer(unittest.TestCase):
    """data/resolution_registry.json had two readers and zero writers.

    tracker_hygiene.py's R1 auto-close rule and board_meeting.py's
    "don't resurrect an already-fixed proposal" gate both read it; nothing had
    ever written it, and the file did not exist on either host. R1 therefore
    printed "0 verified-closed" every day for ~6 weeks — indistinguishable from
    a rule with nothing to do — and board_meeting's `_fixed` was pinned False.
    """

    def setUp(self):
        import issue_tracker as it
        self.it = it
        self.td = tempfile.mkdtemp()
        self.tracker  = os.path.join(self.td, "issues.json")
        self.archive  = os.path.join(self.td, "archive.json")
        self.registry = os.path.join(self.td, "registry.json")
        self.p = patch.multiple(it, TRACKER_PATH=self.tracker, ARCHIVE_PATH=self.archive,
                                REGISTRY_PATH=self.registry)
        self.p.start()

    def tearDown(self):
        self.p.stop()
        shutil.rmtree(self.td, ignore_errors=True)

    def test_the_registry_module_names_a_writer(self):
        """AST: at least one function in issue_tracker.py writes REGISTRY_PATH.

        Grep would match the postmortem comments above, so resolve the call.
        """
        tree = ast.parse(Path(__file__).with_name("issue_tracker.py").read_text())
        fns = {n.name for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)}
        self.assertIn("record_resolution", fns,
                      "the registry has readers but no producer function")
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "record_resolution")
        opens = [n for n in ast.walk(fn) if isinstance(n, ast.Call)
                 and getattr(n.func, "id", None) == "open"
                 and len(n.args) > 1]
        self.assertTrue(opens, "record_resolution() never opens the registry for writing")

    def test_resolving_an_issue_records_a_matcher(self):
        iid = self.it.log_issue("CIT", "data/x.json is 40h old", "d", "HIGH", "PIPELINE")
        self.assertFalse(self.it.load_resolution_registry())
        self.it.resolve_issue(iid, "producer rescheduled", "me")
        reg = self.it.load_resolution_registry()
        self.assertEqual(len(reg), 1)
        self.assertEqual(reg[0]["signature"], self.it.condition_signature("data/x.json is 40h old"))
        self.assertEqual(reg[0]["by"], "me")

    def test_the_recorded_signature_is_age_independent(self):
        """The matcher must survive the number moving, or it closes nothing later."""
        iid = self.it.log_issue("CIT", "data/x.json is 40h old", "d", "HIGH", "PIPELINE")
        self.it.resolve_issue(iid, "fixed", "me")
        sig = self.it.load_resolution_registry()[0]["signature"]
        self.assertEqual(sig, self.it.condition_signature("data/x.json is 900h old"))

    def test_the_same_fix_is_not_recorded_twice(self):
        a = self.it.log_issue("CIT", "data/x.json is 40h old", "d", "HIGH", "PIPELINE")
        self.it.resolve_issue(a, "fixed", "me")
        b = self.it.log_issue("OTHER", "data/x.json is 41h old", "d", "HIGH", "PIPELINE")
        self.it.resolve_issue(b, "fixed again", "me")
        self.assertEqual(len(self.it.load_resolution_registry()), 1)

    def test_an_entry_with_neither_key_is_refused(self):
        self.assertFalse(self.it.record_resolution(note="n", by="me"))
        self.assertEqual(self.it.load_resolution_registry(), [])

    def test_the_registry_is_capped(self):
        for n in range(self.it.REGISTRY_MAX + 20):
            self.it.record_resolution(note="n", by="me", signature=f"sig-{n}")
        reg = self.it.load_resolution_registry()
        self.assertEqual(len(reg), self.it.REGISTRY_MAX)
        # Oldest dropped, newest kept — a cap that trimmed the tail would keep
        # the fixes whose issues are already closed and drop the fresh ones.
        self.assertEqual(reg[-1]["signature"], f"sig-{self.it.REGISTRY_MAX + 19}")

    def test_a_missing_registry_reads_as_empty_not_an_error(self):
        self.assertEqual(self.it.load_resolution_registry(), [])


class TestTheTrackerSurvivesConcurrentWriters(unittest.TestCase):
    """Row counts in git are not monotonic: 2414 -> 1303 -> 2266 -> 3886.

    Three compounding defects, all in ~30 lines of file I/O:
      * _save() opened the live file with "w", which TRUNCATES at open — before
        flock() was called. The exclusive lock could not protect content that
        was already gone.
      * _load() therefore met an empty or half-written file, json.load raised,
        and the except handler returned [] — a failed read wearing the costume
        of a legitimately empty tracker. Measured on a 2000-row file: 14 of 300
        concurrent reads came back empty.
      * the caller then appended one issue to that [] and saved it. Two
        thousand rows, gone, with no error anywhere.
      * and the lock never spanned load->mutate->save anyway, so even a clean
        read lost the other writer's row.
    No issue in the live tracker predates 2026-08-06.
    """

    def setUp(self):
        import issue_tracker as it
        self.it = it
        self.td = tempfile.mkdtemp()
        self.tracker  = os.path.join(self.td, "issues.json")
        self.p = patch.multiple(it, TRACKER_PATH=self.tracker,
                                ARCHIVE_PATH=os.path.join(self.td, "archive.json"),
                                REGISTRY_PATH=os.path.join(self.td, "registry.json"))
        self.p.start()

    def tearDown(self):
        self.p.stop()
        shutil.rmtree(self.td, ignore_errors=True)

    def test_a_reader_never_sees_a_half_written_file(self):
        """os.replace is atomic, so there is no window where the file is empty."""
        seed = [{"issue_id": f"ISS-{n}", "status": "OPEN", "title": f"t{n}"}
                for n in range(500)]
        self.it._save(seed)
        empties = []

        def churn():
            for _ in range(60):
                self.it._save(seed)

        t = threading.Thread(target=churn)
        t.start()
        for _ in range(200):
            if len(self.it._load()) == 0:
                empties.append(1)
        t.join()
        self.assertEqual(empties, [],
                         "a concurrent read saw an empty tracker; the next write "
                         "would have persisted that emptiness")

    def test_concurrent_writers_do_not_drop_each_others_rows(self):
        """The real race: two agents log a different issue at the same moment."""
        errors = []

        def log(n):
            try:
                for i in range(12):
                    self.it.log_issue(f"agent{n}", f"finding {n}-{i}", "d", "LOW", "PIPELINE")
            except Exception as e:                        # noqa: BLE001
                errors.append(e)

        threads = [threading.Thread(target=log, args=(n,)) for n in range(4)]
        for t in threads: t.start()
        for t in threads: t.join()
        self.assertEqual(errors, [])
        rows = json.load(open(self.tracker))
        self.assertEqual(len(rows), 48,
                         f"4 writers x 12 distinct findings should be 48 rows, got {len(rows)}")
        self.assertEqual(len({r["issue_id"] for r in rows}), 48,
                         "issue_ids collided — _next_id read a stale file")

    def test_an_unreadable_tracker_is_moved_aside_not_overwritten(self):
        Path(self.tracker).write_text("{ this is not json")
        iid = self.it.log_issue("CIT", "something", "d", "HIGH", "PIPELINE")
        self.assertTrue(iid)
        corrupt = list(Path(self.td).glob("issues.json.corrupt-*"))
        self.assertEqual(len(corrupt), 1, "the unparseable bytes were destroyed")
        self.assertEqual(corrupt[0].read_text(), "{ this is not json")

    def test_compaction_refuses_an_unreadable_tracker(self):
        """Starting compaction from [] would write an empty tracker and archive nothing."""
        Path(self.tracker).write_text("{ this is not json")
        with self.assertRaises(self.it.TrackerUnreadable):
            self.it.compact(dry_run=True)

    def test_a_tracker_that_is_not_a_list_is_not_silently_replaced(self):
        Path(self.tracker).write_text('{"issues": []}')
        with self.assertRaises(self.it.TrackerUnreadable):
            self.it._load(strict=True)

    def test_an_absent_tracker_is_legitimately_empty(self):
        """"No file" and "unreadable file" must not take the same branch."""
        self.assertEqual(self.it._load(strict=True), [])

    def test_no_locked_function_calls_another(self):
        """flock is per file description, so nesting @_locked would self-deadlock."""
        tree = ast.parse(Path(__file__).with_name("issue_tracker.py").read_text())
        locked = {n.name for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)
                  and any(getattr(d, "id", None) == "_locked" for d in n.decorator_list)}
        self.assertTrue(locked, "no function carries @_locked — the lock was dropped")
        for n in ast.walk(tree):
            if isinstance(n, ast.FunctionDef) and n.name in locked:
                called = {c.func.id for c in ast.walk(n)
                          if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)}
                self.assertFalse(
                    called & locked,
                    f"{n.name}() calls {called & locked} — both take the same "
                    f"exclusive flock and the process would hang forever")

    def test_every_mutating_path_is_locked(self):
        """AST: any function that both loads and saves must hold the lock.

        A new writer added without @_locked reintroduces the lost update, and
        it would look completely fine in review.
        """
        tree = ast.parse(Path(__file__).with_name("issue_tracker.py").read_text())
        unlocked = []
        for n in ast.walk(tree):
            if not isinstance(n, ast.FunctionDef) or n.name.startswith("_"):
                continue
            names = {c.func.id for c in ast.walk(n)
                     if isinstance(c, ast.Call) and isinstance(c.func, ast.Name)}
            if "_save" in names and names & {"_load", "_load_for_write"}:
                if not any(getattr(d, "id", None) == "_locked" for d in n.decorator_list):
                    unlocked.append(n.name)
        self.assertEqual(unlocked, [],
                         f"read-modify-write without @_locked: {unlocked}")

    def test_no_writer_truncates_the_live_file(self):
        """AST: open(TRACKER_PATH, "w") is the defect itself — it must not come back."""
        tree = ast.parse(Path(__file__).with_name("issue_tracker.py").read_text())
        for c in ast.walk(tree):
            if isinstance(c, ast.Call) and getattr(c.func, "id", None) == "open" \
                    and len(c.args) > 1:
                target = getattr(c.args[0], "id", None)
                mode = getattr(c.args[1], "value", None)
                self.assertFalse(
                    target == "TRACKER_PATH" and isinstance(mode, str) and "w" in mode,
                    f"line {c.lineno}: open(TRACKER_PATH, {mode!r}) truncates before "
                    f"any lock can be taken — write to a temp file and os.replace")


class TestNoWriterTruncatesBeforeItLocks(unittest.TestCase):
    """Repo-wide: `open(p, "w")` destroys the file's contents at open().

    A flock taken on the next line is decoration — the bytes are already gone,
    and any concurrent reader gets an empty or half-written file. Six sites
    shipped this: issue_tracker._save (which lost the tracker outright) plus
    five agents that shared one FIXED ".json.tmp" path between all writers, so
    a second writer could empty the first's temp file mid-dump and the first
    would then rename the torn result over the live file.

    The correct shape is mkstemp (a private name per writer) + os.replace,
    which is atomic and needs no lock at all.
    """

    def test_no_module_locks_a_handle_it_already_truncated(self):
        offenders = []
        for f in sorted(Path(__file__).parent.rglob("*.py")):
            if "__pycache__" in str(f) or f.name == Path(__file__).name:
                continue
            try:
                tree = ast.parse(f.read_text())
            except SyntaxError:
                continue
            for w in ast.walk(tree):
                if not isinstance(w, ast.With):
                    continue
                for item in w.items:
                    c = item.context_expr
                    if not (isinstance(c, ast.Call)
                            and getattr(c.func, "id", None) == "open"
                            and len(c.args) > 1):
                        continue
                    mode = getattr(c.args[1], "value", "")
                    if not (isinstance(mode, str) and "w" in mode):
                        continue
                    var = getattr(item.optional_vars, "id", None)
                    if var and any(isinstance(n, ast.Call)
                                   and getattr(n.func, "attr", None) == "flock"
                                   and n.args
                                   and getattr(n.args[0], "id", None) == var
                                   for n in ast.walk(w)):
                        offenders.append(f"{f.name}:{w.lineno}")
        self.assertEqual(
            offenders, [],
            "these lock a handle whose open() already truncated the file: "
            + ", ".join(offenders))


class TestTheAlertQueueSurvivesConcurrentProducers(unittest.TestCase):
    """data/email_buffer.json is the ONLY channel that reaches Jack.

    `_save_buffer` did `open(BUFFER_PATH, "w")` with no lock and no atomic
    rename, and `buffer_email` was an unlocked load-append-save on top of it.
    Measured before the fix: 200 concurrent enqueues left 7 survivors, and 68
    of 300 reads on a 400-entry queue came back empty — whereupon the next
    producer saved that empty list and the day's alerts were gone.

    A lost alert here is worse than a lost issue-tracker row: the tracker keeps
    the finding and merely delays it, while this drops the only copy of a
    message on its way to a human.
    """

    def setUp(self):
        import email_buffer as eb
        self.eb = eb
        self.td = tempfile.mkdtemp()
        self.buf = os.path.join(self.td, "email_buffer.json")
        self.stamp = os.path.join(self.td, ".digest_last_sent")
        self.p = patch.multiple(eb, BUFFER_PATH=self.buf,
                                DIGEST_STAMP_PATH=self.stamp)
        self.p.start()
        self.addCleanup(self.p.stop)
        self.addCleanup(shutil.rmtree, self.td, True)

    def test_concurrent_producers_do_not_drop_each_others_messages(self):
        def worker(t):
            for i in range(12):
                self.eb.buffer_email(subject=f"m-{t}-{i}", html_body="x",
                                     sender_name="probe")
        threads = [threading.Thread(target=worker, args=(t,)) for t in range(4)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()
        subjects = [e["subject"] for e in self.eb._load_buffer()]
        self.assertEqual(len(subjects), 48,
                         f"48 producers enqueued, {len(subjects)} survived")
        self.assertEqual(len(set(subjects)), 48, "duplicate subjects written")

    def test_a_reader_never_sees_a_half_written_queue(self):
        rows = [{"subject": f"s{i}", "html_body": "y"} for i in range(300)]
        self.eb._save_buffer(rows)
        empties, stop = [], threading.Event()

        def churn():
            while not stop.is_set():
                self.eb._save_buffer(rows)

        w = threading.Thread(target=churn)
        w.start()
        try:
            for _ in range(200):
                if len(self.eb._load_buffer()) != 300:
                    empties.append(1)
        finally:
            stop.set()
            w.join()
        self.assertEqual(empties, [], f"{len(empties)}/200 reads saw a torn queue")

    def test_an_unreadable_queue_is_moved_aside_not_overwritten(self):
        with open(self.buf, "w") as f:
            f.write("{not json at all")
        self.eb.buffer_email(subject="new", html_body="x")
        saved = [p for p in os.listdir(self.td) if ".corrupt-" in p]
        self.assertTrue(saved, "unreadable queue was overwritten, not quarantined")
        with open(os.path.join(self.td, saved[0])) as f:
            self.assertIn("not json", f.read())

    def test_a_queue_that_is_not_a_list_is_not_silently_accepted(self):
        with open(self.buf, "w") as f:
            json.dump({"subject": "a dict, not a queue"}, f)
        with self.assertRaises(self.eb.BufferUnreadable):
            self.eb._load_buffer(strict=True)

    def test_an_absent_queue_is_legitimately_empty(self):
        self.assertFalse(os.path.exists(self.buf))
        self.assertEqual(self.eb._load_buffer(strict=True), [])

    # ── the receipt ──────────────────────────────────────────────────────────

    def test_the_receipt_names_the_subjects_it_sent(self):
        self.eb._stamp_digest_sent(2, ["alpha", "beta"])
        with open(self.stamp) as f:
            stamp = json.load(f)
        self.assertEqual(stamp["subjects"], ["alpha", "beta"])

    def test_a_message_in_the_manifest_reads_delivered(self):
        self.eb._stamp_digest_sent(1, ["Kalshi verdict: premise DEAD"])
        state, why = self.eb.delivery_state(
            "2020-01-01T00:00:00", "Kalshi verdict: premise DEAD")
        self.assertEqual(state, "delivered", why)

    def test_a_message_dropped_before_the_send_reads_lost_not_delivered(self):
        """The clock alone said 'delivered' for a message that was destroyed.

        This is the whole reason the manifest exists: a receipt proving that
        SOME digest went out after the enqueue is not a receipt proving THIS
        message was in it.
        """
        self.eb._stamp_digest_sent(3, ["other-a", "other-b", "other-c"])
        state, why = self.eb.delivery_state("2020-01-01T00:00:00", "vanished")
        self.assertEqual(state, "lost", why)
        self.assertIn("not among them", why)

    def test_a_queued_message_reads_pending_even_with_a_later_receipt(self):
        self.eb._save_buffer([{"subject": "waiting", "html_body": "x"}])
        self.eb._stamp_digest_sent(1, ["something else"])
        state, _ = self.eb.delivery_state("2020-01-01T00:00:00", "waiting")
        self.assertEqual(state, "pending")

    def test_a_receipt_older_than_the_enqueue_still_reads_lost(self):
        self.eb._stamp_digest_sent(1, ["anything"])
        state, _ = self.eb.delivery_state("2099-01-01T00:00:00", "anything")
        self.assertEqual(state, "lost")

    def test_a_legacy_receipt_without_a_manifest_admits_it_is_inferring(self):
        """Upgrading must not mail Jack a backlog he already read.

        A receipt written before the manifest existed cannot answer membership,
        so it falls back to the clock — but it has to SAY it fell back, or the
        caller is holding a weaker answer than it thinks it is.
        """
        with open(self.stamp, "w") as f:
            json.dump({"date": "2026-08-23", "sent_at": "2026-08-23T22:00:00",
                       "reports": 15}, f)
        state, why = self.eb.delivery_state("2026-08-23T11:45:00", "anything")
        self.assertEqual(state, "delivered")
        self.assertIn("no subject manifest", why)

    # ── the deadlock that would silence the firm ─────────────────────────────

    def test_no_locked_function_calls_another(self):
        """flock is per open file description, so nesting them self-deadlocks.

        A deadlocked `flush_digest` is total email silence to Jack — the worst
        failure this module has — and it would present as "the digest just
        stopped arriving", with no error anywhere.
        """
        import email_buffer as eb
        tree = ast.parse(Path(eb.__file__).read_text())
        locked = {n.name for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef)
                  and any(getattr(d, "id", None) == "_locked" for d in n.decorator_list)}
        self.assertTrue(locked, "no @_locked functions found — did they get renamed?")
        offenders = []
        for n in ast.walk(tree):
            if not (isinstance(n, ast.FunctionDef) and n.name in locked):
                continue
            for c in ast.walk(n):
                if isinstance(c, ast.Call) and getattr(c.func, "id", None) in locked:
                    offenders.append(f"{n.name} -> {c.func.id}")
        self.assertEqual(offenders, [], f"nested lock acquisition: {offenders}")

    def test_the_digest_does_not_enqueue_an_email_while_holding_the_lock(self):
        """Anything flush_digest imports must not route back into buffer_email.

        `mail_guard.send_email` DOES call buffer_email — flush_digest avoids it
        by using smtplib directly under `allow_direct`. If a future edit sends
        a status mail through the normal path from inside this function, the
        digest deadlocks and Jack hears nothing at all.
        """
        import email_buffer as eb
        tree = ast.parse(Path(eb.__file__).read_text())
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "flush_digest")
        called = {getattr(c.func, "id", None) or getattr(c.func, "attr", None)
                  for c in ast.walk(fn) if isinstance(c, ast.Call)}
        for forbidden in ("buffer_email", "send_email"):
            self.assertNotIn(forbidden, called,
                             f"flush_digest calls {forbidden} while holding the "
                             f"buffer lock — this deadlocks the digest")

    def test_the_buffer_is_never_truncated_in_place(self):
        import email_buffer as eb
        src = ast.parse(Path(eb.__file__).read_text())
        fn = next(n for n in ast.walk(src)
                  if isinstance(n, ast.FunctionDef) and n.name == "_save_buffer")
        names = {getattr(c.func, "id", None) or getattr(c.func, "attr", None)
                 for c in ast.walk(fn) if isinstance(c, ast.Call)}
        self.assertIn("mkstemp", names, "_save_buffer must write to a private temp")
        self.assertIn("replace", names, "_save_buffer must swap in atomically")
        self.assertNotIn("open", names, "_save_buffer must not open the live path")


class TestThePrePushGateIsTheOneWeShip(unittest.TestCase):
    """One tracked copy of the gate, and CLAUDE.md must name its real path.

    The hook's own header records that the hardened version once lived only in
    .git/hooks while the tracked copy stayed a fail-open stub, so the documented
    install command DOWNGRADED the gate. The repair left a second tracked copy
    at institutional-tracker/scripts/git-hooks/pre-push, three weeks stale — and
    CLAUDE.md's install block sits under `cd institutional-tracker`, so a reader
    following it landed on the stale one. The hook's own drift self-check could
    not see this: it compares the installed file against $ROOT/scripts/..., and
    a second copy somewhere else is invisible to it.
    """

    @staticmethod
    def _root():
        return Path(__file__).resolve().parent.parent

    def _tracked_hooks(self):
        import subprocess
        out = subprocess.run(["git", "ls-files"], cwd=str(self._root()),
                             capture_output=True, text=True)
        if out.returncode != 0:
            self.skipTest("not a git checkout (the VM is rsynced, not cloned)")
        return [p for p in out.stdout.split("\n") if p.endswith("git-hooks/pre-push")]

    def test_exactly_one_tracked_copy_of_the_hook(self):
        tracked = self._tracked_hooks()
        self.assertEqual(
            1, len(tracked),
            f"{len(tracked)} tracked copies of the pre-push gate: {tracked}. "
            f"Two copies means one of them is stale and somebody will install "
            f"it; the hook's drift self-check only ever compares against one.")

    def test_claude_md_names_the_path_that_actually_exists(self):
        tracked = self._tracked_hooks()
        if len(tracked) != 1:
            self.skipTest("covered by test_exactly_one_tracked_copy_of_the_hook")
        real = tracked[0]                     # e.g. "scripts/git-hooks/pre-push"
        doc = (self._root() / "CLAUDE.md").read_text()
        install = [ln for ln in doc.split("\n")
                   if "git-hooks/pre-push" in ln and ln.lstrip().startswith(("cp ", "cd "))]
        self.assertTrue(install, "CLAUDE.md no longer documents installing the gate")
        for ln in install:
            self.assertIn(
                real, ln,
                f"CLAUDE.md's install line points somewhere other than the one "
                f"tracked hook ({real}):\n  {ln.strip()}")
            self.assertIn(
                "rev-parse --show-toplevel", ln,
                "the install line must anchor itself to the repo root — the gate "
                "is at the root and the surrounding block runs from "
                "institutional-tracker/, where that relative path meant a "
                "different, staler file:\n  " + ln.strip())

    def test_the_gate_still_fails_closed_and_checks_the_production_zone(self):
        tracked = self._tracked_hooks()
        if len(tracked) != 1:
            self.skipTest("covered by test_exactly_one_tracked_copy_of_the_hook")
        body = (self._root() / tracked[0]).read_text()

        # Comments STRIPPED. The hook's header narrates the old fail-open bug
        # verbatim, so a plain `assertNotIn("|| exit 0", body)` fails on the
        # postmortem describing the fix — the same reason every guard in this
        # file reads structure rather than text.
        code = "\n".join(ln for ln in body.split("\n")
                         if not ln.lstrip().startswith("#"))

        # This was `assertIn("TZ=UTC", code)` and it could not fail: the hook
        # names TZ=UTC in its own BLOCKED message, so the substring survives
        # even if the second suite run is deleted outright. Two guards covered
        # this property and only one of them could ever fire. Same structural
        # check as TestThePushGateIsTheGateTheRepoShips — the property is "a run
        # of the suite carries TZ=UTC in its env prefix", not "the file contains
        # the letters TZ=UTC".
        runs = [ln for ln in code.split("\n")
                if re.search(r"python3?\s+test_pipeline_smoke\.py", ln)]
        self.assertTrue(
            [ln for ln in runs
             if re.match(r"^\s*(\w+=\S+\s+)*TZ=UTC(\s+\w+=\S+)*\s+python3?\s", ln)],
            "the gate must RUN the suite in the VM's zone too — green on the "
            "Mac is not green. Invocations found:\n  " + "\n  ".join(runs))
        self.assertNotIn("|| exit 0", code,
                         "a gate that exits 0 when confused allows every push")
        self.assertIn("|| exit 0", body,
                      "the header stopped explaining WHY the gate fails closed — "
                      "if that postmortem was deleted, the next person to hit a "
                      "confusing tree will re-add the escape hatch")

    def test_the_internal_audit_can_still_find_the_hook_it_ships(self):
        """Deleting the duplicate must not blind the liveness check to the gate.

        `_detector_liveness` reads the shipped hook to decide whether a
        test-suite detector is PUSH_ONLY or runs nowhere at all. It used to
        resolve that path under institutional-tracker/ — the copy this change
        deletes — so the dedup silently downgraded every suite-backed detector
        to "nothing runs it". Same shape as `fix_that_erased_its_detector`.
        """
        import internal_audit_agent as iaa
        if not (self._root() / "scripts/git-hooks/pre-push").exists():
            # The VM is rsynced from institutional-tracker/, so the repo root
            # is not there at all. Asserting here would fail on the VM for a
            # reason that has nothing to do with the audit — and the two-zone
            # push gate runs this suite on both (memory
            # `host_divergence_is_a_bug_class`). The missing-hook branch is
            # covered by the next test, which does not depend on the host.
            self.skipTest("no repo root on this host (rsynced, not cloned)")
        live = iaa._detector_liveness(["test_pipeline_smoke.py::TestWrongfulRetirement"])
        status, why = live["test_pipeline_smoke.py::TestWrongfulRetirement"]
        self.assertEqual(
            iaa.PUSH_ONLY, status,
            f"the audit no longer sees the gate that runs the suite: {why}")

    def test_a_missing_hook_is_unknown_not_unscheduled(self):
        """Absent evidence must not be reported as evidence of absence.

        The VM has no repo root (deploy.sh rsyncs institutional-tracker/ only),
        so on that host the hook genuinely cannot be read. Claiming
        UNSCHEDULED there would be the control manufacturing a finding from a
        host difference.
        """
        import internal_audit_agent as iaa
        import tempfile
        ref = "test_pipeline_smoke.py::TestWrongfulRetirement"
        with tempfile.TemporaryDirectory() as d:
            saved = iaa.BASE_DIR
            try:
                iaa.BASE_DIR = Path(d)
                status, why = iaa._detector_liveness([ref])[ref]
            finally:
                iaa.BASE_DIR = saved
        if "crontab snapshot" in why:
            # The whole function short-circuits when the schedule is unreadable,
            # so we never reached the branch under test. Passing on that would
            # be answering this question with the other branch's evidence.
            self.skipTest("no crontab snapshot on this host")
        self.assertEqual(iaa.UNKNOWN_RUN, status, why)
        self.assertIn("cannot be determined", why)


class TestInterruptedWriteDetectorStillFires(unittest.TestCase):
    """A poison pill for `wiring_audit.check_interrupted_writes`.

    The six real corpses it found on 2026-08-23 were archived, so its live
    output is now the reassuring "OK — 0 orphaned temp files". That is exactly
    the state in which a broken detector is indistinguishable from a clean
    system (see memory `presence-is-not-currency`). So: hand it a directory
    containing one known corpse and require it to say so.
    """

    def _run(self, dirpath):
        import wiring_audit
        saved = wiring_audit.notes
        wiring_audit.notes = []
        try:
            wiring_audit.check_interrupted_writes(data_dir=dirpath)
            return list(wiring_audit.notes)
        finally:
            wiring_audit.notes = saved

    def test_a_planted_corpse_is_reported(self):
        import os
        import tempfile
        import time
        with tempfile.TemporaryDirectory() as d:
            corpse = os.path.join(d, "tmpDEADBEEF.tmp")
            with open(corpse, "w") as f:
                f.write("{partial")
            old = time.time() - 9 * 3600
            os.utime(corpse, (old, old))
            out = self._run(d)
        self.assertEqual(len(out), 1, out)
        self.assertIn("1 orphaned temp file", out[0])
        self.assertIn("tmpDEADBEEF.tmp", out[0])

    def test_a_fresh_temp_is_not_a_corpse(self):
        """A writer mid-`os.replace` right now is not evidence of anything."""
        import os
        import tempfile
        with tempfile.TemporaryDirectory() as d:
            with open(os.path.join(d, "tmpLIVE.tmp"), "w") as f:
                f.write("{}")
            out = self._run(d)
        self.assertEqual(len(out), 1, out)
        self.assertIn("0 orphaned temp files", out[0])

    def test_the_clean_note_still_carries_a_denominator(self):
        """"OK" on a directory that moved is a false pass — demand the count."""
        import json
        import os
        import tempfile
        with tempfile.TemporaryDirectory() as d:
            for i in range(3):
                with open(os.path.join(d, f"f{i}.json"), "w") as f:
                    json.dump({}, f)
            out = self._run(d)
        self.assertIn("3 json files examined", out[0])


class TestAtomicJsonIsActuallyAtomic(unittest.TestCase):
    """The helper the whole firm now routes shared-file writes through.

    Every assertion here corresponds to a way the hand-rolled version failed in
    production, so a regression in `atomic_json` is a regression in six modules
    at once.
    """

    def setUp(self):
        import tempfile as _tf
        self._dir = _tf.mkdtemp(prefix="aj-test-")
        self.path = os.path.join(self._dir, "queue.json")

    def tearDown(self):
        import shutil
        shutil.rmtree(self._dir, ignore_errors=True)

    # ── the loss the lock exists to stop ─────────────────────────────────
    def test_concurrent_appenders_do_not_overwrite_each_other(self):
        """200 appends from 8 threads → 200 rows. Unlocked this loses ~95%."""
        import atomic_json as aj
        import threading

        aj.write(self.path, [])

        def append(worker):
            for i in range(25):
                with aj.update(self.path, default=[], expect=list) as rows:
                    rows.append({"w": worker, "i": i})

        threads = [threading.Thread(target=append, args=(w,)) for w in range(8)]
        for t in threads:
            t.start()
        for t in threads:
            t.join()

        rows = aj.read(self.path, default=None, expect=list)
        self.assertEqual(len(rows), 200,
                         f"lost {200 - len(rows)} of 200 concurrent appends")
        self.assertEqual(len({(r["w"], r["i"]) for r in rows}), 200,
                         "rows were duplicated rather than merged")

    def test_a_reader_never_observes_a_half_written_file(self):
        """No reader sees [] or a truncated body while a writer is mid-dump."""
        import atomic_json as aj
        import threading

        big = [{"n": n, "pad": "x" * 200} for n in range(400)]
        aj.write(self.path, big)

        empties, stop = [], threading.Event()

        def reader():
            while not stop.is_set():
                got = aj.read(self.path, default=None, expect=list)
                if not got or len(got) != 400:
                    empties.append(got)

        def writer():
            for _ in range(60):
                aj.write(self.path, big)

        r = threading.Thread(target=reader)
        r.start()
        w = threading.Thread(target=writer)
        w.start()
        w.join()
        stop.set()
        r.join()

        self.assertEqual(empties, [],
                         f"{len(empties)} read(s) saw a torn or empty file")

    # ── a degraded read must not look like a legitimate empty ────────────
    def test_absent_and_unreadable_do_not_share_an_answer(self):
        import atomic_json as aj

        # absent → the default, because building on nothing is correct
        self.assertEqual(aj.read(self.path, default=[], strict=True), [])

        # present but garbage → NOT the default. The caller's next move after a
        # read on the mutating path is a write.
        with open(self.path, "w") as f:
            f.write("{not json")
        with self.assertRaises(aj.Unreadable):
            aj.read(self.path, default=[], strict=True)

    def test_a_file_of_the_wrong_shape_is_unreadable_not_empty(self):
        import atomic_json as aj
        aj.write(self.path, {"a": 1})
        with self.assertRaises(aj.Unreadable):
            aj.read(self.path, default=[], strict=True, expect=list)

    def test_unreadable_bytes_are_quarantined_never_overwritten(self):
        import atomic_json as aj
        import glob

        with open(self.path, "w") as f:
            f.write("{truncated mid-dump")

        got = aj.read_for_write(self.path, default=[], expect=list)
        self.assertEqual(got, [])

        saved = glob.glob(self.path + ".corrupt-*")
        self.assertEqual(len(saved), 1,
                         "the unparseable bytes must be archived, not deleted")
        with open(saved[0]) as f:
            self.assertEqual(f.read(), "{truncated mid-dump")

    # ── failures are reported, not swallowed ─────────────────────────────
    def test_a_failed_write_raises_and_leaves_no_debris(self):
        """A caller that could not persist must not go on believing it did."""
        import atomic_json as aj

        aj.write(self.path, [{"keep": "me"}])
        circular = {}
        circular["self"] = circular          # json.dump raises on this

        with self.assertRaises(ValueError):
            aj.write(self.path, circular)

        self.assertEqual(aj.read(self.path, default=None),
                         [{"keep": "me"}],
                         "a failed write must not damage the live file")
        leftovers = [n for n in os.listdir(self._dir) if n.endswith(".tmp")]
        self.assertEqual(leftovers, [], f"temp files left behind: {leftovers}")

    def test_a_raising_body_does_not_write(self):
        import atomic_json as aj
        aj.write(self.path, [1, 2, 3])
        with self.assertRaises(RuntimeError):
            with aj.update(self.path, default=[], expect=list) as rows:
                rows.append(4)
                raise RuntimeError("the caller changed its mind")
        self.assertEqual(aj.read(self.path, default=None), [1, 2, 3])

    # ── the two structural properties, checked in the source ─────────────
    def test_the_temp_name_is_private_to_this_writer(self):
        """`path + '.tmp'` is a name every concurrent writer shares."""
        import atomic_json as aj
        fn = next(n for n in ast.walk(ast.parse(Path(aj.__file__).read_text()))
                  if isinstance(n, ast.FunctionDef) and n.name == "write")
        calls = {getattr(c.func, "id", None) or getattr(c.func, "attr", None)
                 for c in ast.walk(fn) if isinstance(c, ast.Call)}
        self.assertIn("mkstemp", calls)
        self.assertIn("fsync", calls)
        self.assertIn("replace", calls)
        for node in ast.walk(fn):
            if isinstance(node, ast.Constant) and node.value == ".tmp":
                parent_is_concat = any(
                    isinstance(b, ast.BinOp) and isinstance(b.op, ast.Add)
                    and node in ast.walk(b) for b in ast.walk(fn))
                self.assertFalse(parent_is_concat,
                                 "'.tmp' must be a mkstemp suffix, never "
                                 "concatenated onto the live path")

    def test_the_lock_lives_beside_the_file_not_inside_it(self):
        """write() renames over the path, so a lock held on it follows a dead
        inode and the next writer locks a different file entirely."""
        import atomic_json as aj
        fn = next(n for n in ast.walk(ast.parse(Path(aj.__file__).read_text()))
                  if isinstance(n, ast.FunctionDef) and n.name == "locked")
        suffixes = [n.value for n in ast.walk(fn)
                    if isinstance(n, ast.Constant) and n.value == ".lock"]
        self.assertTrue(suffixes, "locked() must use a sidecar <path>.lock")

        import glob
        with aj.locked(self.path):
            pass
        self.assertTrue(glob.glob(self.path + ".lock"))


class TestNoSharedJsonFileIsWrittenUnsafely(unittest.TestCase):
    """The invariant the whole atomic_json exercise bought.

    Measured the wrong way first: counting modules that *mention* a filename and
    dump json *somewhere* reported 50 shared files, top hit 15 writers. Tying the
    filename to the actual write site gives 3. A 17x overstatement — so this test
    resolves the write site, and a fix that only looked right against the loose
    count would not pass it.
    """

    #: A path here is written raw by more than one module. The correct size of
    #: this list is zero: route the writes through `atomic_json.update()` (or a
    #: single-source-of-truth module like chairman_queue) rather than adding an
    #: entry.
    ALLOWED_MULTI_WRITER = frozenset()

    @staticmethod
    def _write_sites(root):
        """(raw, guarded, idioms) — every truncating write, by resolved filename.

        FOUR idioms, because the first version of this sweep only understood
        `with open(p, "w")` and so could not see:
          * 21 modules using a bare `open(p, "w")` outside a with-statement,
          * `Path.write_text(json.dumps(...))`, which truncates identically,
          * module-local `_save_json(path, data)` helpers, where the filename is
            at the CALL site and the truncation is inside the helper.
        Each blind spot is a place a second writer could hide while the sweep
        reported zero (memory `auditor_ground_truth`).
        """
        import re as _re
        from collections import defaultdict, Counter
        NAME = _re.compile(r"([A-Za-z0-9_.\-]+\.json)")

        def names_in(node, consts):
            out = []
            for n in ast.walk(node):
                if isinstance(n, ast.Constant) and isinstance(n.value, str):
                    out += NAME.findall(n.value)
                elif isinstance(n, ast.Name) and n.id in consts:
                    out += NAME.findall(consts[n.id])
                elif isinstance(n, ast.Attribute):
                    out += NAME.findall(consts.get(n.attr, ""))
            return out

        def raw_target(n):
            """The path expression a truncating write targets, or None."""
            if not isinstance(n, ast.Call):
                return None
            if getattr(n.func, "id", None) == "open" and len(n.args) > 1:
                mode = getattr(n.args[1], "value", "")
                if isinstance(mode, str) and mode.startswith("w"):
                    return n.args[0]
            if getattr(n.func, "attr", None) == "write_text":
                return getattr(n.func, "value", None)
            return None

        raw, guarded = defaultdict(set), defaultdict(set)
        idioms = Counter()
        for f in sorted(Path(root).rglob("*.py")):
            s = str(f)
            if "__pycache__" in s or "/venv" in s or f.name.startswith("_"):
                continue
            if f.name in ("test_pipeline_smoke.py", "wiring_audit.py"):
                continue
            try:
                tree = ast.parse(f.read_text())
            except (SyntaxError, UnicodeDecodeError, OSError):
                continue
            consts = {}
            for n in tree.body:
                if (isinstance(n, ast.Assign) and isinstance(n.value, ast.Constant)
                        and isinstance(n.value.value, str)):
                    for t in n.targets:
                        if isinstance(t, ast.Name):
                            consts[t.id] = n.value.value

            in_with = {id(i.context_expr) for w in ast.walk(tree)
                       if isinstance(w, ast.With) for i in w.items}

            # Helpers that truncate whatever path they are handed.
            helpers = set()
            for fn in ast.walk(tree):
                if not (isinstance(fn, ast.FunctionDef) and fn.args.args):
                    continue
                first = fn.args.args[0].arg
                for n in ast.walk(fn):
                    t = raw_target(n)
                    if isinstance(t, ast.Name) and t.id == first:
                        helpers.add(fn.name)

            for n in ast.walk(tree):
                t = raw_target(n)
                if t is not None:
                    idioms["write_text" if getattr(n.func, "attr", None) == "write_text"
                           else ("with_open" if id(n) in in_with else "bare_open")] += 1
                    for p in set(names_in(t, consts)):
                        raw[p].add(f.name)
                elif (isinstance(n, ast.Call)
                      and getattr(n.func, "id", None) in helpers and n.args):
                    idioms["helper"] += 1
                    for p in set(names_in(n.args[0], consts)):
                        raw[p].add(f.name)
                elif (isinstance(n, ast.Call)
                      and getattr(getattr(n.func, "value", None), "id", None)
                      in ("aj", "atomic_json")
                      and getattr(n.func, "attr", None) in ("update", "write", "locked")
                      and n.args):
                    for p in set(names_in(n.args[0], consts)):
                        guarded[p].add(f.name)
        return raw, guarded, idioms

    def test_no_json_path_has_two_raw_writers(self):
        raw, _, _ = self._write_sites(Path(__file__).resolve().parent)
        shared = {p: mods for p, mods in raw.items()
                  if len(mods) > 1 and p not in self.ALLOWED_MULTI_WRITER}
        self.assertEqual(
            {}, shared,
            "these JSON files are written by more than one module with an "
            "unlocked, non-atomic truncating write — the shape that lost 193 of "
            "200 concurrent messages from the email buffer:\n" +
            "\n".join(f"  {p}: {', '.join(sorted(m))}"
                      for p, m in sorted(shared.items())))

    def test_no_guarded_path_is_also_written_raw(self):
        """A lock only some writers take is not a lock.

        This is the failure the plain multi-writer count cannot see: one module
        does the careful locked read-modify-write, another truncates the same
        file underneath it, and every count in the sweep reads 1.
        """
        raw, guarded, _ = self._write_sites(Path(__file__).resolve().parent)
        mixed = {p: (sorted(guarded[p]), sorted(raw[p]))
                 for p in guarded if raw.get(p)}
        self.assertEqual(
            {}, mixed,
            "these paths are guarded by atomic_json in one module and truncated "
            "raw in another — the lock protects nothing:\n" +
            "\n".join(f"  {p}: guarded by {g}, raw in {r}"
                      for p, (g, r) in sorted(mixed.items())))

    def test_the_sweep_can_still_see_every_write_idiom(self):
        """A guard that silently stops resolving write sites passes forever."""
        raw, guarded, idioms = self._write_sites(Path(__file__).resolve().parent)
        self.assertGreater(
            len(raw), 40,
            f"the AST sweep resolved only {len(raw)} write sites — it has gone "
            f"blind, so its zero-shared-writers verdict means nothing")
        self.assertTrue(guarded, "the sweep no longer recognises atomic_json")
        for idiom in ("with_open", "bare_open", "write_text"):
            self.assertGreater(
                idioms[idiom], 0,
                f"the sweep resolved zero `{idiom}` writes. Either the firm has "
                f"none left (delete this assertion) or the matcher for it broke "
                f"— and a second writer using it would now be invisible. "
                f"Counts: {dict(idioms)}")

    def test_no_locked_region_nests_another(self):
        """flock is per open file description, so a nested update self-deadlocks."""
        import atomic_json as aj
        root = Path(__file__).resolve().parent
        offenders = []

        def is_aj_ctx(node):
            return (isinstance(node, ast.Call)
                    and getattr(node.func, "attr", None) in ("update", "locked")
                    and getattr(getattr(node.func, "value", None), "id", None)
                    in ("aj", "atomic_json"))

        for f in sorted(root.rglob("*.py")):
            if "__pycache__" in str(f) or f.name == "test_pipeline_smoke.py":
                continue
            try:
                tree = ast.parse(f.read_text())
            except (SyntaxError, UnicodeDecodeError, OSError):
                continue
            for outer in ast.walk(tree):
                if not (isinstance(outer, ast.With)
                        and any(is_aj_ctx(i.context_expr) for i in outer.items)):
                    continue
                for stmt in outer.body:
                    for inner in ast.walk(stmt):
                        if isinstance(inner, ast.With) and any(
                                is_aj_ctx(i.context_expr) for i in inner.items):
                            offenders.append(f"{f.name}:{inner.lineno}")
        self.assertEqual([], offenders,
                         f"nested atomic_json context(s) — each one blocks "
                         f"forever on the lock its own caller holds: {offenders}")
        self.assertIn("NOT REENTRANT", Path(aj.__file__).read_text(),
                      "the non-reentrancy must stay documented at the source")


class TestHygieneRefusesAnOverBroadMatcher(unittest.TestCase):
    """Closing is the expensive direction, so R1's blunt matcher gets a cap.

    A hand-written `{"match": "stale"}` would have closed several hundred
    unrelated live rows in a single run, and a wrongly-closed issue vanishes
    with nobody left to look for it.
    """

    def setUp(self):
        import tracker_hygiene as th
        self.th = th
        self.td = tempfile.mkdtemp()
        os.makedirs(os.path.join(self.td, "data"))
        self.p = patch.object(th, "DATA", Path(self.td) / "data")
        self.p.start()

    def tearDown(self):
        self.p.stop()
        shutil.rmtree(self.td, ignore_errors=True)

    def _write(self, issues, registry):
        d = Path(self.td) / "data"
        (d / "issue_tracker.json").write_text(json.dumps(issues))
        (d / "resolution_registry.json").write_text(json.dumps(registry))

    def _rows(self):
        return json.loads((Path(self.td) / "data" / "issue_tracker.json").read_text())

    def test_an_exact_signature_closes_only_its_own_condition(self):
        import issue_tracker as it
        rows = [{"issue_id": f"ISS-{n}", "status": "OPEN",
                 "title": f"data/a.json is {n}h old",
                 "signature": it.condition_signature("data/a.json is 1h old")}
                for n in range(3)]
        rows.append({"issue_id": "ISS-9", "status": "OPEN", "title": "data/b.json is 5h old",
                     "signature": it.condition_signature("data/b.json is 5h old")})
        self._write(rows, [{"signature": it.condition_signature("data/a.json is 7h old"),
                            "note": "producer rescheduled", "date": "2026-08-23"}])
        res = self.th.run()
        self.assertEqual(res["flipped"], 3)
        self.assertEqual([r["status"] for r in self._rows()],
                         ["resolved", "resolved", "resolved", "OPEN"])

    def test_a_matcher_wider_than_the_cap_closes_nothing(self):
        rows = [{"issue_id": f"ISS-{n}", "status": "OPEN",
                 "title": f"agent_{n} produced stale output"}
                for n in range(self.th.R1_MAX_PER_MATCHER + 5)]
        self._write(rows, [{"match": "stale", "note": "fixed the scheduler",
                            "date": "2026-08-23"}])
        res = self.th.run()
        self.assertEqual(res["flipped"], 0)
        self.assertIn("stale", res["over_broad"])
        self.assertTrue(all(r["status"] == "OPEN" for r in self._rows()))

    def test_a_narrow_matcher_still_works(self):
        rows = [{"issue_id": "ISS-1", "status": "OPEN", "title": "canary_agent produced stale output"},
                {"issue_id": "ISS-2", "status": "OPEN", "title": "hr_agent produced stale output"}]
        self._write(rows, [{"match": "canary_agent", "note": "rescheduled", "date": "2026-08-23"}])
        res = self.th.run()
        self.assertEqual(res["flipped"], 1)
        self.assertEqual([r["status"] for r in self._rows()], ["resolved", "OPEN"])

    def test_the_report_distinguishes_an_empty_registry_from_a_quiet_one(self):
        """'0 verified-closed' must not read the same with and without input."""
        self._write([{"issue_id": "ISS-1", "status": "OPEN", "title": "x"}], [])
        self.assertEqual(self.th.run()["registry_size"], 0)
        self._write([{"issue_id": "ISS-1", "status": "OPEN", "title": "x"}],
                    [{"match": "nomatch", "note": "n", "date": "d"}])
        self.assertEqual(self.th.run()["registry_size"], 1)

    def test_a_registry_close_stamps_resolved_at(self):
        """Without it, get_stale_issues and the archiver cannot tell it is finished."""
        self._write([{"issue_id": "ISS-1", "status": "OPEN", "title": "canary is broken"}],
                    [{"match": "canary", "note": "n", "date": "d"}])
        self.th.run()
        self.assertTrue(self._rows()[0].get("resolved_at"))



class TestAReaderTakesOnlyKeysItsProducerWrites(unittest.TestCase):
    """A key its producer never writes is `.get()`'s default, forever, in silence.

    THE ESCAPE (2026-08-27). morning_briefing.py is the Chairman's one daily
    window into a 155-agent firm, and 31 of its ~100 read sites named keys no
    producer has ever written. The brief had been reporting Market "unknown",
    HR 0 agents (real: 67), the board meeting 999h stale (real: written that
    afternoon), CVaR 0.00% (real: $2,064), win rate 0 (real: 23.7%), and an
    Operations Director panel — all ten of its reads wrong — that had never
    once displayed a true value. Nothing threw. Nothing logged. No file was
    empty. Every number was present in the artifact under a different name.

    The same sweep then found the fifth reader to invent its own contract
    against the canary: deputy_monitor's CRITICAL "canary stuck RED" board
    escalation, dead two ways at once (see the test below).

    These tests are AST- and artifact-based, never grep: this file and the
    modules under test are full of postmortem comments that name the very keys
    a text search would look for, so a grep would pass on the prose while the
    code stayed broken.
    """

    @classmethod
    def setUpClass(cls):
        import wiring_audit
        cls.wa = wiring_audit

    # ── the mechanism works, on every host, artifacts or not ────────────────
    def _sandbox(self, module_src: str, artifacts: dict, producer_src: str = None):
        d = tempfile.mkdtemp()
        (Path(d) / "data").mkdir()
        (Path(d) / "reader_mod.py").write_text(module_src)
        # CONDITIONAL_KEYS names board_meeting.py; a missing producer voids the
        # exemption, which would pollute every sandbox assertion. Supply a stub
        # that really does write those keys unless a test is about that.
        (Path(d) / "board_meeting.py").write_text(
            producer_src if producer_src is not None
            else "d = {}\nd['board_override'] = True\nd['pdo_signal'] = 'DEPLOY_MORE'\n")
        for name, doc in artifacts.items():
            (Path(d) / "data" / name).write_text(json.dumps(doc))
        self.addCleanup(shutil.rmtree, d, ignore_errors=True)
        return d

    LOADER = ("import json\n"
              "def _safe_load(p):\n"
              "    try:\n"
              "        with open(p) as fh:\n"
              "            return json.load(fh)\n"
              "    except Exception:\n"
              "        return {}\n")

    def test_it_catches_a_key_the_artifact_does_not_have(self):
        """The floor: without this the whole check could be a no-op and pass."""
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("nope", 0)\n',
            {"a.json": {"real_key": 1}})
        v, resolved, _unj, stale = self.wa.reader_key_contract(base=d)
        self.assertEqual([], stale, "stub producer should keep exemptions live")
        self.assertEqual(1, len(v), "a dead read site was not detected: %r" % (v,))
        self.assertEqual(["nope"], v[0]["reads"])
        self.assertEqual("data/a.json", v[0]["artifact"])
        self.assertGreaterEqual(resolved, 1)

    def test_a_key_that_is_present_is_not_flagged(self):
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("real_key", 0)\n',
            {"a.json": {"real_key": 1}})
        v, resolved, _u, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual([], v)
        self.assertEqual(1, resolved)

    def test_a_fallback_chain_is_one_decision_not_two_sites(self):
        """`x.get("a", x.get("b", 0))` with `b` present is NOT a defect.

        Counting the inner call as its own site reported 16 phantom defects on
        the first run of this check — enough noise to bury the 31 real ones.
        """
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("gone", x.get("real_key", 0))\n',
            {"a.json": {"real_key": 1}})
        v, _r, _u, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual([], v, "a satisfied fallback arm was reported: %r" % (v,))

    def test_a_chain_with_every_key_absent_is_still_a_defect(self):
        """The ops-director shape: `.get("floor_status", .get("status", "UNKNOWN"))`
        where the artifact has neither."""
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("gone", x.get("also_gone", 0))\n',
            {"a.json": {"real_key": 1}})
        v, _r, _u, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual(1, len(v))
        self.assertEqual(["gone", "also_gone"], v[0]["reads"])

    def test_a_fallback_arm_on_another_object_is_not_judged(self):
        """`cap.get("deployed_pct", other["x"]["deployed_pct"])` — absence from
        `cap` is not a defect when a different object supplies the value, and
        this checker cannot see into that object."""
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\nother = {"k": 5}\n'
            'y = x.get("gone", other.get("k", 0))\n',
            {"a.json": {"real_key": 1}})
        v, _r, unj, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual([], v, "an unjudgeable site was judged: %r" % (v,))
        self.assertGreaterEqual(unj, 1, "it should be COUNTED as unjudgeable, not ignored")

    def test_a_list_artifact_is_not_judged(self):
        """data/cit_pending_proposals.json is a list; no element stands for the
        schema, and those reads are dead branches behind an isinstance guard."""
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("proposals", [])\n',
            {"a.json": [{"id": 1}, {"id": 2}]})
        v, _r, _u, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual([], v)

    def test_an_absent_artifact_is_not_a_pass_or_a_failure(self):
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/never_written.json")\ny = x.get("k", 0)\n',
            {})
        v, resolved, _u, _s = self.wa.reader_key_contract(base=d)
        self.assertEqual([], v)
        self.assertEqual(0, resolved, "an unproduced artifact must not count as evidence")

    # ── the exemption cannot outlive its justification ──────────────────────
    def test_an_exemption_dies_with_the_write_that_justified_it(self):
        """An allowlist is where a real bug hides. Each entry names the module
        that conditionally writes the key and is VOID unless it really does —
        so you cannot silence this check by exempting a key nobody writes."""
        d = self._sandbox(
            self.LOADER + 'x = _safe_load("data/a.json")\ny = x.get("board_override", 0)\n',
            {"a.json": {"real_key": 1}},
            producer_src="# board_meeting no longer writes it\n")
        v, _r, _u, stale = self.wa.reader_key_contract(base=d)
        self.assertIn(("board_override", "board_meeting.py"), stale)
        self.assertEqual(1, len(v), "a voided exemption must re-expose the key")

    def test_a_missing_producer_voids_the_exemption(self):
        """'I could not check' must never read as 'confirmed fine'."""
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, ignore_errors=True)
        (Path(d) / "data").mkdir()
        (Path(d) / "reader_mod.py").write_text(self.LOADER)
        _v, _r, _u, stale = self.wa.reader_key_contract(base=d)
        self.assertEqual({"board_override", "pdo_signal"}, {s[0] for s in stale})

    def test_every_exemption_names_a_reason(self):
        for key, val in self.wa.CONDITIONAL_KEYS.items():
            self.assertEqual(2, len(val), "%s: want (producer, why)" % key)
            self.assertTrue(val[0].endswith(".py"), "%s: producer must be a module" % key)
            self.assertGreater(len(val[1]), 30, "%s: reason too thin to review" % key)

    # ── and it is actually judging this firm ────────────────────────────────
    def test_the_firm_has_no_dead_read_sites(self):
        v, resolved, _u, stale = self.wa.reader_key_contract()
        self.assertEqual([], stale, "stale exemption(s): %r" % (stale,))
        self.assertEqual([], v, "dead read site(s):\n" + "\n".join(
            "  %s:%s reads %s off %s (has %s)"
            % (x["module"], x["line"], " | ".join(x["reads"]), x["artifact"],
               ", ".join(x["has"])) for x in v))
        # Vacuity floor. EVERY artifact these readers touch is gitignored, so a
        # fresh clone resolves zero sites and would bank a green that means "no
        # evidence". Only demand the floor on a host that has actually run.
        if (Path("data/canary_state.json").exists()
                and Path("data/ops_director_report.json").exists()):
            self.assertGreater(
                resolved, 60,
                "only %d site(s) resolved on a host WITH artifacts — measured 115 "
                "here and 136 on the VM, so the resolver has broken and this "
                "check is now judging almost nothing" % resolved)

    def test_the_ops_director_panel_reads_keys_that_producer_writes(self):
        """Pin the worst of the 31 by name: this panel was wrong in all ten fields."""
        prod = ast.parse(Path("operations_director.py").read_text())
        written = {k for k in ("supervised_agents", "agent_status", "flags",
                               "summary", "generated_at")
                   if self.wa._module_writes_key(prod, k)}
        self.assertEqual(
            {"supervised_agents", "agent_status", "flags", "summary", "generated_at"},
            written, "the ops-director brief no longer writes what the panel reads")
        brief = Path("morning_briefing.py").read_text()
        tree = ast.parse(brief)
        # the panel's dict, located structurally — not by matching comment prose
        panel = None
        for n in ast.walk(tree):
            if (isinstance(n, ast.Assign) and isinstance(n.value, ast.Dict)
                    and any(self.wa._const_str(k) == "floor_status" for k in n.value.keys
                            if k is not None)):
                panel = n.value
        self.assertIsNotNone(panel, "the ops_director panel has moved or gone")
        src = ast.unparse(panel)
        for dead in ("total_agents_supervised", "agent_issues", "floor_directive",
                     "issues_found\"", "total_issues"):
            self.assertNotIn(dead, src,
                             "the panel is reading %r again, a key nothing writes" % dead)

    def test_the_canary_red_escalation_can_actually_fire(self):
        """An alarm whose trigger value cannot occur is not an alarm.

        deputy_monitor's CRITICAL escalation read `alert_level` and
        `generated_at` off canary_state.json, which carries neither — so the
        level was the literal "GREEN" and the age the empty-timestamp sentinel,
        and `"GREEN" == "RED"` and `inf < 1` were each independently always
        False. The firm's most severe automatic escalation, wired to nothing.

        So this does not check that the keys look right. It lifts the real
        branch condition out of the real file and evaluates it, and separately
        confirms "RED" is a value the canary can actually emit.
        """
        import canary_agent
        self.assertIn("RED", canary_agent.ALERTING_LEVELS,
                      "RED is not a level the canary emits — the trigger cannot occur")

        tree = ast.parse(Path("deputy_monitor.py").read_text())
        fn = next((n for n in ast.walk(tree)
                   if isinstance(n, ast.FunctionDef) and n.name == "_escalation_sweep"), None)
        self.assertIsNotNone(fn, "_escalation_sweep has been renamed")
        conds = [n.test for n in ast.walk(fn) if isinstance(n, ast.If)
                 and "canary_level" in ast.unparse(n.test)]
        self.assertEqual(1, len(conds), "expected exactly one canary escalation branch")
        cond = ast.unparse(conds[0])

        # it must ask the one supported accessor, not re-read the state file
        body = ast.unparse(fn)
        self.assertIn("load_active_alert", body,
                      "the escalation no longer routes through the canary's accessor")
        self.assertNotIn("canary_state.json", body,
                         "it is reading the state file again — that records the last "
                         "level SEEN, which stays RED long after an episode clears")

        red = {"canary_level": "RED", "red_mins": 45.0, "board_answered": False}
        self.assertTrue(eval(cond, {}, dict(red)),
                        "a RED alert 45 min old with no board response does NOT "
                        "trigger the escalation: %s" % cond)
        for change in ({"canary_level": "GREEN"}, {"red_mins": 5.0},
                       {"board_answered": True}):
            ns = dict(red); ns.update(change)
            self.assertFalse(eval(cond, {}, ns),
                             "the branch still fires with %r — it is not "
                             "discriminating: %s" % (change, cond))

class TestAReviewerWithNoCallerIsNotAControl(unittest.TestCase):
    """A control that cannot be reached, crashes unseen, or reports agreement
    it never checked. Three ways the IRM's proactive audits were decorative.

    THE ESCAPE (2026-08-27). Jack got an email saying the pipeline was down.
    It wasn't — `wakeup_recovery.py` called
    `buffer_email("wakeup_recovery", subject, body)` against the signature
    `(subject, html_body, sender_name)`. Three strings, three string
    parameters, every one shifted a place left. The mail arrived with the
    subject "wakeup_recovery", a body containing only the real subject line,
    and the whole recovery report — 1 job re-run, 10 already fresh, 0 failed —
    stranded in `sender_name`. Nothing raised. The one email whose entire job
    is to say whether the firm came back could not say it.

    Pulling that thread found the same shape three more times in the IRM:

      1. `_review_pdo` was unreachable. Reviewers are dispatched on the
         `sender_name` of an outgoing email, and the PDO sends none — it writes
         capital_efficiency_report.json six times a day and stops. So a
         reviewer existed for a producer that never speaks, and
         `creative_agent.metrics_for_pdo`, which builds its input, had zero
         callers on either host.
      2. `_review_cit` WAS reached — daily, from run_irm_daily — and raised
         TypeError on its first statement (`len()` of an int; cit_director
         writes `board_proposals` as a COUNT). The handler was `logger.debug`
         while the module configures INFO, so it emitted nothing at all. A
         broken control and a quiet one were indistinguishable for its whole
         life.
      3. The audits' verdicts were never persisted: irm_daily_check.json is
         written ~80 lines BEFORE the audit block, so the CIT audit reached the
         Chairman's email and no programmatic reader of the file it appeared to
         belong to.

    AST-based, never grep: this file and irm_review_agent.py both contain
    postmortem prose naming `logger.debug`, `_review_pdo` and `buffer_email`,
    so a text search would match the explanation and miss the code.
    """

    DISPATCH = "_dispatch_review_inner"

    @classmethod
    def setUpClass(cls):
        cls.here = Path(__file__).resolve().parent
        cls.tree = ast.parse((cls.here / "irm_review_agent.py").read_text())
        cls.fns = {n.name: n for n in ast.walk(cls.tree)
                   if isinstance(n, ast.FunctionDef)}

    # ── 1. reachability ─────────────────────────────────────────────────────
    def _dispatch_aliases(self):
        """reviewer -> the sender_name strings that route to it."""
        aliases = {}
        fn = self.fns.get(self.DISPATCH)
        self.assertIsNotNone(fn, "the IRM dispatch function was renamed")
        for node in ast.walk(fn):
            if (isinstance(node, ast.If) and isinstance(node.test, ast.Compare)
                    and node.test.ops and isinstance(node.test.ops[0], ast.In)):
                names = [e.value for e in getattr(node.test.comparators[0], "elts", [])
                         if isinstance(e, ast.Constant) and isinstance(e.value, str)]
                for stmt in node.body:
                    for c in ast.walk(stmt):
                        if (isinstance(c, ast.Call) and isinstance(c.func, ast.Name)
                                and c.func.id.startswith("_review_")):
                            aliases.setdefault(c.func.id, []).extend(names)
        return aliases

    def _direct_callers(self):
        """Reviewers called from somewhere OTHER than the dispatch table.

        Excluding the dispatch function matters: counting its own calls made
        all ten reviewers look reachable, which is the vacuous version of this
        test and the first answer the sweep gave.
        """
        out = set()
        for name, fn in self.fns.items():
            if name == self.DISPATCH:
                continue
            for n in ast.walk(fn):
                if (isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                        and n.func.id.startswith("_review_")):
                    out.add(n.func.id)
        return out

    def _emitted_sender_names(self):
        """Every `sender_name="..."` literal any module in the firm passes."""
        emitted = set()
        for p in sorted(self.here.glob("*.py")):
            try:
                t = ast.parse(p.read_text())
            except Exception:
                continue
            for n in ast.walk(t):
                if isinstance(n, ast.Call):
                    for kw in n.keywords:
                        if (kw.arg == "sender_name" and isinstance(kw.value, ast.Constant)
                                and isinstance(kw.value.value, str)):
                            emitted.add(kw.value.value)
        return emitted

    def test_every_specialised_reviewer_is_reachable(self):
        reviewers = {n for n in self.fns if n.startswith("_review_")}
        self.assertGreaterEqual(len(reviewers), 8,
                                "reviewer sweep found almost nothing — it is not resolving")
        aliases = self._dispatch_aliases()
        direct  = self._direct_callers()
        emitted = self._emitted_sender_names()
        self.assertGreater(len(emitted), 10,
                           "sender_name sweep found almost nothing — it is not resolving")

        unreachable = []
        for r in sorted(reviewers):
            if r == "_review_generic":
                continue          # the else-branch fallback; reached by definition
            if r in direct:
                continue          # called outright, e.g. the proactive daily audits
            if any(a in emitted for a in aliases.get(r, [])):
                continue          # some producer really does send under that name
            unreachable.append("%s (aliases: %s)" % (r, ",".join(aliases.get(r, [])) or "none"))

        self.assertEqual([], unreachable,
                         "IRM reviewer(s) that nothing can ever call — a reviewer for a "
                         "producer that never speaks is not a control, it is dead code "
                         "that reads as coverage:\n  " + "\n  ".join(unreachable))

    def test_the_reachability_sweep_can_actually_fail(self):
        """The check above is worthless if it cannot detect a dead reviewer."""
        emitted = self._emitted_sender_names()
        ghost_aliases = ["nobody_sends_this_name_xyz"]
        self.assertFalse(any(a in emitted for a in ghost_aliases),
                         "the negative control's alias is actually emitted — pick another")
        # And the real table must not be empty, or the loop above skips everything.
        self.assertTrue(self._dispatch_aliases(),
                        "no dispatch aliases resolved — the reachability test is vacuous")

    # ── 2. a failed reviewer must leave a trace ─────────────────────────────
    def _proactive_tries(self):
        """The *innermost* try guarding each proactive `_review_*` call.

        Every enclosing Try would also match — including the one wrapping the
        whole of run_irm_daily, whose handler is a general fallback and
        legitimately does not record per-reviewer state. Asserting against that
        one is the over-broad version of this test; it fails on correct code,
        which is worse than not testing at all.
        """
        fn = self.fns.get("run_irm_daily")
        self.assertIsNotNone(fn, "run_irm_daily was renamed")

        parent = {}
        for node in ast.walk(fn):
            for child in ast.iter_child_nodes(node):
                parent[child] = node

        out = {}
        for c in ast.walk(fn):
            if not (isinstance(c, ast.Call) and isinstance(c.func, ast.Name)
                    and c.func.id.startswith("_review_")):
                continue
            # Climb to the nearest Try that has this call in its `body`, not in
            # one of its handlers.
            node, prev = parent.get(c), c
            while node is not None:
                if isinstance(node, ast.Try) and any(
                        prev is s or prev in set(ast.walk(s)) for s in node.body):
                    out.setdefault(id(node), (node, set()))[1].add(c.func.id)
                    break
                node, prev = parent.get(node), node
        return list(out.values())

    def test_a_failed_proactive_audit_is_not_swallowed_at_debug(self):
        offenders = []
        for node, calls in self._proactive_tries():
            for h in node.handlers:
                levels = {c.func.attr for c in ast.walk(h)
                          if isinstance(c, ast.Call) and isinstance(c.func, ast.Attribute)
                          and isinstance(c.func.value, ast.Name) and c.func.value.id == "logger"}
                if levels and levels <= {"debug"}:
                    offenders.append("%s at line %d only logger.debug()s"
                                     % (",".join(sorted(calls)), h.lineno))
        self.assertEqual([], offenders,
                         "a proactive reviewer's failure handler logs only at DEBUG while "
                         "the module configures INFO, so a control that crashes every day "
                         "produces no output whatsoever:\n  " + "\n  ".join(offenders))

    def test_a_failed_proactive_audit_is_recorded_on_disk(self):
        """An absent log line is not evidence. The failure must become a fact."""
        tries = self._proactive_tries()
        self.assertTrue(tries, "no proactive reviewer is wrapped in a try at all")
        for node, calls in tries:
            for h in node.handlers:
                touches = any(isinstance(s, ast.Subscript) and isinstance(s.value, ast.Name)
                              and s.value.id == "irm_output" for s in ast.walk(h))
                self.assertTrue(
                    touches,
                    "the failure handler for %s logs but never writes to irm_output, so "
                    "nothing downstream — and no future audit — can tell a broken control "
                    "from a quiet one" % ",".join(sorted(calls)))

    # ── 3. the audits must reach the artifact, not just the email ───────────
    def test_the_audit_artifact_is_written_after_the_audits_run(self):
        """irm_daily_check.json had exactly one write, ~80 lines too early.

        Six modules read that file (board_meeting, hr_agent, fi_executor,
        logic_team, morning_briefing, freshness_sentinel). None could see the
        CIT audit's verdict: it did not exist yet when the file was written.
        """
        fn = self.fns["run_irm_daily"]
        review_lines = [n.lineno for n in ast.walk(fn)
                        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name)
                        and n.func.id.startswith("_review_")]
        self.assertTrue(review_lines, "no proactive reviewer is called at all")

        # A write is either a literal open(...,'w') on the path or a call to a
        # persist helper — resolve both rather than betting on one spelling.
        write_lines = []
        for n in ast.walk(fn):
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name):
                if n.func.id == "open" and any(
                        isinstance(a, ast.Constant) and "irm_daily_check" in str(a.value)
                        for a in n.args):
                    write_lines.append(n.lineno)
                elif "persist" in n.func.id:
                    write_lines.append(n.lineno)
        self.assertTrue(write_lines, "run_irm_daily no longer writes irm_daily_check.json")
        self.assertGreater(
            max(write_lines), max(review_lines),
            "every write of irm_daily_check.json happens BEFORE the last proactive audit, "
            "so the audit's verdict is emailed and then dropped — invisible to every "
            "programmatic reader of the file it appears to be part of")

    def test_the_audit_section_renders_its_omissions(self):
        """An omission is what a control says when it could NOT check.

        The renderer loaded `omissions`, counted them toward "is there anything
        to say", then never emitted them — so a review whose only output was an
        omission produced a header and nothing under it. The severest thing a
        reviewer can say, rendered as silence.
        """
        import irm_review_agent as I
        html = I._build_cit_audit_html({"verdict": "v",
                                        "omissions": ["UNIQUE_OMISSION_MARKER_9f2a"]})
        self.assertIn("UNIQUE_OMISSION_MARKER_9f2a", html,
                      "an audit's omissions are collected but never rendered")

    # ── 4. a cross-check that did not happen is not agreement ───────────────
    def test_review_pdo_does_not_report_agreement_it_never_checked(self):
        import irm_review_agent as I
        ctx = {"risk_assessment": {"risk_level": "MODERATE"},
               "account": {"cash": 1000, "portfolio_value": 10000}}

        blind = I._review_pdo("t", {}, ctx)          # unreadable report
        self.assertTrue(blind["omissions"],
                        "an unreadable PDO report produced no omission — the reviewer "
                        "silently skipped every branch and reported nothing wrong")
        joined = " ".join(blind["findings"] + [blind["verdict"]]).lower()
        self.assertNotIn("aligned", joined,
                         "the PDO reviewer reports the signals are ALIGNED when it could "
                         "not read the signal at all — the substituted default is itself "
                         "a verdict (`fallback-that-means-act`)")
        self.assertNotEqual("HIGH", blind["confidence"],
                            "HIGH confidence in a cross-check that never ran")

        stale = I._review_pdo("t", {"PDO Signal": "NEAR_OPTIMAL",
                                    "Report Age Hours": 500.0}, ctx)
        self.assertTrue(stale["omissions"],
                        "a 500h-old deployment signal was cross-checked against today's "
                        "risk level with no caveat")

        fresh = I._review_pdo("t", {"PDO Signal": "NEAR_OPTIMAL",
                                    "Report Age Hours": 2.0}, ctx)
        self.assertEqual([], fresh["omissions"],
                         "a fresh, consistent PDO signal must NOT raise an omission — an "
                         "alarm that is always on is an alarm nobody reads")
        self.assertTrue(fresh["commendations"])

    def test_review_cit_survives_both_artifact_shapes(self):
        """cit_backlog/pending/sensitive are top-level LISTS on both hosts.

        Three sites called .get() straight on them (AttributeError on a list),
        and cit_evening_report writes `board_proposals` as an int, so len() blew
        up on the first statement. Both shapes must work.
        """
        import irm_review_agent as I
        ctx = {"risk_assessment": {"risk_level": "MODERATE"}, "account": {}}
        rows = [{"title": "t%d" % i, "confidence": 90, "description": "d"}
                for i in range(5)]

        shapes = {
            "list-shaped (production, both hosts)": {
                "cit_evening_report.json":    {"board_proposals": 14, "backlog": 122,
                                               "proposals": rows},
                "cit_pending_proposals.json": rows,
                "cit_backlog.json":           rows,
                "cit_sensitive.json":         rows,
            },
            "dict-wrapped (the shape the code assumed)": {
                "cit_evening_report.json":    {"board_proposals": rows, "backlog": rows},
                "cit_pending_proposals.json": {"proposals": rows},
                "cit_backlog.json":           {"items": rows},
                "cit_sensitive.json":         {"items": rows},
            },
            "null confidence (207 of 500 real rows)": {
                "cit_evening_report.json":    {"board_proposals": 1, "proposals": rows},
                "cit_backlog.json":           [{"title": "x", "confidence": None}],
            },
        }
        cwd = os.getcwd()
        for label, artifacts in shapes.items():
            d = tempfile.mkdtemp()
            self.addCleanup(shutil.rmtree, d, ignore_errors=True)
            (Path(d) / "data").mkdir()
            for name, doc in artifacts.items():
                (Path(d) / "data" / name).write_text(json.dumps(doc))
            try:
                os.chdir(d)
                out = I._review_cit("t", {}, ctx)
            except Exception as e:
                self.fail("_review_cit raised %s on %s — this is the crash that ran daily "
                          "and was logged at DEBUG: %s" % (type(e).__name__, label, e))
            finally:
                os.chdir(cwd)
            self.assertTrue(out.get("findings"),
                            "_review_cit produced no findings on %s — it returned a "
                            "well-formed empty verdict, which reads as 'nothing wrong'"
                            % label)

    # ── 5. the transposed-argument guard at the choke point ─────────────────
    def test_a_document_in_the_sender_slot_is_flagged(self):
        """The original bug, replayed. Every legitimate sender_name in this firm
        is a short identifier; a multi-line report there is a transposition."""
        import email_buffer as EB
        d = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, d, ignore_errors=True)
        os.makedirs(os.path.join(d, "data"))
        old = EB.BUFFER_PATH
        EB.BUFFER_PATH = os.path.join(d, "data", "email_buffer.json")
        self.addCleanup(lambda: setattr(EB, "BUFFER_PATH", old))

        EB.buffer_email("wakeup_recovery", "Pipeline Recovery Complete",
                        "Re-ran: main.py\nAlready fresh: 10 jobs\nFailed: 0\n" * 3)
        EB.buffer_email(subject="Pipeline Recovery Complete",
                        html_body="<pre>ok</pre>", sender_name="wakeup_recovery")

        rows = json.loads(Path(EB.BUFFER_PATH).read_text())
        self.assertEqual(2, len(rows), "the guard dropped mail — it must never do that")
        self.assertTrue(rows[0].get("arg_order_suspect"),
                        "a 147-char multi-line sender_name was accepted without comment; "
                        "this is exactly the call that mailed Jack a mangled all-clear")
        self.assertFalse(rows[1].get("arg_order_suspect", False),
                         "the guard fires on a correct call — it would cry wolf daily")

    def test_the_transposition_guard_runs_before_the_urgent_early_return(self):
        """_is_urgent returns early AND reads both swapped strings, so a guard
        placed after it cannot see the calls most likely to be wrong."""
        fn = [n for n in ast.walk(ast.parse((self.here / "email_buffer.py").read_text()))
              if isinstance(n, ast.FunctionDef) and n.name == "buffer_email"][0]
        urgent = [n.lineno for n in ast.walk(fn) if isinstance(n, ast.Call)
                  and isinstance(n.func, ast.Name) and n.func.id == "_is_urgent"]
        guard  = [n.lineno for n in ast.walk(fn) if isinstance(n, ast.Name)
                  and n.id == "_arg_order_suspect"]
        self.assertTrue(urgent, "buffer_email no longer has an urgent early-return")
        self.assertTrue(guard, "the transposed-argument guard is gone")
        self.assertLess(min(guard), min(urgent),
                        "the argument-order guard sits after the urgent early-return, so "
                        "urgent mail bypasses it entirely")

    def test_wakeup_recovery_reports_through_a_named_body(self):
        """The specific call that started this, pinned at its site."""
        tree = ast.parse((self.here / "wakeup_recovery.py").read_text())
        calls = [n for n in ast.walk(tree) if isinstance(n, ast.Call)
                 and isinstance(n.func, ast.Name) and n.func.id == "buffer_email"]
        self.assertTrue(calls, "wakeup_recovery no longer buffers its report at all — the "
                               "pipeline's own all-clear would go nowhere")
        for c in calls:
            self.assertIn("html_body", {k.arg for k in c.keywords},
                          "wakeup_recovery's buffer_email call passes its body positionally "
                          "again; it is the one call site in the firm that got this wrong, "
                          "and it mailed Jack a report with no report in it")
            self.assertEqual([], c.args,
                             "positional args reintroduced at the site of the original "
                             "transposition")


class TestAFailedControlCannotRenderAsACleanOne(unittest.TestCase):
    """A control that CRASHED and a control that found NOTHING, byte-identical.

    `_review_cit` raised TypeError on its first statement every day for weeks.
    Nobody noticed, because the call site was:

        cit_review = {}
        try:
            cit_review = _review_cit(...)
        except Exception as e:
            logger.debug(f"  [IRM Daily] CIT audit skipped: {e}")
        ... f"<div>{cit_review}</div>" ...

    The module configures INFO, so `debug()` emitted nothing at all. The audit
    section of the Chairman's email rendered from the empty default and looked
    exactly like a clean audit. An absent log line is not evidence.

    The defect needs FOUR parts together, and this pins all four:
      1. an EMPTY default ({} / [] / "" / None / 0 / False)
      2. reassigned from a CONTROL call inside a try
      3. whose handler is silent -- nothing reaches INFO, nothing re-raises
      4. and the variable is READ after the try, into a report / email / artifact

    Fewer parts is a different thing and is deliberately NOT flagged:
    (1)(2)(3) without (4) is a discarded result; (2)(3)(4) with a NON-empty
    default is `fallback-that-means-act`, which has its own guard.

    Swept firm-wide when this was written: 0 instances across 3,010 functions.
    The IRM was the only one. The three synthetic tests below exist because a
    sweep that reports zero is worthless until it is shown able to report one
    -- an earlier version of this sweep returned a clean zero purely because
    it never examined the dispatch it was written for.
    """

    CONTROL = re.compile(
        r"audit|review|verif|validat|_law|sentinel|guard|reconcil|coheren|"
        r"invariant|census|detect|watchdog|_check|check_|assess|scan", re.I)
    SILENT_CALLS = {"debug"}

    # ── predicates ───────────────────────────────────────────────────────
    @classmethod
    def _handler_is_silent(cls, h):
        """Nothing an operator can see, and no re-raise."""
        for st in h.body:
            if isinstance(st, (ast.Pass, ast.Continue, ast.Break, ast.Return)):
                continue
            if isinstance(st, ast.Raise):
                return False
            if isinstance(st, ast.Expr) and isinstance(st.value, ast.Call):
                f = st.value.func
                attr = (f.attr if isinstance(f, ast.Attribute)
                        else f.id if isinstance(f, ast.Name) else "")
                if attr in cls.SILENT_CALLS:
                    continue
                return False        # print / info / warning / error / anything
            if isinstance(st, (ast.Assign, ast.AugAssign, ast.AnnAssign)):
                continue            # recorded into a local: still invisible
            return False
        return True

    @staticmethod
    def _is_empty_default(node):
        if isinstance(node, ast.Constant):
            return node.value in (None, "", 0) or node.value is False
        if isinstance(node, ast.Dict):
            return not node.keys
        if isinstance(node, (ast.List, ast.Set)):
            return not node.elts
        if (isinstance(node, ast.Call) and isinstance(node.func, ast.Name)
                and node.func.id in ("dict", "list", "set") and not node.args):
            return True
        return False

    @staticmethod
    def _call_name(node):
        if not isinstance(node, ast.Call):
            return None
        f = node.func
        if isinstance(f, ast.Name):
            return f.id
        if isinstance(f, ast.Attribute):
            return f.attr
        return None

    @classmethod
    def _hits_in_tree(cls, tree):
        """Function names exhibiting the full 4-part shape."""
        out = []
        for fn in ast.walk(tree):
            if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue

            empty_at = {}                                        # (1)
            for n in ast.walk(fn):
                if isinstance(n, ast.Assign) and cls._is_empty_default(n.value):
                    for t in n.targets:
                        if isinstance(t, ast.Name):
                            empty_at.setdefault(t.id, n.lineno)
                elif (isinstance(n, ast.AnnAssign) and n.value is not None
                        and cls._is_empty_default(n.value)
                        and isinstance(n.target, ast.Name)):
                    empty_at.setdefault(n.target.id, n.lineno)

            for node in ast.walk(fn):
                if not isinstance(node, ast.Try):
                    continue
                if not any(cls._handler_is_silent(h) for h in node.handlers):
                    continue                                     # (3)
                for st in node.body:                             # (2)
                    if not isinstance(st, ast.Assign):
                        continue
                    cn = cls._call_name(st.value)
                    if not cn or not cls.CONTROL.search(cn):
                        continue
                    for t in st.targets:
                        if not isinstance(t, ast.Name) or t.id not in empty_at:
                            continue
                        if empty_at[t.id] > st.lineno:
                            continue      # default set AFTER: not this shape
                        end = getattr(node, "end_lineno", st.lineno)
                        read_after = any(                        # (4)
                            isinstance(u, ast.Name) and u.id == t.id
                            and isinstance(u.ctx, ast.Load) and u.lineno > end
                            for u in ast.walk(fn))
                        if read_after:
                            out.append((fn.name, t.id, cn, st.lineno))
        return out

    # ── the firm-wide invariant ──────────────────────────────────────────
    def test_no_control_result_is_silently_failed_and_rendered_from_empty(self):
        root = Path(__file__).resolve().parent
        skip = {"venv", ".venv", "site-packages", "__pycache__",
                "node_modules", ".git"}
        offenders, n_files = [], 0
        for p in sorted(root.rglob("*.py")):
            if any(part in skip for part in p.parts) or p.name.startswith("test_"):
                continue
            try:
                tree = ast.parse(p.read_text())
            except Exception:
                continue
            n_files += 1
            for fnname, var, cn, ln in self._hits_in_tree(tree):
                offenders.append("%s:%d  %s(): %s = %s(...) -- silent handler, "
                                 "empty default, rendered downstream"
                                 % (p.relative_to(root), ln, fnname, var, cn))

        self.assertGreater(n_files, 100, "sweep found almost no modules to read")
        self.assertEqual(
            [], offenders,
            "A control failure here is indistinguishable from a clean run.\n"
            "Raise the handler to logger.warning AND record the failure on "
            "disk (see irm_review_agent.run_irm_daily's reviewer_failures), or "
            "let it raise. Do not leave it at debug():\n  " +
            "\n  ".join(offenders))

    # ── the sweep must be able to fail ───────────────────────────────────
    _PRE_FIX_IRM = '''
import logging
logger = logging.getLogger(__name__)
def run_daily():
    cit_review = {}
    try:
        cit_review = _review_cit("x", {}, {})
    except Exception as e:
        logger.debug(f"skipped: {e}")
    return f"<div>{cit_review}</div>"
'''

    _VISIBLE_HANDLER = '''
import logging
logger = logging.getLogger(__name__)
def run_daily():
    cit_review = {}
    try:
        cit_review = _review_cit("x", {}, {})
    except Exception as e:
        logger.warning(f"FAILED: {e}")
    return f"<div>{cit_review}</div>"
'''

    _RESULT_DISCARDED = '''
import logging
logger = logging.getLogger(__name__)
def run_daily():
    cit_review = {}
    try:
        cit_review = _review_cit("x", {}, {})
    except Exception as e:
        logger.debug(f"skipped: {e}")
    return "done"
'''

    def test_the_sweep_fires_on_the_shape_it_was_built_from(self):
        hits = self._hits_in_tree(ast.parse(self._PRE_FIX_IRM))
        self.assertEqual(
            ["run_daily"], [h[0] for h in hits],
            "The sweep no longer detects the exact pre-fix IRM call site, so "
            "its firm-wide zero means nothing.")

    def test_a_visible_handler_is_not_flagged(self):
        self.assertEqual(
            [], self._hits_in_tree(ast.parse(self._VISIBLE_HANDLER)),
            "logger.warning() makes the failure visible -- flagging it would "
            "make the invariant unsatisfiable and it would be deleted.")

    def test_a_discarded_result_is_not_flagged(self):
        self.assertEqual(
            [], self._hits_in_tree(ast.parse(self._RESULT_DISCARDED)),
            "Nothing reads the variable, so no reader is misled. That is a "
            "different defect (dead result), not this one.")


class TestAMutationAfterTheLastWriteIsNotRecorded(unittest.TestCase):
    """A verdict attached to a dict that was already written to disk.

    `irm_review_agent.run_irm_daily` persisted `irm_output` exactly once, ~80
    lines before the CIT audit block ran, so the audit's verdict reached the
    Chairman's email and NO reader of data/irm_daily_check.json.
    `hr_agent.run_hr_review` was worse: SIX audits -- attendance,
    ratchet_integrity, retirement_coverage, roster_coverage, sweep_queue,
    performance_ledger -- were attached ~320 lines after its only write, and
    both callers (main.py and this module's __main__) read only
    firm_health_score and action_required, which come from the dict literal
    BEFORE that write. Six controls, each built to close a specific past
    escape, producing verdicts that reached nothing at all.

    Four more of the same shape were found in the same sweep, all receipts:
    metric_sanity_sentinel (bugs_filed, decisions_filed),
    data_integrity_sentinel (chairman_filed), fundamentals_sanity (bugs_filed),
    derive_risk_limits (queued), backup_data (pruned -- the record of which
    backups were deleted).

    The invariant: within a function, if a name is handed to something that
    writes it, that name's CONTENTS must not change afterwards. The accepted
    fixes are a second write, or a persist closure called on both sides of the
    mutation. Both are recognised below.
    """

    PERSIST_FN = re.compile(
        # dump(?!s): json.dumps(X) serialises X, it does not write it.
        r"^_*(json_)?(dump(?!s)|save|persist|write|store|flush|commit)", re.I)
    MUTATORS = {"update", "setdefault", "append", "extend", "pop", "clear"}

    @classmethod
    def _persisted(cls, fn):
        """name -> [lineno...] where it is handed to something that writes.

        Key "*" collects ZERO-ARG persist calls. Those are closures over the
        thing they write (`_persist_irm_output()`), so the name never appears
        at the call site and an argument scan sees nothing -- which is how an
        earlier version of this check kept reporting the two call sites it had
        already been used to fix.
        """
        out = {}
        for n in ast.walk(fn):
            if not isinstance(n, ast.Call):
                continue
            f = n.func
            nm = (f.attr if isinstance(f, ast.Attribute)
                  else f.id if isinstance(f, ast.Name) else "")
            if not nm or not cls.PERSIST_FN.match(nm):
                continue
            if not n.args and not n.keywords:
                out.setdefault("*", []).append(n.lineno)
                continue
            for a in list(n.args) + [k.value for k in n.keywords]:
                for sub in ast.walk(a):
                    if isinstance(sub, ast.Name) and isinstance(sub.ctx, ast.Load):
                        out.setdefault(sub.id, []).append(n.lineno)
        return out

    @classmethod
    def _mutations(cls, fn):
        out = {}
        for n in ast.walk(fn):
            if isinstance(n, ast.Assign):
                for t in n.targets:
                    if isinstance(t, (ast.Subscript, ast.Attribute)) \
                            and isinstance(t.value, ast.Name):
                        out.setdefault(t.value.id, []).append(n.lineno)
            elif isinstance(n, ast.AugAssign):
                t = n.target
                if isinstance(t, ast.Subscript) and isinstance(t.value, ast.Name):
                    out.setdefault(t.value.id, []).append(n.lineno)
            elif (isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute)
                    and n.func.attr in cls.MUTATORS
                    and isinstance(n.func.value, ast.Name)):
                out.setdefault(n.func.value.id, []).append(n.lineno)
        return out

    @classmethod
    def _hits_in_tree(cls, tree):
        out = []
        for fn in ast.walk(tree):
            if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            pers, muts = cls._persisted(fn), cls._mutations(fn)
            wildcard = max(pers.get("*", [0]))
            for name, plines in pers.items():
                if name == "*":
                    continue
                last = max(plines + [wildcard])
                after = sorted(l for l in muts.get(name, []) if l > last)
                if after:
                    out.append((fn.name, name, last, after))
        return out

    def test_nothing_is_mutated_after_the_last_write_that_records_it(self):
        root = Path(__file__).resolve().parent
        skip = {"venv", ".venv", "site-packages", "__pycache__",
                "node_modules", ".git"}
        offenders, n_files = [], 0
        for p in sorted(root.rglob("*.py")):
            if any(part in skip for part in p.parts) or p.name.startswith("test_"):
                continue
            try:
                tree = ast.parse(p.read_text())
            except Exception:
                continue
            n_files += 1
            for fnname, name, last, after in self._hits_in_tree(tree):
                offenders.append(
                    "%s  %s(): %s written last at L%d, then mutated at L%s"
                    % (p.relative_to(root), fnname, name, last,
                       ", L".join(str(a) for a in after[:4])))

        self.assertGreater(n_files, 100, "sweep found almost no modules to read")
        self.assertEqual(
            [], offenders,
            "These changes never reach disk. Write again after the mutation, "
            "or move the write below it:\n  " + "\n  ".join(offenders))

    # ── the check must be able to fail, and must accept both fixes ───────
    _PRE_FIX = '''
def run():
    report = {"a": 1}
    with open("x.json", "w") as f:
        json.dump(report, f)
    report["audit"] = do_audit()
    return report
'''
    _FIXED_CLOSURE = '''
def run():
    report = {"a": 1}
    def _persist_report():
        with open("x.json", "w") as f:
            json.dump(report, f)
    _persist_report()
    report["audit"] = do_audit()
    _persist_report()
    return report
'''
    _FIXED_SECOND_WRITE = '''
def run():
    report = {"a": 1}
    REPORT.write_text(json.dumps(report))
    report["filed"] = file_it()
    REPORT.write_text(json.dumps(report))
    return report
'''
    _CLOSURE_THEN_MUTATE = '''
def run():
    report = {"a": 1}
    def _persist_report():
        with open("x.json", "w") as f:
            json.dump(report, f)
    _persist_report()
    report["audit"] = do_audit()
    return report
'''
    _DUMPS_IS_NOT_A_WRITE = '''
def run():
    c = {"a": 1}
    s = "x" + json.dumps(c["nums"])
    c["routed"] = True
    return c
'''

    def test_it_fires_on_the_shape_it_was_built_from(self):
        self.assertTrue(
            self._hits_in_tree(ast.parse(self._PRE_FIX)),
            "No longer detects the pre-fix IRM/HR call site, so the firm-wide "
            "zero above means nothing.")

    def test_a_closure_called_on_both_sides_is_accepted(self):
        self.assertEqual([], self._hits_in_tree(ast.parse(self._FIXED_CLOSURE)))

    def test_a_plain_second_write_is_accepted(self):
        self.assertEqual([], self._hits_in_tree(ast.parse(self._FIXED_SECOND_WRITE)))

    def test_the_closure_exemption_does_not_cover_a_later_mutation(self):
        """The dangerous over-broad reading of the "*" key.

        Crediting a zero-arg persist to every name must exonerate mutations
        BEFORE that call, never after it -- otherwise one `_persist_x()`
        anywhere in a function silences the whole function.
        """
        self.assertTrue(
            self._hits_in_tree(ast.parse(self._CLOSURE_THEN_MUTATE)),
            "A mutation after the last persist closure is still unrecorded.")

    def test_serialising_is_not_writing(self):
        self.assertEqual(
            [], self._hits_in_tree(ast.parse(self._DUMPS_IS_NOT_A_WRITE)),
            "json.dumps(X) builds a string; it does not persist X. Counting it "
            "made rd_price_theory_agent._route read as defective when its real "
            "writer persists a different name entirely.")


class TestEveryClassificationIsCounted(unittest.TestCase):
    """A partition that produces five buckets must not report three.

    `board_meeting._synthesise_consensus` has always assigned FIVE values to
    `classification` and returned THREE counts. Those three numbers are the
    firm's entire summary of what its board decided: the board email headline,
    the board log line, the board report on disk, morning_briefing, canary_agent
    and main.py all render them, and nothing else.

    On 2026-08-27 the board took NINE actions and every one of those readers
    said "0 unanimous, 2 majority, 1 vetoed". The six it did not mention were
    all SPLIT, and they included ADD_VAR_CIRCUIT_BREAKER and
    REGIME_ADAPTIVE_STOP_LOSS. UNVOTED is the worse of the two, because it is
    not a decision at all — `n_agents == 0` means no voting member cast a vote —
    and it rendered identically to "never came up"
    (memory a-decision-recorded-nowhere: "the board said no" and "we lost it"
    must not be one state).

    The same shape sat in `operations_director.build_floor_brief`: four
    statuses written, three counted, so an agent whose report failed to parse
    was in no bucket and the floor-status line did not sum to the roster.

    These tests pin the general property, not the specific fix: whatever the
    producer can emit, the tally must have a bucket for, and the residual must
    be reported rather than absorbed.
    """

    # ── the producers, and the tuples that are supposed to enumerate them ──
    PARTITIONS = (
        ("board_meeting", "_synthesise_consensus", "classification",
         "CLASSIFICATIONS"),
        ("operations_director", "build_floor_brief", "status",
         "FLOOR_STATUSES"),
    )

    @staticmethod
    def _fn(mod, name):
        import importlib, inspect, textwrap
        m = importlib.import_module(mod)
        return m, ast.parse(textwrap.dedent(
            inspect.getsource(getattr(m, name)))).body[0]

    @staticmethod
    def _str_lits(node):
        """The string constants an expression can evaluate to, one level deep.

        Handles a bare constant and a ternary of constants. Anything else
        returns empty, which makes this test blind rather than wrong — and the
        emptiness is caught by the `assertTrue(emitted)` guard below.
        """
        if isinstance(node, ast.Constant) and isinstance(node.value, str):
            return {node.value}
        if isinstance(node, ast.IfExp):
            out = set()
            for side in (node.body, node.orelse):
                if isinstance(side, ast.Constant) and isinstance(side.value, str):
                    out.add(side.value)
            return out
        return set()

    @classmethod
    def _emitted(cls, fn, var):
        """String literals the function assigns to `var`, or to a dict key `var`.

        AST, not grep: this file and both modules carry postmortem comments
        naming every one of these literals, so a text search would find them
        whether or not the code still produced them.

        One level of local indirection is resolved, because that is how the
        real producers are written:
            status = "STALE" if stale else "OK"   →  {"status": status}
        Without it the sweep sees only the literals written inline at the dict
        and reports two live buckets as dead — which is what it did first.
        """
        local = {}                     # local name -> {literals}
        for n in ast.walk(fn):
            if isinstance(n, ast.Assign):
                lits = cls._str_lits(n.value)
                if lits:
                    for t in n.targets:
                        if isinstance(t, ast.Name):
                            local.setdefault(t.id, set()).update(lits)

        out = set(local.get(var, set()))
        for n in ast.walk(fn):
            if isinstance(n, ast.Dict):
                for k, v in zip(n.keys, n.values):
                    if not (isinstance(k, ast.Constant) and k.value == var):
                        continue
                    out |= cls._str_lits(v)
                    if isinstance(v, ast.Name):
                        out |= local.get(v.id, set())
        return out

    def test_every_emitted_label_has_a_bucket(self):
        for mod, fnname, var, tupname in self.PARTITIONS:
            with self.subTest(module=mod):
                m, fn = self._fn(mod, fnname)
                emitted = self._emitted(fn, var)
                self.assertTrue(
                    emitted, f"{mod}.{fnname} assigns no {var} literal — the "
                             "test can no longer see the producer")
                declared = set(getattr(m, tupname))
                self.assertEqual(
                    emitted, declared,
                    f"{mod}.{tupname} must name exactly the {var} values "
                    f"{fnname} can emit. Only-emitted: "
                    f"{sorted(emitted - declared)} (produced, in no bucket). "
                    f"Only-declared: {sorted(declared - emitted)} (a bucket "
                    "for something nothing produces).")

    def test_the_board_tally_buckets_every_action_and_reports_the_residual(self):
        import board_meeting as bm
        actions = [{"classification": c} for c in bm.CLASSIFICATIONS]
        actions.append({"classification": "NOT_A_REAL_CLASS"})
        actions.append({})                      # classification absent entirely
        c = bm.count_by_classification({"actions": actions})

        for k in bm.CLASSIFICATIONS:
            self.assertEqual(1, c[k], f"{k} must be counted exactly once")
        self.assertEqual(2, c["unclassified"],
                         "an unknown class and a missing class are both residual")
        self.assertEqual(len(actions), c["total"])
        self.assertEqual(
            c["total"],
            sum(c[k] for k in bm.CLASSIFICATIONS) + c["unclassified"],
            "buckets + residual must equal the agenda, or the headline is not "
            "an account of the meeting")

    def test_the_floor_tally_buckets_every_agent_and_reports_the_residual(self):
        import operations_director as od
        st = {f"a{i}": {"status": s} for i, s in enumerate(od.FLOOR_STATUSES)}
        st["bogus"] = {"status": "NOT_A_REAL_STATUS"}
        st["empty"] = {}
        c = od.count_by_status(st)

        for k in od.FLOOR_STATUSES:
            self.assertEqual(1, c[k], f"{k} must be counted exactly once")
        self.assertEqual(2, c["unknown"])
        self.assertEqual(len(st), c["total"])
        self.assertEqual(
            c["total"], sum(c[k] for k in od.FLOOR_STATUSES) + c["unknown"],
            "floor buckets + residual must equal the supervised roster")

    def test_the_residual_is_reported_not_asserted(self):
        """It must survive a sixth label, loudly.

        Raising on an unknown classification would take the board meeting down
        over a reporting defect. Silently dropping it is how this bug lived.
        The third option — count it, name it, warn — is the only one that
        neither hides the problem nor becomes the problem.
        """
        import board_meeting as bm, operations_director as od
        try:
            c = bm.count_by_classification(
                {"actions": [{"classification": "SIXTH"}]})
        except Exception as e:                              # pragma: no cover
            self.fail(f"an unknown classification must not raise: {e!r}")
        self.assertEqual(1, c["unclassified"])
        self.assertEqual(1, c["total"])

        c2 = od.count_by_status({"x": {"status": "FIFTH"}})
        self.assertEqual(1, c2["unknown"])

    def test_the_tally_names_every_nonzero_bucket(self):
        import board_meeting as bm
        text = bm.consensus_tally({"actions": [
            {"classification": "SPLIT"}, {"classification": "UNVOTED"},
            {"classification": "WAT"}]})
        for want in ("1 split", "1 never voted on", "1 UNCLASSIFIED"):
            self.assertIn(want, text,
                          f"consensus_tally hid a non-zero bucket: {text!r}")
        self.assertIn("3 action(s)", text)

    # ── the render sites ──────────────────────────────────────────────────
    RENDERERS = ("board_meeting", "canary_agent", "main", "morning_briefing")
    _COUNT_KEYS = {"unanimous_count", "majority_count", "vetoed_count"}
    _COMPLETING = {"split_count", "unvoted_count", "consensus_tally",
                   "count_by_classification"}

    def test_no_render_site_reports_three_of_the_five(self):
        """Structural, per-function, over every module that renders the tally.

        This is why the defect survived so long: the three-number line was
        duplicated at nine call sites in six modules, so completing it meant
        editing all nine, and nobody did. The fix is a single renderer
        (`consensus_tally`), and this test is what stops a tenth partial copy
        from being written — a function that reads one of the three counts must
        also reach for the two that were missing, or go through the renderer.

        Reads only, via AST: `{"unanimous_count": ...}` as a dict KEY is a
        producer writing the field, not a reader rendering it, and is ignored.
        """
        import importlib, inspect, textwrap

        def _read_keys(node):
            out = set()
            for n in ast.walk(node):
                if isinstance(n, ast.Subscript) and isinstance(
                        n.slice, ast.Constant) and isinstance(n.slice.value, str):
                    out.add(n.slice.value)
                elif (isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute)
                      and n.func.attr == "get" and n.args
                      and isinstance(n.args[0], ast.Constant)
                      and isinstance(n.args[0].value, str)):
                    out.add(n.args[0].value)
                elif isinstance(n, ast.Name):
                    out.add(n.id)
                elif isinstance(n, ast.Attribute):
                    out.add(n.attr)
            return out

        offenders = []
        for mod in self.RENDERERS:
            src = inspect.getsource(importlib.import_module(mod))
            tree = ast.parse(textwrap.dedent(src))
            for fn in ast.walk(tree):
                if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    continue
                seen = _read_keys(fn)
                if not (seen & self._COUNT_KEYS):
                    continue
                if seen & self._COMPLETING:
                    continue
                offenders.append(f"{mod}.{fn.name} (line {fn.lineno})")

        self.assertEqual(
            [], offenders,
            "these functions render the board tally without SPLIT/UNVOTED and "
            "without going through consensus_tally, so they under-report the "
            f"meeting: {offenders}")


class TestAnUnreadableReportIsNotAHealthyOne(unittest.TestCase):
    """The one condition the handler existed to catch could not reach it.

    `operations_director.build_floor_brief` wraps its per-agent read in
    `try/except` and records `status: "ERROR"` in the handler. But the read
    went through a `_safe_load` that swallowed every exception and returned
    `{}` — so a truncated or half-written report produced an empty dict, which
    has no timestamp key, which took the `Timestamp unknown` branch and was
    filed as **OK**. The handler was unreachable for the failure it was for.

    Same shape as memory fallback-that-means-act: the constant a degraded read
    substitutes is itself a decision, and `{}` here decided "healthy".
    """

    def test_a_corrupt_report_is_ERROR_not_OK(self):
        import importlib, json as _json, os as _os, tempfile
        od = importlib.import_module("operations_director")

        cwd = _os.getcwd()
        with tempfile.TemporaryDirectory() as td:
            _os.makedirs(_os.path.join(td, "data"))
            with open(_os.path.join(td, "data", "good.json"), "w") as f:
                _json.dump({"generated_at": datetime.now().isoformat()}, f)
            with open(_os.path.join(td, "data", "corrupt.json"), "w") as f:
                f.write('{"generated_at": tru')       # half-written, as observed

            agents, files = od.SUPERVISED_AGENTS, od.SUPERVISED_FILES
            try:
                _os.chdir(td)
                od.SUPERVISED_AGENTS = ["Good", "Corrupt", "Absent"]
                od.SUPERVISED_FILES = {"Good": "data/good.json",
                                       "Corrupt": "data/corrupt.json",
                                       "Absent": "data/nope.json"}
                brief = od.build_floor_brief()
            finally:
                _os.chdir(cwd)
                od.SUPERVISED_AGENTS, od.SUPERVISED_FILES = agents, files

        got = {k: v["status"] for k, v in brief["agent_status"].items()}
        self.assertEqual(
            {"Good": "OK", "Corrupt": "ERROR", "Absent": "NO_REPORT"}, got,
            "a report that cannot be parsed must not be indistinguishable from "
            f"one that parsed cleanly: {got}")

        c = brief["status_counts"]
        self.assertEqual(1, c["ERROR"])
        self.assertEqual(
            c["total"], sum(c[k] for k in od.FLOOR_STATUSES) + c["unknown"],
            "the floor-status line must sum to the supervised roster")
        self.assertIn("1 unreadable", brief["summary"],
                      f"ERROR must appear in the summary line: "
                      f"{brief['summary']!r}")


class TestATruncatedStampIsAWrongAge(unittest.TestCase):
    """`fromisoformat(ts[:19])` on an offset-bearing stamp is a wrong number.

    `"2026-08-27T15:30:05+00:00"[:19]` is `"2026-08-27T15:30:05"` — a NAIVE
    datetime holding UTC digits, subtracted from a naive LOCAL `now()`. On this
    Mac the age comes back exactly one UTC offset too SMALL (4h in EDT, 5h in
    EST — the error changes with daylight saving). On the VM, where TZ=UTC, the
    identical line is correct. Green in production, wrong on the machine we
    audit from: memory host_divergence_is_a_bug_class.

    The direction is what makes it dangerous. Too SMALL means an artifact whose
    true age is in (12, 16] hours reports as <= 12 and clears a 12-hour
    freshness gate — a four-hour window every cycle where a producer that has
    already missed its run reads as healthy. Measured 2026-08-27: 16 aware
    artifacts misdated, every one by exactly -4.00h, `international_report.json`
    reading 1.04h at a true age of 5.04h.

    Two things are pinned here, and the second matters more than the first:

      1. The BEHAVIOUR — the converted helpers return the true age of an aware
         stamp. A ratchet alone would pass on code that removed the slice and
         broke differently.
      2. The RATCHET — the count of surviving truncating parses may shrink,
         never grow.

    Why removing `[:19]` is not the fix: `datetime.now() - fromisoformat(
    "...+00:00")` raises `TypeError: can't subtract offset-naive and
    offset-aware datetimes`, and nearly every one of these sites sits in a bare
    `except Exception`. The age then is not wrong, it is ABSENT — and absent
    reads as fine (the stale flag stays False). A wrong number can be argued
    with; silence cannot. `time_utils` handles both.
    """

    # Sites still parsing with a truncating slice, measured 2026-08-27 after
    # converting the 14 helper choke points and the two live sites in
    # apex_improvement_board (44 -> 26). Every one of the 26 was checked against
    # the producer it actually reads, and every one of those files is naive on
    # disk today, so all 26 are LATENT: correct now, wrong the day their
    # producer starts writing an offset — which
    # `test_the_baseline_sites_are_latent_not_live` is here to catch.
    # Shrink-only.
    MODE_A_BASELINE = 26

    # Only cuts that provably land at or after the seconds field, where the
    # ONLY thing a slice can remove is an offset or a fraction. `[:10]` is
    # deliberate date extraction and is not this bug.
    TRUNCATING_CUTS = (19, 26)

    # ---- detector -------------------------------------------------------
    @staticmethod
    def _datetime_aliases(tree):
        """Local names bound to the datetime CLASS, and to the MODULE.

        Alias-resolved rather than grepped because this class is reached five
        ways in this codebase — `datetime.`, `_dt2.`, `dt.datetime.`,
        `_date_ctx.`, `datetime.datetime.` — and because `date.fromisoformat`
        must be excluded: a date has no offset, so there is nothing to discard
        and nothing to raise. Getting that exclusion wrong is the difference
        between a 184-row aggregate and a 28-row finding.
        """
        cls, mod = set(), set()
        for n in ast.walk(tree):
            if isinstance(n, ast.ImportFrom) and n.module == "datetime":
                for a in n.names:
                    if a.name == "datetime":
                        cls.add(a.asname or a.name)
            elif isinstance(n, ast.Import):
                for a in n.names:
                    if a.name == "datetime":
                        mod.add(a.asname or a.name)
        return cls, mod

    @classmethod
    def _is_datetime_fromisoformat(cls, func, dt_cls, dt_mod):
        if not (isinstance(func, ast.Attribute)
                and func.attr == "fromisoformat"):
            return False
        v = func.value
        if isinstance(v, ast.Name):
            return v.id in dt_cls
        if isinstance(v, ast.Attribute) and isinstance(v.value, ast.Name):
            return v.value.id in dt_mod and v.attr == "datetime"
        return False

    @classmethod
    def _truncating_cut(cls, arg):
        """N for a bare `<expr>[:N]` with N in TRUNCATING_CUTS, else None."""
        if isinstance(arg, ast.Subscript) and isinstance(arg.slice, ast.Slice):
            sl = arg.slice
            if (sl.lower is None and sl.step is None
                    and isinstance(sl.upper, ast.Constant)
                    and sl.upper.value in cls.TRUNCATING_CUTS):
                return sl.upper.value
        return None

    @classmethod
    def _offenders(cls):
        out = []
        root = Path(__file__).parent
        skip = {"venv", ".venv", "site-packages", "__pycache__",
                "node_modules", ".git"}
        for p in sorted(root.rglob("*.py")):
            if any(part in skip for part in p.parts):
                continue
            if p.name.startswith("test_"):
                continue
            try:
                src = p.read_text()
                tree = ast.parse(src)
            except Exception:
                continue
            dt_cls, dt_mod = cls._datetime_aliases(tree)
            if not (dt_cls or dt_mod):
                continue
            lines = src.splitlines()
            for n in ast.walk(tree):
                if not (isinstance(n, ast.Call) and n.args):
                    continue
                if not cls._is_datetime_fromisoformat(n.func, dt_cls, dt_mod):
                    continue
                cut = cls._truncating_cut(n.args[0])
                if cut is None:
                    continue
                out.append((str(p.relative_to(root)), n.lineno, cut,
                            lines[n.lineno - 1].strip()[:88]))
        return out

    # ---- 1. behaviour ---------------------------------------------------
    def test_an_aware_stamp_gets_its_true_age(self):
        """Zone-independent: asserted against an offset-bearing stamp.

        The pre-push gate runs this suite twice, once in the local zone and
        once under TZ=UTC. A test written against a naive local stamp would
        pass in both zones while proving nothing, because the bug is invisible
        wherever the local offset is zero. Building the stamp from
        `now(timezone.utc)` makes the expected answer 7.0 in EVERY zone.
        """
        from datetime import timezone as _tz
        import time_utils

        for spelling in ("+00:00", "Z"):
            stamp = (datetime.now(_tz.utc) - timedelta(hours=7)).isoformat()
            if spelling == "Z":
                stamp = stamp.replace("+00:00", "") + "Z"
            got = time_utils.age_hours(stamp, default=None)
            self.assertIsNotNone(got, f"{spelling}: aware stamp must parse")
            self.assertAlmostEqual(
                7.0, got, places=2,
                msg=f"{spelling}: an aware stamp 7h old must read 7h in any "
                    f"zone, got {got}")

            # The old spelling, for contrast — wrong by exactly the local UTC
            # offset. Under TZ=UTC that offset is 0 and the two agree, which is
            # precisely why this bug survived on the VM.
            off = datetime.now().astimezone().utcoffset().total_seconds() / 3600
            old = (datetime.now()
                   - datetime.fromisoformat(stamp.replace("Z", "+00:00")[:19])
                   ).total_seconds() / 3600
            self.assertAlmostEqual(
                7.0 + off, old, places=2,
                msg="the truncating spelling should be wrong by exactly the "
                    f"local UTC offset ({off}h); if this fails the model of "
                    "the bug is wrong, not the fix")

    def test_a_naive_stamp_is_unchanged(self):
        """The 104 naive artifacts must keep reading exactly as before."""
        import time_utils
        stamp = (datetime.now() - timedelta(hours=3)).isoformat()
        self.assertAlmostEqual(3.0, time_utils.age_hours(stamp, default=None),
                               places=2)

    def test_an_unreadable_stamp_returns_the_callers_own_default(self):
        """`age_hours` must not pick a substitute for the caller.

        The value put in place of an age you could not compute IS a decision
        (memory fallback-that-means-act): for a staleness gate a huge number
        raises the alarm, for a cooldown the same huge number PERMITS the
        action. Identical form, opposite meaning — so the helper refuses to
        guess and the caller has to name it where a reviewer can see it.
        """
        import time_utils
        for bad in ("", None, "not a date", "2026-13-45T99:99:99", [], {}):
            self.assertIsNone(time_utils.age_hours(bad),
                              f"{bad!r} must yield None, not a number")
            self.assertEqual(-1.0, time_utils.age_hours(bad, default=-1.0))
        self.assertTrue(time_utils.is_stale("garbage", 1.0),
                        "a stamp we cannot read is not evidence of freshness")

    def test_a_future_stamp_is_negative_not_zero(self):
        """Clamping to 0 makes clock skew indistinguishable from 'just now'."""
        import time_utils
        from datetime import timezone as _tz
        stamp = (datetime.now(_tz.utc) + timedelta(hours=2)).isoformat()
        self.assertAlmostEqual(-2.0, time_utils.age_hours(stamp, default=None),
                               places=2)
        # `timedelta.days` floors toward -inf, so an hour of skew read as
        # "-1 days" — a day in the past. age_days is a float and does not.
        near = (datetime.now(_tz.utc) + timedelta(hours=1)).isoformat()
        self.assertGreater(time_utils.age_days(near, default=None), -1.0)

    def test_the_converted_helpers_date_an_aware_stamp_correctly(self):
        """The choke points themselves, not just the library underneath.

        These are the functions the 44 sites collapsed into. Each is exercised
        on a real aware stamp: before the conversion every one of them returned
        the age minus the local UTC offset.
        """
        from datetime import timezone as _tz
        import importlib
        stamp = (datetime.now(_tz.utc) - timedelta(hours=9)).isoformat()

        hours_helpers = [
            ("agent_inbox", "_age_hours"),
            ("agent_meeting", "_age_hours"),
            ("cit_pipeline_integrity_agent", "_ts_age_hours"),
            ("deputy_monitor", "_age_hours"),
            ("cit_watchdog", "_age_hours"),
        ]
        for mod_name, fn_name in hours_helpers:
            fn = getattr(importlib.import_module(mod_name), fn_name)
            self.assertAlmostEqual(
                9.0, fn(stamp), places=2,
                msg=f"{mod_name}.{fn_name} must read an aware stamp 9h old as "
                    f"9h, got {fn(stamp)}")

        days_helpers = [("fe_cit_agent", "_ts_age_days"),
                        ("board_issue_ledger", "_days_since")]
        for mod_name, fn_name in days_helpers:
            fn = getattr(importlib.import_module(mod_name), fn_name)
            self.assertAlmostEqual(
                9.0 / 24.0, fn(stamp), places=3,
                msg=f"{mod_name}.{fn_name} must read 9h as 0.375 days")

        lt = importlib.import_module("logic_team")
        self.assertEqual(0, lt._days_since(stamp),
                         "9h old is 0 whole days, not -1")

    def test_each_helper_keeps_its_own_fail_closed_constant(self):
        """A shared helper must not homogenise what 'unknown' means.

        These four modules deliberately disagree: `inf` for an inbox item that
        should expire, `9999.0` for a watchdog that must alarm, `None` for a
        ledger where an unknown age must not manufacture an escalation. The
        conversion routes them all through one parser and must NOT have routed
        them all to one answer.
        """
        import importlib
        self.assertEqual(float("inf"),
                         importlib.import_module("agent_inbox")._age_hours(""))
        self.assertEqual(float("inf"),
                         importlib.import_module("agent_meeting")._age_hours(""))
        self.assertEqual(9999.0,
                         importlib.import_module("cit_watchdog")._age_hours(""))
        self.assertIsNone(
            importlib.import_module("board_issue_ledger")._days_since(""))
        self.assertIsNone(
            importlib.import_module("logic_team")._days_since(""))

    def test_deadmans_switch_converts_rather_than_truncates(self):
        """It works in naive local on purpose — but must CONVERT to get there.

        This module subtracts producer stamps from EACH OTHER, so both sides
        need the same awareness; naive is a deliberate, documented choice
        (its docstring records three snapshot tests that failed on the UTC VM).
        `[:19]` also produced a naive datetime — but a wrong one, keeping UTC
        digits and calling them local. `as_naive_local` converts.
        """
        from datetime import timezone as _tz
        import importlib
        ds = importlib.import_module("deadmans_switch")
        aware = datetime.now(_tz.utc) - timedelta(hours=5)
        got = ds._parse(aware.isoformat())
        self.assertIsNotNone(got)
        self.assertIsNone(got.tzinfo, "the module's naive contract must hold")
        self.assertAlmostEqual(
            5.0, (datetime.now() - got).total_seconds() / 3600.0, places=2,
            msg="a naive-by-conversion stamp must still be 5h old on the local "
                f"clock, got {got}")

    # ---- 2. ratchet -----------------------------------------------------
    def test_truncating_parses_never_grow(self):
        found = self._offenders()
        if len(found) > self.MODE_A_BASELINE:
            listing = "\n".join(f"    {f}:{ln}  [:{c}]  {t}"
                                for f, ln, c, t in found)
            self.fail(
                f"{len(found)} truncating datetime parses, baseline is "
                f"{self.MODE_A_BASELINE}. `fromisoformat(ts[:19])` discards a "
                f"real UTC offset and reads one offset too NEW, which is the "
                f"direction that clears a staleness gate. Use "
                f"`time_utils.age_hours(ts, default=...)` instead — and name "
                f"the default, because it is a decision.\n{listing}")
        if len(found) < self.MODE_A_BASELINE:
            self.fail(
                f"only {len(found)} truncating parses remain (baseline "
                f"{self.MODE_A_BASELINE}) — lower MODE_A_BASELINE to "
                f"{len(found)} so the ratchet cannot drift back up. A "
                f"shrink-only baseline that is never tightened stops being a "
                f"ratchet.")

    def test_the_ratchet_can_actually_see_a_regression(self):
        """A detector nobody has watched fail is not known to work.

        Memory the-instrument-measured-itself: prove the instrument fires on a
        defect built to trip it, and prove it stays quiet on the two lookalikes
        that are NOT this bug — `date.fromisoformat` (no offset to lose) and
        `[:10]` (deliberate date extraction).
        """
        import tempfile, textwrap
        cases = [
            ("from datetime import datetime\n"
             "def f(t): return datetime.fromisoformat(t[:19])", 1, "plain"),
            ("import datetime\n"
             "def f(t): return datetime.datetime.fromisoformat(t[:26])",
             1, "module-qualified"),
            ("from datetime import datetime as _dt2\n"
             "def f(t): return _dt2.fromisoformat(t[:19])", 1, "aliased"),
            ("from datetime import date\n"
             "def f(t): return date.fromisoformat(t[:19])", 0, "date class"),
            ("from datetime import datetime\n"
             "def f(t): return datetime.fromisoformat(t[:10])", 0, "[:10]"),
            ("from datetime import datetime\n"
             "def f(t): return datetime.fromisoformat(t)", 0, "no slice"),
        ]
        with tempfile.TemporaryDirectory() as td:
            for i, (src, want, label) in enumerate(cases):
                p = Path(td) / f"m{i}.py"
                p.write_text(textwrap.dedent(src))
                tree = ast.parse(p.read_text())
                dt_cls, dt_mod = self._datetime_aliases(tree)
                n_hits = sum(
                    1 for n in ast.walk(tree)
                    if isinstance(n, ast.Call) and n.args
                    and self._is_datetime_fromisoformat(n.func, dt_cls, dt_mod)
                    and self._truncating_cut(n.args[0]) is not None)
                self.assertEqual(want, n_hits, f"detector on {label}: "
                                               f"expected {want}, got {n_hits}")

    def test_the_baseline_sites_are_latent_not_live(self):
        """Every surviving site must read a producer that is still naive.

        This is what makes 28 an acceptable place to stop rather than a
        deferral: the conversion removed every site that is wrong TODAY. If a
        producer under one of these readers starts writing offsets, this test
        is the thing that notices — the reader would go wrong silently, and the
        artifact census here would flip first.
        """
        import re as _re
        aware_pat = _re.compile(
            r'"(?:generated_at|timestamp|ts|run_at|created_at|updated_at|'
            r'buffered_at|queued_at|last_started|last_ran|last_seen)"\s*:\s*'
            r'"[^"]*\d{2}:\d{2}:\d{2}(?:\.\d+)?(?:[+-]\d{2}:?\d{2}|Z)"')
        root = Path(__file__).parent
        live = []
        for f, ln, cut, txt in self._offenders():
            win = "\n".join(
                (root / f).read_text().splitlines()[max(0, ln - 30):ln + 2])
            for name in set(_re.findall(r"([a-zA-Z0-9_]+\.json)", win)):
                p = root / "data" / name
                if p.exists() and aware_pat.search(p.read_text()[:400000]):
                    live.append(f"{f}:{ln} reads {name}, which is now AWARE")
        self.assertEqual(
            [], live,
            "a surviving truncating parse now reads an offset-bearing "
            "producer — it is silently reading one UTC offset too new and must "
            "move to time_utils.age_hours:\n  " + "\n  ".join(live))


class TestTheKalshiBuildDecisionIsRecordedNotJustMailed(unittest.TestCase):
    """The build-or-drop verdict must reach a queue, not only an inbox.

    On 2026-08-27 the three Kalshi verdicts (premise / edge / cost) were emailed
    to the Chairman on a weekly heartbeat and appeared in NO `*queue*.json`,
    `*pending*.json` or `*chairman*.json` on either host. An email has no owner,
    no clock, no status and no way to answer, so "nobody has decided whether to
    build the estimator" and "the decision was made and we lost it" were the
    same observable state — [[a-decision-recorded-nowhere]]. A queue row gets a
    20-day `chairman_decision_sla` clock and a board escalation; mail does not.

    These pin the four properties that make the row a record rather than a
    second notification.
    """

    AGG = {"n": 2007, "quote": 0.9498, "realised": 0.9337, "ci_low": 0.922,
           "ci_high": 0.9438, "mean_spread": 0.0366, "edge": 0.01603,
           "edge_low": 0.00596, "edge_high": 0.02777,
           "cost": {"maker": {"spread": 0.01829, "fee": 0.00083, "total": 0.01912},
                    "taker": {"spread": 0.03658, "fee": 0.00334, "total": 0.03992},
                    "spread": 0.01829, "fee": 0.00083, "total": 0.01912},
           "net_point": -0.00309, "net_best_case": 0.00865,
           "direction": "market OVERPRICES yes"}

    def _raise(self, path, cost_verdict="MARGINAL", agg=None, settled=2007):
        import kalshi_calibration as kk
        detail = {"settled": settled, "strata": {},
                  "aggregate": (self.AGG if agg is None else agg) if settled else None}
        return kk.queue_build_decision(
            [], path=path,
            premise=("DEAD", "premise reason", {"settled": settled}),
            proven=(False, "edge reason"),
            cost=(cost_verdict, "cost reason", detail))

    def _open(self, path):
        return [r for r in json.loads(Path(path).read_text())
                if r.get("status") == "awaiting_chairman"]

    def test_a_host_with_no_ledger_raises_nothing(self):
        """There is no state sync: the VM holds 2,007 settled rows, the Mac 0.

        A row raised from the empty side would read CANNOT_TELL and would land
        in the same list the Chairman reads as one queue, beside the VM's real
        verdict. n == 0 means "this host has no ledger", which is not an answer.
        """
        with tempfile.TemporaryDirectory() as d:
            p = str(Path(d) / "q.json")
            Path(p).write_text("[]")
            n, why = self._raise(p, "CANNOT_TELL", settled=0)
            self.assertEqual(0, n, "an empty host must not raise the decision")
            self.assertIn("not qualified", why)
            self.assertEqual([], self._open(p))

    def test_a_ledger_that_cannot_decide_still_raises(self):
        """The mirror of the above, and the one that is easy to get wrong.

        "No ledger here" is silence; "there IS a ledger and it cannot resolve"
        is a decision-relevant state and must reach an owner. Collapsing the two
        into one `if not settled` is how a control goes quiet exactly when it
        has something to say. [[verdict-with-no-consequence]]
        """
        with tempfile.TemporaryDirectory() as d:
            p = str(Path(d) / "q.json")
            Path(p).write_text("[]")
            n, _ = self._raise(p, "CANNOT_TELL", agg=None, settled=12)
            self.assertEqual(1, n, "12 settled rows that cannot decide is a "
                                   "finding, not an absence")
            self.assertEqual(1, len(self._open(p)))

    def test_a_moved_verdict_supersedes_rather_than_accumulates(self):
        """One decision, one open row — and the old one CLOSED, never dropped.

        Leaving the prior row open gives the Chairman two contradictory verdicts
        for one question, and the stale one keeps counting down toward its own
        board escalation. Deleting it instead would erase the fact that the
        reading moved, which is the same erasure the ledger exists to prevent.
        """
        with tempfile.TemporaryDirectory() as d:
            p = str(Path(d) / "q.json")
            Path(p).write_text("[]")
            self._raise(p, "MARGINAL")
            self.assertEqual(0, self._raise(p, "MARGINAL")[0],
                             "the weekly heartbeat must not re-raise an "
                             "unchanged verdict")

            harvestable = dict(self.AGG, edge_low=0.025, net_point=0.006)
            self._raise(p, "HARVESTABLE", agg=harvestable)

            rows = json.loads(Path(p).read_text())
            self.assertEqual(2, len(rows), "the superseded row is kept")
            self.assertEqual(1, len(self._open(rows and p)),
                             "exactly one open row per decision")
            closed = [r for r in rows if r.get("status") == "resolved"]
            self.assertEqual(1, len(closed))
            self.assertIn("superseded", closed[0].get("resolved_by", ""),
                          "a closed row must say what replaced it")
            self.assertIn("HARVESTABLE", closed[0].get("resolved_by", ""))

    def test_the_dedup_key_carries_all_three_verdicts(self):
        """Any one of premise / edge / cost moving must re-raise.

        The cost verdict moves independently of the other two — the spread can
        narrow UNHARVESTABLE into MARGINAL while the premise stays DEAD. A key
        built from a subset would suppress exactly the news worth having.
        """
        with tempfile.TemporaryDirectory() as d:
            p = str(Path(d) / "q.json")
            Path(p).write_text("[]")
            self._raise(p, "MARGINAL")
            key = self._open(p)[0]["dedup_key"]
            for token in ("DEAD", "NOT_PROVEN", "MARGINAL"):
                self.assertIn(token, key,
                              f"{token} is not in the dedup key, so a change "
                              f"in it would be suppressed as a duplicate")

    def test_the_row_carries_measured_numbers_not_written_ones(self):
        """Every figure comes from the detail dict, so it moves when it moves.

        `edge_versus_cost`'s docstring read 1.73c on 2026-08-26 and 1.60c on
        2026-08-27. A row that quoted a constant would put a decision in front
        of the Chairman on evidence that had already reversed.
        """
        with tempfile.TemporaryDirectory() as d:
            p = str(Path(d) / "q.json")
            Path(p).write_text("[]")
            self._raise(p, "MARGINAL")
            first = self._open(p)[0]["description"]
            self.assertIn("1.60c", first, "the measured edge must appear")
            self.assertIn("1.91c", first, "the measured cost must appear")
            self.assertIn("-0.31c", first, "the measured net must appear")

            moved = dict(self.AGG, edge=0.033, edge_low=0.025,
                         net_point=0.014, net_best_case=0.020)
            second = self._raise(p, "HARVESTABLE", agg=moved) and \
                self._open(p)[0]["description"]
            self.assertIn("3.30c", second)
            self.assertNotIn("1.60c", second,
                             "the new row is quoting the old measurement")

    def test_the_decision_is_raised_from_a_scheduled_entry_point(self):
        """A producer nobody calls is the firm's oldest bug class.

        RUN the entry point; do not read it. The first version of this test
        walked the AST for a Call node inside `main()`, and a mutation that
        wrapped the call in `if False:` still PASSED — the node was lexically
        present and permanently unreachable. That is the same defect the test
        was written to catch, wearing the test's own shape:
        [[a-union-cannot-prove-all-n]]. Reachability is a property of execution.

        The recorder means nothing is written: the behaviour of the function
        itself is pinned by the five tests above.
        """
        import io
        import kalshi_calibration as kk
        calls = []
        with patch.object(kk, "queue_build_decision",
                          lambda *a, **k: calls.append(k) or (0, "stub")), \
                patch.object(sys, "argv", ["kalshi_calibration.py", "--report"]), \
                patch("sys.stdout", io.StringIO()):
            kk.main()
        self.assertEqual(1, len(calls),
                         "`--report` did not reach queue_build_decision — the "
                         "Chairman's row exists only if someone runs it by hand")

    def test_email_verdict_queues_even_when_it_sends_nothing(self):
        """The queue is the record; the mail is the notification.

        `email_verdict` returns early when the signature is unchanged — the
        common case, by design. If the queue call sat below that return, the
        durable row would only be maintained on the runs that also sent mail,
        re-coupling the record to the notification.

        So the test drives exactly that path: seed the state file with the
        verdict this host is about to compute, so the function is guaranteed to
        take its early return, and assert the queue call happened anyway.
        Nothing is buffered and no mail can leave — the early return is above
        every `buffer_email` in the function.
        """
        import kalshi_calibration as kk
        rows = kk._load_ledger()
        premise, _, _ = kk.is_premise_alive(rows)
        proven, _ = kk.is_edge_proven(rows)
        cost, _, _ = kk.edge_versus_cost(rows)
        signature = f"{premise}|{'PROVEN' if proven else 'NOT_PROVEN'}|{cost}"

        calls = []
        with tempfile.TemporaryDirectory() as d:
            state = Path(d) / "verdict.json"
            state.write_text(json.dumps({
                "signature": signature,
                "at": datetime.now(timezone.utc).isoformat(),
                "subject": "seeded", "buffered_at": datetime.now().isoformat(),
                "delivery": "buffered"}))
            with patch.object(kk, "VERDICT_STATE", state), \
                    patch.object(kk, "queue_build_decision",
                                 lambda *a, **k: calls.append(k) or (0, "stub")):
                sent, why = kk.email_verdict(rows)

        self.assertFalse(sent, "the seeded state must force the early return, "
                               "otherwise this test proves nothing about it")
        self.assertIn("unchanged", why)
        self.assertEqual(1, len(calls),
                         "email_verdict returned early WITHOUT maintaining the "
                         "Chairman's row — on an unchanged verdict (the normal "
                         "case) the decision would go unrecorded")
        self.assertEqual({"premise", "proven", "cost"}, set(calls[0]),
                         "the three verdicts are already computed at that point "
                         "and must be passed in, not rescanned")


class TestTheChairmanInboxHearsAboutClosures(unittest.TestCase):
    """A decision already resolved upstream must not reach the board.

    `chairman_decision_queue.json` is a MIRROR of chairman_action_required.json.
    `chairman_queue.resolve()` closes a row when its condition stops being
    observed, and `chairman_queue_compactor` archives the closed row — and this
    inbox read neither. Once ingested, an item stayed `awaiting_chairman` until
    the Chairman decided it or the 20-day clock escalated it to a board vote on
    a condition that no longer existed.

    Measured 2026-08-27 on both hosts, independently: 44 of the Mac's 134
    pending items (33%) and 22 of the VM's 58 (38%) were already resolved and
    archived upstream while still counting down. Two of them were the top rows
    of the Chairman's own session banner, both marked OVERDUE.
    """

    def _env(self, d, queue, actions, archive):
        import chairman_decision_sla as sla
        p = {n: Path(d) / f"{n}.json" for n in
             ("queue", "actions", "archive", "cit")}
        p["queue"].write_text(json.dumps(queue))
        p["actions"].write_text(json.dumps(actions))
        p["archive"].write_text(json.dumps(archive))
        p["cit"].write_text("[]")
        return sla, patch.multiple(
            sla, QUEUE_PATH=p["queue"], CHAIR_ACTION=p["actions"],
            ARCHIVE_PATH=p["archive"], CIT_PENDING=p["cit"]), p

    @staticmethod
    def _item(iid, days_old=1, **kw):
        first = datetime.utcnow() - timedelta(days=days_old)
        item = {"id": iid, "severity": "MEDIUM", "description": iid,
                "status": "awaiting_chairman", "first_surfaced": first.isoformat(),
                "deadline": (first + timedelta(days=20)).isoformat()}
        item.update(kw)
        return item

    def test_a_row_the_producer_closed_leaves_the_inbox(self):
        with tempfile.TemporaryDirectory() as d:
            sla, env, p = self._env(
                d, [self._item("a"), self._item("b")],
                [{"id": "a", "status": "resolved"},
                 {"id": "b", "status": "awaiting_chairman"}], [])
            with env:
                rep = sla.run(write=True)
            self.assertEqual(1, rep["resolved_upstream"])
            self.assertEqual(["b"], [q["id"] for q in rep["pending_for_chairman"]])
            saved = {q["id"]: q for q in json.loads(p["queue"].read_text())}
            self.assertEqual("resolved_upstream", saved["a"]["status"])
            self.assertIn("never by absence", saved["a"]["resolved_by"])

    def test_a_row_the_compactor_archived_also_leaves(self):
        """The compactor moves closed rows OUT of the live file entirely.

        Reading only chairman_action_required.json would see those as missing,
        not as closed — which is the case below that must stay open.
        """
        with tempfile.TemporaryDirectory() as d:
            sla, env, _ = self._env(d, [self._item("a")], [],
                                    [{"id": "a", "status": "resolved"}])
            with env:
                rep = sla.run(write=True)
            self.assertEqual(1, rep["resolved_upstream"])
            self.assertEqual([], rep["pending_for_chairman"])

    def test_an_upstream_row_that_is_simply_GONE_stays_open(self):
        """Absence is not resolution — the half that must never be simplified.

        `chairman_queue._submit_locked` evicts a producer's least-severe rows
        past a per-source cap of 20, so a row can vanish from the upstream file
        while remaining a live, undecided question. 5 items on the Mac and 10 on
        the VM are in exactly that state. Closing on absence would delete real
        decisions on the strength of a cap.
        """
        with tempfile.TemporaryDirectory() as d:
            sla, env, _ = self._env(d, [self._item("evicted")], [], [])
            with env:
                rep = sla.run(write=True)
            self.assertEqual(0, rep["resolved_upstream"],
                             "an item with no upstream row anywhere was closed "
                             "— absence was read as resolution")
            self.assertEqual(["evicted"],
                             [q["id"] for q in rep["pending_for_chairman"]])

    def test_a_merged_item_stays_open_while_any_leg_is_open(self):
        with tempfile.TemporaryDirectory() as d:
            sla, env, _ = self._env(
                d, [self._item("m", merged_ids=["m2"])],
                [{"id": "m", "status": "resolved"},
                 {"id": "m2", "status": "awaiting_chairman"}], [])
            with env:
                rep = sla.run(write=True)
            self.assertEqual(0, rep["resolved_upstream"],
                             "one still-open leg keeps the merged decision live")

    def test_an_overdue_resolved_item_is_not_escalated_to_the_board(self):
        """The consequence, and the reason reconciliation runs BEFORE escalation.

        This is the failure the whole class describes: a 21-day-old item whose
        finding cleared last week becomes a STRATEGY proposal the board votes on.
        """
        with tempfile.TemporaryDirectory() as d:
            sla, env, p = self._env(
                d, [self._item("stale", days_old=21)],
                [{"id": "stale", "status": "resolved"}], [])
            with env:
                rep = sla.run(write=True)
            self.assertEqual([], rep["escalated_to_board"],
                             "a resolved finding was escalated to a board vote")
            self.assertEqual("[]", p["cit"].read_text().strip(),
                             "a board proposal was filed for a closed condition")

            # And the control case: same age, still open upstream -> DOES escalate.
            sla2, env2, p2 = self._env(
                d + "", [self._item("live", days_old=21)],
                [{"id": "live", "status": "awaiting_chairman"}], [])
            with env2:
                rep2 = sla2.run(write=True)
            self.assertEqual(["live"], rep2["escalated_to_board"],
                             "the SLA stopped escalating anything at all — the "
                             "fix disabled the clock instead of reconciling it")

    def test_reconciliation_is_idempotent(self):
        with tempfile.TemporaryDirectory() as d:
            sla, env, _ = self._env(d, [self._item("a")],
                                    [{"id": "a", "status": "resolved"}], [])
            with env:
                first = sla.run(write=True)["resolved_upstream"]
                second = sla.run(write=True)["resolved_upstream"]
            self.assertEqual((1, 0), (first, second),
                             "a second run re-closed an already-closed item")


if __name__ == "__main__":
    os.chdir(Path(__file__).parent)  # ensure relative paths resolve correctly
    # Load EVERY TestCase in this module.
    #
    # This used to be a hand-maintained list of 34 addTests() calls, and on
    # 2026-08-01 it did exactly what the firm's oldest bug class always does: a
    # new test class was written, imported cleanly, passed when run directly —
    # and never ran in the suite, because nobody added the line. The count stayed
    # at 273 through two full green runs. A test that is not registered does not
    # fail; it is silently absent, which is worse than a failing test because it
    # reads as coverage. Same shape as a producer whose consumer does not exist.
    #
    # loadTestsFromModule cannot drop a class, so the registration step that
    # could be forgotten no longer exists.
    loader = unittest.TestLoader()
    suite = loader.loadTestsFromModule(sys.modules[__name__])
    n_classes = len({type(t).__name__ for t in suite._tests for t in t})
    print("Discovered %d test class(es) in %s\n" % (n_classes, Path(__file__).name),
          file=sys.stderr)
    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)
    sys.exit(0 if result.wasSuccessful() else 1)
